FD.put("works.lod-1",{"works":{"lod.v01.0177":{"title":"Robert Treat Paine's Diary","author_label":"Robert Treat Paine","kind":"diary","date":"1774-10-14","date_label":"October 14, 1774","date_type":"written","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 1","source_url":"https://archive.org/details/lettersofdelegat01smit","scan_url":"https://archive.org/details/lettersofdelegat01smit/page/197","text_status":"unreviewed_ocr","editorial_source_note":"MS (MHi) . 1 For a fuller account of this meeting, see John Adams' Diary, this date.","authors":["robert-treat-paine"],"paras":[["h","Robert Treat Paine's Diary"],["p","[October 14, 1774] Fine weather. This morning visited Dr. Chevot & saw his Anatomical preparations. Dined Dr. [John] Morgan. Evening met at Carpenters Hall at the desire of some Baptists to hear their complaints of Grievances in our Province. Mr. Backus, Dr. Manning & others present.1"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v01.0230":{"title":"John Dickinson to Thomas Cushing","author_label":"John Dickinson","kind":"letter","date":"1774-12","date_label":"December 1774","date_type":"written","recipient":"Thomas Cushing","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 1","source_url":"https://archive.org/details/lettersofdelegat01smit","scan_url":"https://archive.org/details/lettersofdelegat01smit/page/264","text_status":"unreviewed_ocr","editorial_source_note":"RC (PRO: CO. 5, 118).","authors":["john-dickinson"],"paras":[["h","John Dickinson to Thomas Cushing"],["p","Dear Sir, Fairhill Deer. 11th 1774"],["p","I am much oblig'd to You for the Extract You were so kind as to inclose in your late Letter; and heartily rejoice, that I can repay in some Degree the favorable Intelligence it contain'd, by informing You, that, Yesterday our House of Representatives, taking into their Consideration, the Report of the Delegates from this Province, by a Resolve in the strongest Terms, \"approv'd of all Resolves & proceedings of the Congress, and recommended to the good People of this province, a strict Attention to and an inviolable Observation of the Matters & Things contained therein.\" A Ship sailing directly for England, a Copy of the Resolve was immediately transmitted by her. May God Almighty look down with Mercy upon Us, 8c bring our righteous Cause to a happy Conclusion. Procrastination is Preservation. States acting on the Defensive, should study for Delays. It is a melancholy Employment to peruse those various Instances recorded in History, in which, the best Causes have been ruin'd by an Excess of virtuous Zeal, too hastily to promote them. I ever thought, & think still, that a just Reverence for the Lives of our Countrymen, should determine us at all Events to wait for a Turn of European Affairs, and of British Sentiments. Either of these may save Us [with] out an Effusion of Blood. If at last, the Choice must be the Sword, or Submission, [then] America cannot hesitate."],["p","Please to present my Compliments to your good Family, %c to Messrs Adams, Paine, Adams and Hancock. I am Dr. Sir, with great"],["p","Truth, your very affectionate fe very humble Servant,"],["p","John Dickinson"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v01.0241":{"title":"Samuel Adams to William and Thomas Bradford","author_label":"Samuel Adams","kind":"letter","date":"1775-01-07","date_label":"January 7, 1775","date_type":"written","recipient":"William and Thomas Bradford","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 1","source_url":"https://archive.org/details/lettersofdelegat01smit","scan_url":"https://archive.org/details/lettersofdelegat01smit/page/292","text_status":"unreviewed_ocr","editorial_source_note":"RC (DLC) . Printed facsimile.","authors":["samuel-adams"],"paras":[["h","Samuel Adams to William and Thomas Bradford"],["p","Gentlemen Boston Jan. 7 1775"],["p","I have lately receivd your1 favor of the 6 Deer by the Post, advising me of your having shipped to my Care on board the Captains Glover and Johnson two boxes containing in the whole 350 Journals of Congress. I have since been informd that they are arrivd in Salem, and expect daily to receive them. I shall observe your Directions to dispose of one to each of the Gentlemen you have mentiond, and make the best & most speedy Sale of the others."],["p","I am with due Regard Gentlemen Your humble servt."],["p","Saml Adams"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v01.0270":{"title":"John Dickinson to Arthur Lee","author_label":"John Dickinson","kind":"letter","date":"1775-04-29","date_label":"April 29, 1775","date_type":"written","recipient":"Arthur Lee","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 1","source_url":"https://archive.org/details/lettersofdelegat01smit","scan_url":"https://archive.org/details/lettersofdelegat01smit/page/331","text_status":"unreviewed_ocr","editorial_source_note":"RC (MH) . In Dickinson's hand, though not signed.","authors":["john-dickinson"],"paras":[["h","John Dickinson to Arthur Lee"],["p","[Fairhill?] April 29th. 1775. \"The 'immedicabile Vulnus' is at length struck. The Rescript to our Petition is written in Blood. The impious War of Tyranny against Innocence has commene'd in the Neighbourhood of Boston.\" Describes battle of Lexington and Con-"],["p","cord at length. Continues: \"I cannot say, I am convinc'd of the Truth of all the Particulars above mentioned; tho all of them are supported by many probabilities. But these Facts, I believe, You may depend on. That this most unnatural and inexpressibly cruel War began with the Butchery of the unarm'd Americans at Lexington — that the Provincials, incredible as it may be at St. James's or St. Stephens' fought bravely — that the Regulars have been defeated with considerable Slaughter, tho they behav'd resolutely — that a Tory dares not open his Mouth against the Cause of America even at New York — that the Continent is preparing most assiduously for a vigorous Resistance— and that Freedom or an honorable Death are the only Objects on which their [Sons?] are at present employed."],["p","\"What human Policy can divine the Prudence of precipitating Us into these shocking Scenes? Why have We been so rashly declared Rebels? Why have Divisions been sent to disarm Us? Why Orders to commence Hostilities? Why was not General Gage at least restrain'd from Extremities till the sense of another Congress could be collected? It was the determined Resolution of some already appointed delegates for it, to have strain'd every nerve at that Meeting, to attempt bringing the unhappy Dispute to Terms of Accommodation, safe for the Colonies and honorable 8c advantageous for our Mother Country, in whose Prosperity 8c Glory our Hearts take as large a Share, as any Minister's of State, and from as just and as generous Motives, to say no more of them."],["p","\"Bui what Topicks of Reconciliation are now left for Men, Who think as I do, to address our Countrymen? to recommend Reverence for the Monarch or Affection for the Mother Country? Will the Distinctions between the Prince and his Ministers, between the People & their Representatives wipe out the Stains of Blood? Or have We the slighesl Reason to hope, that those Ministers & Representatives will not be supported throughout the Tragedy as They have been thro the first Act? No. While We revere & love, the Sword is opening our Veins. In all human probability, the same Delusions will still prevail, till France 8c Spain, if not other Powers, long jealous of Britain's Force 8c Fame, will fall upon her embarrass'd with an exhausting Civil War, and crushing or at least depressing her, then turn their arms on these provinces, which must submit to wear their Chains or wade thro Seas of Blood too dear bought and at best a frequently convuls'd and precarious Independence."],["p","\"All the ministerial Intelligence concerning Us is false. We are a united, resolved People — are or quickly shall be well arm'd 8c disciplined. Our Smiths 8c Powder Mills are at work Day 8c Night. Our supplies from foreign Parts continually arriving. Good officers, that is, well experienc'd ones, We shall soon have — and the Navy of Britain cannot stop our whole Trade. Our Towns are but Brick and Stone 8c"],["p","Mortar & Wood. They perhaps may be destroyed. They are only the Hairs of our Heads. If shav'd ever so close, they will grow again. We compare them not with our Rights & Liberties. We worship as our Fathers worship'd — not Idols which our Hands have made.\""]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v01.0521":{"title":"John Hancock to Philip Schuyler","author_label":"John Hancock","kind":"letter","date":"1775-07-01","date_label":"July 1, 1775","date_type":"written","recipient":"Philip Schuyler","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 1","source_url":"https://archive.org/details/lettersofdelegat01smit","scan_url":"https://archive.org/details/lettersofdelegat01smit/page/568","text_status":"unreviewed_ocr","editorial_source_note":"RC (PHC) . Tr (NN) . RC incomplete; signature and postscript supplied from Tr. 1 See JCC, 2:123-24.","authors":["john-hancock"],"paras":[["h","John Hancock to Philip Schuyler"],["p","Sir Philadela. July 1st. 1775"],["p","I duly Rec'd your Letters of 29 & 30th ulto. (that Refer'd to by you of 28th not yet come to hand) and immediately laid them before the Congress, in Consequence of wch. I have their Directions to Transmitt you their Resolution, whereby you will observe that Genl Wooster is order'd with the Troops under his Command to Remain at New York, and that you Raise as many of the Green Mountain Boys & others in the Vicinity of Ticonda. as will be necessary to Execute the Resolutions of Congress I heretofore Transmitted you.1 You will please particularly to Notice that altho' the Congress have given you peremptory Instructions to Take or Destroy all the Boats Vessells 8cc preparing by Gov Carlton on or near the Lake, yet with respect to your proceedg. to Montreal & Quebeck such Circumstances are pointed out by their Resolution which they Expect you [to~\\ be fully possess'd of previous to your undertakg the prosecution of that Expedition."],["p","I inclose you the Arrangement of the officers with their pay so far as has been determin'd by Congress, as soon as the whole is Settled you shall be made Acquainted; as to the Allowance of provisions, that at present must be left to your Discretion, untill you hear further from this Congress or the General on that Subject."],["p","I am to inform you that besides the Quantity of powder Sent from Connectict. to Ticonderoga, the Committee of this City by Desire of Congress yesterday Sent forward 50 quarter Casks of Powder to that place."],["p","Any Resolutions of Congress that take place respectg you I shall be Carefull immediately to transmitt you. I am Sir Your most Obedt. Servant. John Hancock president."],["p","[P.S.] If you are in Want of any more Commissions, let me know & they shall be sent, none are to be issued, but such as go from this Congress."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v02.0217":{"title":"John Adams to James Warren","author_label":"John Adams","kind":"letter","date":"1775-10-19","date_label":"October 19, 1775","date_type":"written","recipient":"James Warren","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 2","source_url":"https://archive.org/details/lettersofdelegat02smit","scan_url":"https://archive.org/details/lettersofdelegat02smit/page/205","text_status":"unreviewed_ocr","editorial_source_note":"RC (MHi) . In Adams' hand, though not signed.","authors":["john-adams"],"paras":[["h","John Adams to James Warren"],["p","Dr Sir Octr. 19th. 1775"],["p","What Think you of an American Fleet?1 I dont Mean 100 ships of the Line, by a Fleet, but I Suppose this Term may be applied to any naval Force consisting of several Vessells, tho the Number, the Weight of Metal, or the Quantity of Tonnage may be small."],["p","The Expence would be very great — true. But the Expence might be born and perhaps the Profits and Benefits to be obtained by it, would be a Com pensation. A naval Force might be created, which would do something. It would destroy Single Cutters and Cruisers — it might destroy small Corvets or Fleets of these like Wallaces at R. Island and Ld Dunmores at Virginia — it might oblige our Enemies to sail in Fleets — for two or three Vessells of 36 and twenty Guns, well armed and manned might attack and carry a 64 or a 70 or a 50 Gun Ship."],["p","But, there is a great objection to this. All the Trade of Pensylvania, the Lower Counties, a great Part of Maryland and N. Jersey Sails in between the Capes of Delaware Bay — and if a strong Fleet should be posted in that Bay, Superior to our Fleet it might obstruct all the Trade of this River. Further the Trade of Virginia and the rest of Maryland floats into Cheasapeak Bay between the Capes of Henry and Charles where a Fleet might Stop all. Besides Virginia and Maryland have no Navigation of their own nor any Carpenters to build ships. Their whole Trade is carried on in British Bottoms by British, most of it by North British Merchants."],["p","These Circumstances distinguish them quite from New England, where the Inlets are innumerable and the Navigation all their own."],["p","They agree that a Fleet would protect & secure the Trade of New England but deny that it would that of the Southern Colonies."],["p","Will it not be difficult to perswade them then to be at the Expence of building a Fleet, merely for N. England. We are Speculating now about Things at a Distance. Should We be driven to a War at all Points, a Fleet a public Fleet as well as privateers might make prey enough of the Trade of our Enemies to make it worth while."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v02.0272":{"title":"Robert R. Livingston's Notes for a Speech in Congress","author_label":"Robert R. Livingston","kind":"speech","date":"1775-10-27","date_label":"October 27, 1775","date_type":"written","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 2","source_url":"https://archive.org/details/lettersofdelegat02smit","scan_url":"https://archive.org/details/lettersofdelegat02smit/page/263","text_status":"unreviewed_ocr","editorial_source_note":"MS (NHi) . In the hand of Robert R. Livingston, Jr. Although an effort has been made to preserve the cryptic character of Livingston's notes, editorial insertions have been added to make them more intelligible and several abbreviations have been expanded without brackets. (For the first page of thes","authors":["robert-r-livingston"],"paras":[["h","Robert R. Livingston, Jr.'s Notes for a Speech in Congress"],["p","[October 27, 1775]1 Motion [to continue noncxportation is] part [of the] general system."],["p","Limitation to March — when apparent [we can] only trade in winter— enemy [can] prevent [?/.v] in summer.2 Arguments against Trade [are] general — hardly believe serious. Inconveniences from stopage [of] trade."],["p","III. Objects."],["p","I. Enable our own people to bear Burthens & to render them"],["p","willing to carry on war. II. To procure means [of] war. III. To impoverish, weaken enemy."],["p","I. May be laid down as a principle, that all circumstances being alike, those support war longest who have most superfluous wealth. Those avoid it who feel more injuries from war than [they have] reason [to] expect from submission. Consider effect [of nonexportation] on wealth [of the] people."],["p","1st. Reduction of price of produce to 1/2 value — Price [of] Labour must fall same proportion. This no inconvenience if [it] stood alone, because labour &"],["p","subsistance bear same proportion to each other. 3 Things to be consider'd:"],["p","1. Tho labour cheap yet vent for produce small — farmer"],["p","discharge labourers. 2d. Cloathing dearer than before — thereafter [when] produce falls 1/2, necessaries purchased [rise in] same proportion: value of cloathing, salt 8cc. is as 1 to 2; the farmer [would] pay 2/3 of income. 3. Burthen still heavier on labourer who [in] genl. being maintained by farmer, worked for cloathing 8c triffle for pleasure of family. [With his] wages diminished 1/2, necessaries except food raised 1/2, [it is] impossible [that he] can cloath himself at all. 2d. People [who] subsist by trade: Merchants, ship builders, Rope & sailmakers, Sailors, Smiths, Millars, labourers employed [at] Furnaces, carriers by land 8c water — in New York, Pensylvania, Rode Island make about 1/4 of the whole — other Colonies North [of] Pensylvania 1/8 — so that have upwards [of] 225,000 [plus] 75,000 [or] 300,000 people besides labourers out of employ who must be supported. All these must be supported by farmer whose income [is] already diminished 2/3. May be said [that these] may be employed. How? Not in culture, Lands less cultivated now than before. Not manufactures— always worked up all materials; of course [there are] hands to do it without them. Consider rigor [of] climate, delicate life, many [of] these [do] not think 30 dollars [a] year extravagant for subsistance. 9,000,000 [dollars]. This tax must be raised immidiately on 7 Colonies &. those [the] poorest."],["p","y '"],["p","%~.i ^.fs^te ~^~«"],["p","/"],["p","X /£ ~ SS \""],["p","<\/\".-?\" ^-v^- ■"],["p","U /&.» ~Jz~**-6~~*7 ~—-"],["p","J ft, % s^y^*^' ' ' /"],["p","Sas.'„~ <■\"■ •-■ - « '■■ <*& *£■ - &***■ - \"f^y"],["p",".****l£."],["p",".'**Tr, t-S*> <?\"■■**■ ^'*5r»*^«» **«^ t-f /■jZt-m**'- ■ ~"],["p","Robert R. Livingston Notes"],["p","L"],["p","May be said some [of] these [colonies are] rich; support"],["p","themselves & others. Deny. Riches [of] northern colonies consists [of] stock in"],["p","trade, money at interest, Land rents. 1st. No use. 2nd. Interest money can not be paid when trade"],["p","stoped, nor can principle be recovered — suits [at] law"],["p","stoped, of course credit, & with it circulation [of] cash. 3d."],["p","Landlord cannot expect rent of people taxed 2/3 of whole"],["p","estate. So that this resolution [to continue nonexportation] anihi-"],["p","lates all property.3"],["p","II. Inquire whether war with all these pressures [is] not more greivous than any they expect from (peace) submission. If it is they chuse lesser evil."],["p","[The people] felt no oppression — found [they] grew wealthy under dominion [of] parliment. Yet spirit [of] liberty excited wonderfully. Hopes boyed up, now see serious. We ourselves thought virtue shd. not be tried. [// we would] not tax 3,000,000 when in affluence, how expect 7 Colonies [to] bear weight [of] 9,000,000 [dollars], besides burthen of war & a total loss besides of 2/3 of property?"],["p","Add to this [that the] value [of] commodities on hand [which] amount to ,4 operate as a bridle on possessors. Horses,"],["p","wheat &c. which could sell £30, now but 15; as much under influence as if £15 given him to desert cause."],["p","People know too that on submission storm [would] burst only on leaders; That oppressions [would] not [be] heavy at least for time."],["p","[People] already alledge dispute [is] about property; they have none."],["p","No instance [in] history [that a] people reduced [to] this situation maintained war. Revolt [in the] Low Countries not paralel, grivously opressd religion — governmt felt many years — body [of the] people felt as much as rich."],["p","During war [the Dutch] carried on trade — grew rich."],["p","Case nearest ours — commotion [in the] year 1640. 5"],["p","Their people soon tired [of] governmt of republick, Tho' trade most flourishing state, meerly on acct. [of] taxes. Petition [and] commotions shew inclinations, army necessary to subject them. Restoration matter [of] genl. satisfaction."],["p","Calculate from northern colonies these inconveniences, not so much felt southwd. Trade [in the South is] carried on English bottoms— no Seamen, no merchants, but few factors. No ship"],["p","builders — various mechanicks employed in that business — few carriers but negroes."],["p","Planters live on estates, cultivation [of] which with great number [of] hands easily procure food & clothing sufficient for whites. Blacks go naked till 14 — of course may till 50."],["p","Not wonder therefore some [of] them stickle measure which judging own climate is but temporary inconvenience."],["p","Hope [they] change sentiments when [they] take view [of the] northern ones."],["p","Whether [we can] obtain means [of] war [if] this takes place. 1st. Wants sufficiently obvious. Operations [of] armies checked by it. Citys defenseless. Coast lyable to be ravaged. Second. Exception with respect [to] them but these [will] not answer purpose — 2 reasons:"],["p","(1st) Because publishes wants to our enimies — make"],["p","[them] more vigilant. (2d) Few merchants engage when bound at all events to return [with] military stores. May so happen [these] cannot be got at port sent — then voyage frustrated. If trade left at large, they always indeavour to get them because yield most promt — adventure because shd [they] fail [to obtain] that cargo [they would] still not return empty. Has been said that if [we had] open ports none but eastern colonies trade — own advantage — rejoice at it. Tho' they joined sentiment that our enjoying advantage [was] not hurtful [to the] rest [of the] provinces, [it] wd excite jealousy in theirs. Yet persuaded own Constituents think as to wish them advantages ten times greater. Besides every Colony [has] chance during winter of slipingout."],["p","3d Objection, impossibility [of] obtaining navy. [Nonexportation] banishes seamen, who not only [are] lost but become enimies — forced by necessity into British service. [Owen] these considerations [we] Must Trade."],["p","III. Meathods proposed. 1st. Invite forreigners. 2d. Trade with all the world except G. B. & I. 3d. Export immediately to G. B. & Ireland except tobacco 8c lumber. I. Invite forreigners. 2 Inquiries."],["p","1st. Whether foreigners at large or particular nations? 2d. Whether temporary expedient or lastg Basis of our"],["p","trade? If at large no national object. Still less so if only temporary"],["p","expedient. Not expect merchants [to] alter course [of] trade & turn [into a] chanel which expect soon [to be] stoped & in which expect many rivals."],["p","If then must trade [with a] particular power, inquire who shall bel Holland, Portugal unable to protect us. [Would] Spain regardless of her own trade consider new one as object? Suffered all staples to decay, mismanagement— weak, unenterprizing — war already on hand."],["p","Only remaining power France. 1st. How [. . . .]«"],["p","1st. Is [it] not very doubtful whether she [France] will trade with us, considering low state [of her] finances, weakness [of the] present monarchy, And late conduct?"],["p","Gent, asserts she must; for want [of] grain which [she can] get no where else. Our exports of grain to France do not make a 110th part of her consumption. Our exports to her never amounted 1,000,000 [bushels] — her consumption 150,000,000."],["p","So [France] not forced [to trade for] those. As many advantages [would] result [to] her from trade, may possibly think [it] worth her notice."],["p","But private adventurers never undertake this. Before govermt interposes, must settle Terms. Must at least be permanent at all events."],["p","Have Gent, turned thoughts to what terms shall be?"],["p","Have fix'd time? Considered whether trade may not become monopoly? Whether she can supply us with woollens without getting them from England? Whether this [might] not defeat our non importation? True, this [would be a] loss [to] G. B., but have [gentlemen] considered whether greater loss [might] not fall on us?"],["p","Have made any provision for our shipbuilders, sailors &c. or must [these] be a burthen?"],["p","But this evident & this measure not to be adopted till treaties settled — nor they entered into till [the French] agree to break with Great Britain."],["p","II. Trade with foreigners at large [in our] own bottoms. This more advantagious because still imploy our own hands. Retain Sailors. Still has its disadvantages."],["p","1st. Vessels liable to capture. By which means [Britain"],["p","would] receive our commodities on a cheap lay. 2d. West Indies would be supplied from foreign West Indies. 3d. British goods would be lodged at foreign ports. Thus non importation, in which our chief strength, [would] be defeated. 4th. When our trade [is] witheld, Briton [would] be under necessity of fetching some commodities from Northern nations [which she] now gets of us. This [would] afford vent to goods [she] usually send to us. May [be~\\ said no purchasers."],["p","Mistake. Both Dutch & English send woollens up Baltick. Of course price must be nearly equal. If so then a small reduction in price [would] enable English to undersell Dutch. That reduction would [be~\\ made. For as [Britain'] must fetch commodities from there, [she] must either send vessels empty and loose freight outward, or by sinking whole profit, make freight. May be said This was done when [she] traded with us —"],["p","of course [her prices] could sink no lower. Not fact. When same good imported [by Britain] from America that [she ivould now] get from Northern nations, & at rather a cheaper rate — profit to the mercht trading with them was on his outward entries — only took their commodities to make a freight. Now reverse. So [it is] clear By non exportation agreement we defeat non importation. Leave [British] manufactures 8c merchants [in the] same state they were, subjecting indeed [that] nation to a loss, but too small to be early felt. That made up by captures. If Then [a] mode can be fallen upon that can prevent these inconveniences, preserve our non importation inviolate, sure prejudice or hard words shd. not prevent a cool examination of it. This did myself honour to mention. As was reed, cooly, [/] shd. have passed over had [/] not been called upon.7 Now endeavour to defend."],["p","III. Export immediately to G.B. & Ireland except tobacco (&"],["p","Lumber), but not import. These evident advantages."],["p","1st. If our exports equal [£] 2,500,000 we must drain"],["p","[Britain] anualy of that some [sum]. Effect this"],["p","[would] have on G.B. when considered [that her]"],["p","current cash not more than [£] 2,000,000. Besides"],["p","employing hands, enriching country, [it ivould] enable [us] to pay whole expense [of the] war."],["p","Enables [us to] purchase what [we] want [to] carry on war. Cheaper, less risk. For vessel would be safe from here to England then have money with which [to] trade [with] any foreign nation. Landings little danger [if] any, numerous inlets on coast."],["p","This would give us intelligence of Movements of our enimies."],["p","Would reserve our seamen."],["p","Objections."],["p","1st. That prohibition [of] tobacco [exports] would create disgust [in] 2 Colonies. [For] my own part [/ have a] higher opinion [of their] virtue than [to] think so. Principles on which prohibited might be explained. Lands [luhich] raise tobacco [are] fit [for] any grain. Female negroes not employed, but will they be employed if trade totally stoped? If not, were disadvantage."],["p","2d. That many things exported by us manufactured in England 8c reshiped. Have shewn [that if Britain] did not get [them] from Colonies, [they would] be procured from elsewhere — & in return for them manufactors. Iron. But even if not, [the] value of those as well as home consumption [ivould be] paid us in specie."],["p","3d. Number hands employed in reshiping. But surely more employed [by] us in shiping — not only same but what they consume too."],["p","4th. Flax seed [to] Ireland not so important as [we] imagine. [They could] procure [it] from Holland [as they] formerely did. Whole value [£] 40,000. Idle [to] think [they] could not manufacture [for] want of it."],["p","5th. West Indies — provision Shiped not reshiped there."],["p","Gent did not think much weight in argument when [he]"],["p","supposes trade [would] be so ruinous to G.B. that she"],["p","would prohibit it. Worth trying. Perhaps interest [of] individual [would]"],["p","over rule publick good. Find [that Britain] does carry on some trades where bal-"],["p","lance [is] against her — East Indies. [During the] last non importation against [Britain, we]"],["p","exported to her. Probable [we ivould] enjoy advantage at least [for] some"],["p","time when [Britain] prohibited exportation [of] specie, which [is the] most probable meathod [Britain would] take [to] stop it. Purchase forreign bills answer same purpose."],["p","Gent went far into non importation & disadvantages Britain laboured from. [/] agree [with that] sentiment, & [am] so far [from] wishing to break it that I mention this [as the] only mode to preserve [non importation] in full force."],["p","Breach association. But if [non exportation is] founded in error, shd. be revoked. Not at present. Let people feel want [of] trade, which [they will] do in few weeks, then grant."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v02.0312":{"title":"Roger Sherman to Jonathan Ingersoll","author_label":"Roger Sherman","kind":"letter","date":"1775-11-06","date_label":"November 6, 1775","date_type":"written","recipient":"Jonathan Ingersoll","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 2","source_url":"https://archive.org/details/lettersofdelegat02smit","scan_url":"https://archive.org/details/lettersofdelegat02smit/page/312","text_status":"unreviewed_ocr","editorial_source_note":"RC (CtNhHi) .","authors":["roger-sherman"],"paras":[["h","Roger Sherman to Jonathan Ingersoll"],["p","Sir Philadelphia Novr. 6th. 1775"],["p","I received Your letter of the 30th of October. Would request you1 to use your best discretion on my behalf in Securing and recovering the money due on the Several notes which I put into Your hands, and You may rest Assured that You Shall not Suffer by any loss which may happen, and I will See that Justice be done the Assignee So far as is in my power."],["p","I dont know when I can come home, or have opportunity to attend to my own private affairs."],["p","There has been Several Addresses to General Gage from Some persons in Boston, on his leaving that place, lately published here. John Simson is a subscriber of one of them, wherein is this remarkable paragraph: viz, \"We cannot forbear to express our Sentiments, that could a restoration to quiet and good Order have been effected in this Province by the influence of personal character, a gentleman of Your Excellency's Established reputation for Candour 8c Justice, for moderation, and an obliging disposition, invested at the Same time with the Supreme Military Authority, could not have failed to have Secured it.\" General Gage's treatment of the Unhappy Sufferers in Boston will Evidence how well he deserved this Character! If the aforesaid Subscriber is your client, you would do well to consider"],["p","whether consistent with Duty or Safety You can continue to do Business for or correspond with Such a Traitor to his Native Country. I remain Yours to Serve Roger Sherman"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v02.0323":{"title":"John Hancock to James Bowdoin, Sr.","author_label":"John Hancock","kind":"letter","date":"1775-11-09","date_label":"November 9, 1775","date_type":"written","recipient":"James Bowdoin, Sr.","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 2","source_url":"https://archive.org/details/lettersofdelegat02smit","scan_url":"https://archive.org/details/lettersofdelegat02smit/page/321","text_status":"unreviewed_ocr","editorial_source_note":"RC (MHi) .","authors":["john-hancock"],"paras":[["p","John Hancock to James Bowdoin, Sr."],["p","Sir, Congress Chamber 9 Novr. 1775 Philada."],["p","I am exceeding Glad to find by the Report of our Committee of Conference1 that your health was so Establish'd as to be able to attend the Publick Business, I hope soon to hear of your perfect Recovery."],["p","I have the pleasure to inform you that your Son Mr. James Bowdoin2 Arriv'd last Eveng in this City from London, and this morning Breakfasted with me, he is in good health, and proposes in a few days to Set out for Cambrige. I Congratulate you on his Arrival. No Answer to the Congress Petition, the King Refusing to Receive it on the Throne; that we must work out our own Salvation."],["p","I Beg my best Respects to your good Lady, & am with Respect, Sir Your Most Obedt Servt, Jonn Hancock"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v02.0532":{"title":"Benjamin Harrison to Robert Carter Nicholas","author_label":"Benjamin Harrison","kind":"letter","date":"1775-12-30","date_label":"December 30, 1775","date_type":"written","recipient":"Robert Carter Nicholas","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 2","source_url":"https://archive.org/details/lettersofdelegat02smit","scan_url":"https://archive.org/details/lettersofdelegat02smit/page/537","text_status":"unreviewed_ocr","editorial_source_note":"RC (PHC) .","authors":["benjamin-harrison"],"paras":[["h","Benjamin Harrison to Robert Carter Nicholas"],["p","Dr Sir Phida. Deer. 30th. 1775."],["p","I Reed, your Favor1 by Express inclosing Bills of Exchg. for five hundred Pounds Sterg. which we have agreed to divid amongst us that are left after Deducting the amount of the Paper &c. sent by Capt Innis, and what you have now order'd, and £17.5.0 this Cury. advanced to Singleton. The poor Fellow lost his Horse which made this necessary. We shall also pay fifty Pounds Virga Currency for Mr Jefferson and take up his order on you to Willing & Morris; the Bills are Sold at seventy two and a half per Cent. The Express was Ready to set off yesterday but geting a Letter from the Gen. Inclosing a Number of intercepted Letters from L. Dunmore and both the Carolinas we thought it better to detain him a Day that we might send to the Com[mitte]e of Safety Extracts of such as were interesting, which we have done and refer you to them for a Sight of them.- I had a private Letter from Camp by which I think it is certain that Robinson, Mathews and Deane were taken in the Vessel. We have no News from Canada but expect an Express every Day with the good Tidings of our being in possession of Quebec. I am Dr Sir Your aftet Servt"],["p","Benj Harrison"],["p","P.S. We have agreed for 25 Ream of Paper to be Deliver'd in 16 Days which shall be immediately sent to you. The other ten will not be ready in some time longer. We think it best to send what we can get soon that you may not shut up shop.3"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v03.0017":{"title":"Robert Treat Paine to Philip Schuyler","author_label":"Robert Treat Paine","kind":"letter","date":"1776-01-02","date_label":"January 2, 1776","date_type":"written","recipient":"Philip Schuyler","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 3","source_url":"https://archive.org/details/lettersofdelegat03smit","scan_url":"https://archive.org/details/lettersofdelegat03smit/page/19","text_status":"unreviewed_ocr","editorial_source_note":"RC (MdBJ-G).","authors":["robert-treat-paine"],"paras":[["h","Robert Treat Paine to Philip Schuyler"],["p","My dear General Philada Jany. 2d. 1776"],["p","I did desert, because I found that was my only method of getting"],["p","from Albany. I should have taken my Leave of your most agreable"],["p","family, but the Urgency of my Journey would not admitt of it, pray"],["p","make my Excuses & present my Compliments to yr. Lady (whose Welfare I should gladly hear of) & also to the young Ladys yr. Daughters."],["p","I had a fatiguing Journey here, but don't find myself the worse for it. We want much to have the Report of the Cmssrs of the Indian Treaty. The Report of the Cmttee I was upon is Committed, & I hope will soon be reported, I shall press the matter;1 I find the Time of my Delegation is Extended to the Last of the month after which it is uncertain whether I shall be here."],["p","Inclosed I send a Newspaper containing a simple & I think very intelligeable method of making Salt petre, as also the result of the Cmttee you were upon which I am sure never was dispersed in the manner it ought to have been. I am sure you will extend the knowledge & practice of this most essential manufacture as far as you possibly can. I assure you it becomes more & more necessary to encrease it."],["p","My Compliments to Mr. Dough [Volkert P. Douw?], Col Tenbroek & others with whom I had the pleasure of any Acquaintance."],["p","Hoping you health & best happiness, I rest yr most hble Sevt.,"],["p","R T Paine"],["p","P.S. I also send you a Resolve of Congress occasioned by the Kings Proclamation.2"],["p","They have got to make Salt petre in large quantitys in many places, & to that degree in Massa. that the Government are about Setting up two powder Mills. Pray don't be behind the best of us."],["p","There is no news here, except that the River is broke up here & I expect 2 ships of 30 guns & 2 Briggs of 18 or 20 will sail soon on a Cruise.3"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v03.0128":{"title":"John Hancock to Thomas Lowrey","author_label":"John Hancock","kind":"letter","date":"1776-01-25","date_label":"January 25, 1776","date_type":"written","recipient":"Thomas Lowrey","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 3","source_url":"https://archive.org/details/lettersofdelegat03smit","scan_url":"https://archive.org/details/lettersofdelegat03smit/page/152","text_status":"unreviewed_ocr","editorial_source_note":"LB (DNA: PCC, item 12A).","authors":["john-hancock"],"paras":[["h","John Hancock to Thomas Lowrey"],["p","Sir, Philada. Jany. 25th. 1776"],["p","On the 1 1 th Inst there was a Draught on the Treasury in your Favour, for 35,000 Dollars, out of which you were directed to provide sundry Articles wanting for second New Jersey Batallion which was ordered to March to Canada.1"],["p","By a Letter this Day reed, from Col. Maxwell the Congress are informed that the Articles are not yet provided.2 The Necessity of the Service requires that the Batallion should march with all possible Expedition, I am therefore directed to press you to exert your utmost Endeavours to provide the Articles, and facilitate the March of the Companies as fast as they can be got ready by all the Means in your Power. I am &c, J H Pt."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v03.0195":{"title":"Samuel Chase to Daniel of St. Thomas Jenifer","author_label":"Samuel Chase","kind":"letter","date":"1776-02-10","date_label":"February 10, 1776","date_type":"written","recipient":"Daniel of St. Thomas Jenifer","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 3","source_url":"https://archive.org/details/lettersofdelegat03smit","scan_url":"https://archive.org/details/lettersofdelegat03smit/page/219","text_status":"unreviewed_ocr","editorial_source_note":"RC (MdAA).","authors":["samuel-chase"],"paras":[["h","Samuel Chase to Daniel of St. Thomas Jenifer"],["p","Dear Sir, Philada. Feby. 10th 1776"],["p","Inclosed You receive a proposal to furnish our Troops with the new"],["p","invented Knapsack, and Haversack, & of Cartouch Boxes etc.1"],["p","The Blockade of Quebec is continued. Arnold has 700 Men with"],["p","him — daily Aids are going. He expects to take the Command in Six Weeks. No News of Consequence. Your obedt. Servant,"],["p","Saml Chase"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v04.0035":{"title":"Elbridge Gerry to James Warren","author_label":"Elbridge Gerry","kind":"letter","date":"1776-05-20","date_label":"May 20, 1776","date_type":"written","recipient":"James Warren","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 4","source_url":"https://archive.org/details/lettersofdelegat04libr","text_status":"unreviewed_ocr","editorial_source_note":"MS not found; extract reprinted from Austin, Life of Gerry, 1:178-80.","authors":["elbridge-gerry"],"paras":[["h","Elbridge Gerry to James Warren"],["p","[May 20, 1776]"],["p","I enclose you a Virginia paper just come in, by which you will see the spirit of another county in that colony, exhibited in their instructions for independency. 1"],["p","In this colony (Pennsylvania) the spirit of the people is great, if a judgement is to be formed by appearances. They are well convinced of the injury their assembly has done to the continent by their instructions to their delegates. It was these instructions which induced the middle colonies and some of the southern to backward every measure which had the appearance of independency: to them is owing the delay of congress in agitating questions of the greatest importance, which long ere now must have terminated in a separation from Great Britain: to them is owing the disadvantages we now experience for want of a full supply of every necessary for carrying on the war. Alhances might have been formed, and a diversion been given to the enemy's arms in Europe or the West Indies, had these instructions never appeared. But they have had their effect; and while we endeavour to recover the continent from the ill"],["p","consequences of such feeble politics, we ought to show the cause of such miserable policy. It appears to me that the eyes of every unbeliever are now open; that all are sensible of the perfidy of Great Britain, and are convinced there is no medium between unqualified submission and actual independency. The colonies are determined on the latter. A final declaration is approaching with great rapidity. May the all-wise Disposer of events so direct our affairs that they may terminate in the salvation of these afflicted colonies."],["p","Amidst all our difficulties you would be highly diverted to see the situation of our \"moderate gentlemen.\" They have been more apprehensive of evils than any others, as we have frequently observed, and they have now the mortification to find that their measures for avoiding have but served to increase them. I sometimes think that Providence permitted them to clog the affairs of the colonies, that they may become in some degree desperate, and thus introduce into the circle of determined men those timid beings, whose constitution never admits of their defending freedom on the noblest principles, and are afterwards obliged to meet danger by the same motives that induced them to shun it. They are coming over to us, but I am sorry their counter influence so long prevented us from adopting the only means by which we could supply ourselves with the necessaries for defence."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v04.0079":{"title":"John Adams to Samuel Cooper","author_label":"John Adams","kind":"letter","date":"1776-05-30","date_label":"May 30, 1776","date_type":"written","recipient":"Samuel Cooper","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 4","source_url":"https://archive.org/details/lettersofdelegat04libr","text_status":"unreviewed_ocr","editorial_source_note":"LB (MHi).","authors":["john-adams"],"paras":[["h","John Adams to Samuel Cooper"],["p","My dear sir May 30th. 1776"],["p","Yours of the 20tli was handed me by the last Post.^ I congratulate you upon the first modern Election, on the last Wednesday in May, of Councillers as at the first. I could not avoid indulging myself yesterday, in Imagination with my Friends in Boston, upon an occasion so joyfull. I presume you must have had a very solemn and ceremonious Election, and wish that no Interruption may ever hereafter take Place, like that of the last year."],["p","You have given me great Pleasure by your account of the Spirit and Activity of our People, their Skill and success in fortifying the Town and Harbour: But there are several Things still wanting, in my Judgment. I never shall be happy, untill every unfriendly Flagg is driven out of sight, and the Light House Island, Georges and Lovells Islands, and the East End of Long Island are secured. Fire Ships and Rafts will be of no service without Something to cover and protect them from the Boats of the Men of War. Gallies are the best Engines in the World for this Purpose. Coll Quincy has the best Idea of these Gallies, of any Man I know. I believe he has a perfect Idea of the Turkish, and Venetian Gallies. Some of these are large as British Men of War, but some are small. (I Sincerely wish, that at this Time he was a Member of one or the other House, because his knowledge and Zeal would be usefull. This however is none of my Concern. But his Knowledge in naval and marine affairs is not exceeded by any Man I know.) ^ Gallies might be built and armed with heavy Cannon, 36 or 42 Pounders, which would drive away a Ship of almost any Size, Number of Guns or Weight of Metal. The Dexterity of our People in Sea Matters must produce great Things, if it had any Person to guide it, and stimulate it. A Kind of dodging Indian Fight might be maintained, among the Islands in our Harbour, between such Gallies and the Men of War."],["p","Whether you have any Person, Sufficiently acquainted with the Composition of those Combustibles, which are usually put into Fire Ships and Rafts I don't know. If you have not, it would be worth while to send some one here to inquire and learn. At least let me know it, and altho I have a demand upon me for an Hour, when I have a Minute to Spare, yet I will be at the Pains, tho I neglect other Things of informing my self as well as I can here, and send you what I learn."],["p","We are making the best Provision we can, for the Defence of America. I believe We shall make Provision for 70,000 Men in the three Departments the Northern, including Canada, the middle, and the southern. The Die is cast. We must all be soldiers and fight pro Aris et Focis. I hope there is not a Gentleman in the Massachusetts Bay, not even in the Town of Boston, who thinks himself too good"],["p","to take his Firelock and his Spade. Such imminent Dangers level all Distinctions. You must before now, have seen Some important Resolutions of this Congress/^ as well as of Seperate Colonies. Before many Weeks you will see more."],["p","Remember me with every sentiment of Friendship and Respect to all who deserve well of their Country. These are all my Friends, and I have, and will have no other. I am Sec."],["p","P.S. Gallies to be used mainly in Boston Harbour, the less they are the better provided they are large and strong enough to sustain the Weight of the Guns and the Shock of the Explosion. The Gallies first built in Delaware River, were too large to be handy and too small, to live and work in a Sea. We are building two of different Construction.^ They are to carry two large Guns in the Stern and two in front — and five or six 3 Pounders on each side besides swivalls. They are built to put to sea, live and fight in a swell or a storm. They are narrow but almost 100 feet long."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v04.0157":{"title":"Josiah Bartlett's Notes on the Plan of Confederation","author_label":"Josiah Bartlett","kind":"notes","date":"1776-07-12","date_label":"July 12, 1776","date_type":"written","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 4","source_url":"https://archive.org/details/lettersofdelegat04libr","text_status":"unreviewed_ocr","editorial_source_note":"MS (DLC). In the hand of Josiah Bartlett.","authors":["josiah-bartlett"],"paras":[["h","Josiah Bartlett's Notes on the Plan of Confederation"],["p","[June 12-July 12? 1776] i United Provinces proportion of 100000 Guilders viz."],["p","s d"],["p","Gelderland 3612— 5: 0"],["p","Holland * 58309— 1:10"],["p","Zealand 9183—14: 2"],["p","Friesland 11661—15:10"],["p","Overyssel 3571— 8: 4"],["p","Utrecht 5830—17:11"],["p","Groningen 5930—17:11"],["p","Each province sends as many Deputies as they please but however many Deputies sent such province has but one vote. The Deputies chosen for Different periods, some anually, some for life."],["p","June 12, 177G"],["p","By the Albany plan The present plan"],["p","5000 polls to a Delegate supposed"],["p","New Hampshire"],["p","Do"],["p","5 near 1 /6"],["p","Massachusetts"],["p","Do"],["p","Conecticut"],["p","Do"],["p","10-"],["p","-2/6"],["p","Rhode Island"],["p","Do"],["p","N York"],["p","Do"],["p","10-"],["p","-2/6"],["p","New Jersey"],["p","Do"],["p","u"],["p","— H /4"],["p","Pensylvania"],["p","Do"],["p","15-"],["p","-1/2"],["p","Lower Counties"],["p","1/2"],["p","Maryland"],["p","Do"],["p","Virginia"],["p","Do"],["p","3/4"],["p","North Carolina"],["p","Do"],["p","South Carolina"],["p","Do"],["p","\"48\""],["p","1/2"],["p","Massach., Pensylvania, Virginia & Maryland. 66 Members, More than half the whole."],["p","Remarks by G.W.2"],["p","Addition to 6th article And the Delegates are to Bring with them to Every Congress an authenticated Return of the No. of the polls in their respective Colonies which is to be triennially taken in order that Each Colonies proportion of the General taxes may be Equitably affixed."],["p","Art 7th"],["p","Each Colony shall choose what No. of Delegates the assembly or convention of such colony pleases not Exceeding for any one Colony."],["p","Art 8th"],["p","Each Delegate at the Congress shall have a vote in the first Instance in all Cases but if any Colony or Colonies are Dissatisfied with the majority of voices so taken the Colonies shall be Called seperately and Each Colony whatever its No. of Delegates may be, shall have only one vote as hath heretofore been customary in Congress."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v04.0170":{"title":"Josiah Bartlett to Meshech Weare","author_label":"Josiah Bartlett","kind":"letter","date":"1776-06-14","date_label":"June 14, 1776","date_type":"written","recipient":"Meshech Weare","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 4","source_url":"https://archive.org/details/lettersofdelegat04libr","text_status":"unreviewed_ocr","editorial_source_note":"RC (DLC).","authors":["josiah-bartlett"],"paras":[["h","Josiah Bartlett to Meshech Weare"],["p","Sir, Philadelphia 14 June 1776"],["p","This goes by the Person who carries the Money mention'd in a former Letter which was order 'd for the advance wages, and defraying the charges of raising the Regiment to be station 'd at Portsmouth.i The Sum ordered is 10,500 Dols., 500 Dols of which Wm. Whipple has taken, which he desires may be replac'd out of the Treasury and charg'd to him. 10,000 dols. is in a Box directed to you, there is in the same Box 10,000 Dols. for John Langdon Esqr which please to advise him of."],["p","We are with great respect. Your most obt Serts,"],["p","Josiah Bartlett"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v04.0208":{"title":"John Hancock to John Witherspoon","author_label":"John Hancock","kind":"letter","date":"1776-06-19","date_label":"June 19, 1776","date_type":"written","recipient":"John Witherspoon","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 4","source_url":"https://archive.org/details/lettersofdelegat04libr","text_status":"unreviewed_ocr","editorial_source_note":"RC (PPRF). In the hand of Charles Thomson and signed by Hancock.","authors":["john-hancock"],"paras":[["h","John Hancock to John Witherspoon"],["p","Sir, June 19. 1776"],["p","I had the honour of laying before Congress the letter from your"],["p","convention with the papers enclosed, whereupon the Congress came"],["p","to the above resolution, which you will please to forward to your"],["p","Convention by the first opportunity. ^ I am, Sir, Your obedient humble servt."],["p","John Hancock Prest."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v04.0227":{"title":"William Whipple to John Langdon","author_label":"William Whipple","kind":"letter","date":"1776-06-22","date_label":"June 22, 1776","date_type":"written","recipient":"John Langdon","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 4","source_url":"https://archive.org/details/lettersofdelegat04libr","text_status":"unreviewed_ocr","editorial_source_note":"FC (Capt. J. G. M. Stone, Annapolis, Md., 1973); Tr (DLC). FC incomplete; last paragraph and signature taken from Tr.","authors":["william-whipple"],"paras":[["h","William Whipple to John Langdon"],["p","Dr Sr. Philada 22d June [1776]"],["p","Agreeable to Your request in Your favor of the first inst^ I have applyed to the Chairman of the secret Committee to know if you shod have Liberty to pay for the Brig, that was taken, in answer to which he says the Charter Party 8c accots must be before the Committee e're they can give orders for the payment. By continual application & importunities I have at last prevail'd on the Marine Committee to consent to your shipg men.^ The warrents will be fill'd up as soon as you send the names. I expected to send you the Blank warrent but the Commte have changed their minds about that matter aledging it will be necessary to have the names enter'd in the office. Therefore the sooner you send them the sooner they will be return'd. I am endeavoring to persuade the Committee to order those Guns at Providence for your ship as she is so much more forward than any but am not certain of success. If I do not succeed in this plan shall endeavor to get the first that is made here but how to get them from this place to you is a difficulty that I don't know at present how to surmount, however shall continue to do every thing in my power that you may be fumish'd with guns the want of which I am fully sensible will be the sole cause of the detention of the ship."],["p","You say you find the Commte at Providence has Liberty to appoint Leiuts Sec. I must confess I don't know from whence they got that power but am sure it was not from the Marine Committee or from any man or body deriving their authority from Congress nor is there any one officer appointed for either of the ships at Providence except the Captains.^"],["p","The govt of Philadelphia are all afloat, but they are in a fair way to get things all right. The post is just going off so can't add, save that I am, with respect, yours, Wm Whipple"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v04.0284":{"title":"Edward Rutledge to John Morgan","author_label":"Edward Rutledge","kind":"letter","date":"1776-07-01","date_label":"July 1, 1776","date_type":"written","recipient":"John Morgan","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 4","source_url":"https://archive.org/details/lettersofdelegat04libr","text_status":"unreviewed_ocr","editorial_source_note":"RC (PHi). Addressed: \"Doctor Morgan at New York. Favored by Messrs Smith, [Harleston?] & Burrows.\"","authors":["edward-rutledge"],"paras":[["h","Edward Rutledge to John Morgan"],["p","My dear Doctor July 1. 1776."],["p","As three of my young Countrymen are so principled in the Cause of Liberty as to undertake a Journey to New York for the purpose of yielding their Assistance to repel the Attacks of the Enemy, I have taken the Liberty of troubling you with a Letter of Introduction and trusting in your Friendship for me beg Leave to recommend them to your particuler Notice. I do not know how I could draw their Characters better than by saying that they are Gentlemen; nor could you desire a better Inducement to shew them Civilities than knowing they are my Friends. Should the Fortune of War occasion any Accident to befal them I know your Humanity will afford them every Relief. Our Compliments to Mrs. Morgan. Yours Sincerely & affectionately, Edward Rutledge"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v04.0300":{"title":"John Hancock to George Washington","author_label":"John Hancock","kind":"letter","date":"1776-07-04","date_label":"July 4, 1776","date_type":"written","recipient":"George Washington","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 4","source_url":"https://archive.org/details/lettersofdelegat04libr","text_status":"unreviewed_ocr","editorial_source_note":"RC (DLC). In the hand of Jacob Rush, with concluding paragraph, closing, and signature by Hancock. ^See JCC, 5:508-9.","authors":["john-hancock"],"paras":[["h","John Hancock to George Washington"],["p","Sir, Philadelphia July 4th. 1776."],["p","The enclosed Resolves, to which I must beg Leave to refer your Attention, will inform you of the Steps Congress have taken to establish the flying Camp.i To the unhappy Confusions, that have prevailed in this Colony, must principally be ascribed the Delays that have hitherto attended that salutary Measure. However I flatter myself Things will now take a different Turn, as the Contest"],["p","President John Hancock"],["p","to keep Possession of Power is now at an End, and a new Mode of Government, equall to the Exigencies of our Affairs will be adopted, agieeable to the Recommendation of Congress to the United Colonies."],["p","I am directed to request you will appoint a proper officer for the Command of the flying Camp; and also persons to supply them with Rations."],["p","I have wrote to the severall Committees, and press'd them to forward their Troops with the utmost Dispatch. ^"],["p","I have the Honour to be, with perfect Esteem, Sir, Your most obedt. Servt. John Hancock Presidt"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v04.0397":{"title":"John Hancock to George Washington","author_label":"John Hancock","kind":"letter","date":"1776-07-17","date_label":"July 17, 1776","date_type":"written","recipient":"George Washington","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 4","source_url":"https://archive.org/details/lettersofdelegat04libr","text_status":"unreviewed_ocr","editorial_source_note":"RC (DLC). In the hand of Jacob Rush and signed by Hancock.","authors":["john-hancock"],"paras":[["h","John Hancock to George Washington"],["p","Sir, Philadelphia July 17th. 1776."],["p","Your Favour of the 14th Inst, was duely received, and immediately laid before Congress."],["p","In obedience to their Commands, I do myself the Honour to forward sundry Resolves.^"],["p","The Congress being of opinion, that a Quantity of Powder should be distributed thro' the several Counties of New York and New Jersey, I am to request you will give Directions to have it lodged in the Hands of such Persons as may [be] depended upon."],["p","1 have delivered Monsr. Kermovan his Commission, and directed him to repair immediately to the Jerseys, and put himself under the Officer who commands the Flying Camp.^"],["p","You will please to give Orders respecting the appointment of a Sergeant Major, a Quarter Master General, and Paymaster Genl. in each Regiment — and likewise necessary Directions to General Schuyler with Regard to cleansing the Army of the Small Pox."],["p","Mr. Humpton 8c Mr. Dawson have been Officers in the British army, and I hope will be of Service in ours. They will be ordered to Head Quarters as soon as possible."],["p","Upwards of a Thousand Troops from Maryland are now in this City on their Way to join the Flying Camp in New Jersey. They are an exceeding fine Body of Men, and will begin their March this day.^"],["p","Agreably to the enclosed Resolves, I have wrote in the most vehement and pressing Manner to the Massachusetts Bay, Connecticut, and New Jersey to forward their Militia — and I do not doubt their Compliance immediately."],["p","With the most fervent, and incessant Wishes, that your Head may be covered in the Day of Battle, and that Success may crown your Arms, I have the Honour to be, Sir, your most obed. 8c very hble Servt. John Hancock Presidt"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v04.0436":{"title":"Samuel Adams to Samuel P. Savage","author_label":"Samuel Adams","kind":"letter","date":"1776-07-23","date_label":"July 23, 1776","date_type":"written","recipient":"Samuel P. Savage","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 4","source_url":"https://archive.org/details/lettersofdelegat04libr","text_status":"unreviewed_ocr","editorial_source_note":"RC (MHi). In Adams' hand, though not signed.","authors":["samuel-adams"],"paras":[["h","Samuel Adams to Samuel P. Savage"],["p","My dear Friend Philad July 23 1776"],["p","I must plead the Want of Leisure as an Apology for not acknowledging your very obliging Letter which came to my hand several Months ago. I assure you there is no one with whom I would chuse to keep up an epistolary Correspondence, rather than with you.^ The long Acquaintance I have had with you, and the unsuspected Sincerity of your Friendship, are strong Inducements to me to write to you very frequently — but I cannot give you any Reason to expect it. I would therefore beg you to favor me with your Letters as often as your Leisure will allow. I shall receive them gratefully. You have before this time heard of the Success of the Continental Arms in South Carolina. This happy Event has, I hope, given such a Check to the Power of the Enemy as to prevent their doing us any material Injury in that part of America. I do not say any thing of our Affairs in Canada — the Subject is too mortifying. We must at all times submit to the Determinations of Providence \"whose ways are ever gracious, ever just.\" We now look towards N York. May Heaven prosper our Arms there! The Express which brought the Carolina News, will return in a few days. I shall take that oppy to forward your Letter to your Son. He was in health last Spring as one of the gentlemen of that Colony informs me. The Post is this Moment going. Present my friendly regards to Mrs Savage 8cc & be assured that I am affectionately your Friend"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v04.0519":{"title":"John Adams to William Heath","author_label":"John Adams","kind":"letter","date":"1776-08-03","date_label":"August 3, 1776","date_type":"written","recipient":"William Heath","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 4","source_url":"https://archive.org/details/lettersofdelegat04libr","text_status":"unreviewed_ocr","editorial_source_note":"RC (MHi).","authors":["john-adams"],"paras":[["h","John Adams to William Heath"],["p","Dear Sir Philadelphia Aug. 3. 1776"],["p","Yours of the 20th Ult. is before me.^ I am much obliged to you for it, and most heartily wish for a more free and intimate Communication of Sentiments, upon the State both of our Councils and Arms. I should be happy, in a few Hours Conversation, but as this cannot be, I must be content with a Letter."],["p","We have now a Nation to protect and defend; and I can easily see the Propriety of the observation you quote from the Prussian Hero, that the Prosperity of a State depends upon the Discipline of its Army. This Discipline reared the Roman Empire and the British: and the American will Stand or fall, in my opinion, according as it adheres to or deviates from the Same Discipline."],["p","If there is not Wisdom and Vigour enough in the civil Government to Support the mihtary officers, in introducing and establishing Such a Discipline, it must be owing to the Advantages of Soil and Climate, and our extream Distance from our Enemies, not to our own Strength, Virtue, or Wisdom, if We do not fail."],["p","The Army must be well officered. Armed, disciplined, fed, cloathed, covered, and paid. In these Respects We do as well as We can. Time, I hope, will assist Us, and every officer of the Army, would do well to suggest to his Friends and Correspondents in Congress, and in the Legislatures of the Several States, every defect, and every Improvement in those Particulars, which occurs to him. I am in more Anxiety for Cloaths and Tents than any Thing, because the Health as well as Discipline of the Army, depend much upon them."],["p","We shall never do well, untill We get a regular Army, and this will never be, untill Men are inlisted for a longer Duration, and that will never be effected untill We are more generous in our Encouragement to Men. But I am convinced that Time alone, will persuade Us to this Measure: and in the mean Time We shall, very indiscreetly waste a much greater Expence than would be necessary for this great Purpose in temporary Calls upon Militia, besides risquing the Loss of many Lives, and much Reputation."],["p","Congress has not determined to have no Regard to the Line of Succession in Promotions, but only that this Line shall not be an invariable Rule. Caeteris paribus, the Line will be pursued. But they mean to reserve a Right of distinguishing extraordinary Merit, or Demerit. This Rule may be abused. But is it not necessary? All good Things are liable to abuse. I am afraid, nay I know it will be abused, in particular Instances. But if We make the succession an invariable Rule, will not the Abuse be greater?"],["p","Is it not common in the British Army, to promote junior officers, over the Heads of their Superiours? Nay even officers in the same Regiment and on the same Command? I have been told of several Instances. This however is wrong."],["p","Your opinions of Men and Things, I wish I knew in more detail, because I have a good opinion of your Judgment of both, and I fear, situated as I am, many Things relating to both may not have come to my Knowledge, that I ought to know. As the first officer in the Massachusetts Service, you have in some sort the Patronage of all the officers of that State. I hope you will recommend the best Men for promotion."],["p","I confess myself very ignorant of the military Characters from that State."],["p","By some Expressions in the Close of your Letter, I conclude you were not perfectly Satisfyed with a late Promotion. Be assured. Sir, if that was raising a junior officer, over the Head of any Superiour, it was not considered in that light by the Gentlemen who did it. The"],["p","Person promoted was thought to be the oldest Brigadier, and intituled to Advancement' by the Line of Succession. And it is my opinion he would have been made a Major General much sooner if his Experience had not been thought indispensible in the Adjutant Generals Department.^ I am, Sir, with great Respect, your affectionate Servant, John Adams"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v04.0576":{"title":"John Adams to Thomas McKean","author_label":"John Adams","kind":"letter","date":"1776-08-15","date_label":"August 15, 1776","date_type":"written","recipient":"Thomas McKean","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 4","source_url":"https://archive.org/details/lettersofdelegat04libr","text_status":"unreviewed_ocr","editorial_source_note":"LB (MHi).","authors":["john-adams"],"paras":[["h","John Adams to Thomas McKean"],["p","Dear Sir, Philadelphia Aug. 15. 1776"],["p","I reed your Favour of the 9th instant,^ two days ago, and was exceedingly obliged to you for it, as We have had very little Intelligence from Perth Amboy."],["p","Mr. Secretary Peters, upon my reading your Letter to him, imme-"],["p","diateiy inclosed all the Barons Papers,^ to General Washington, the Board of War not being inclined from any thing they could learn of the Baron to give him the Rank and Pay to which he aspires. It is impossible for me to know whether all the Barons Letters and. Papers are sent, as my Friend Mr S. Adams, before I reed your Letter, was gone to Boston. Mr Peters has inclosed all that were in his Custody."],["p","1 am much obliged to you for the few Anecdotes, of Intelligence, in your Letter and should be very happy in a Continuance of your Correspondence. We have nothing new but the arrival of a Ship from Havre with a fine Cargo of Powder, Lead, Duck and dry Goods."],["p","From N. York We are happy to hear that the Army is increased and that three Regiments have arrived there from Massachusetts, of Militia. The Enemies whole Force is now collected. Great and glorious will be the Fame of our Arms if we can give them their deserts. God grant it, and that you, my dear Sir, may have a large share of the Crop of Laurells. I am &c"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v05.0022":{"title":"Benjamin Franklin to Lord Howe","author_label":"Benjamin Franklin","kind":"letter","date":"1776-08-20","date_label":"August 20, 1776","date_type":"written","recipient":"Lord Howe","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 5","source_url":"https://archive.org/details/lettersofdelegat00smit","scan_url":"https://archive.org/details/lettersofdelegat00smit/page/29","text_status":"unreviewed_ocr","editorial_source_note":"FC (PPAmP).","authors":["benjamin-franklin"],"paras":[["h","Benjamin Franklin to Lord Howe"],["p","My Lord Philada Aug 20. 76 1"],["p","The Temper (& Disposition) of the Colonies as professed in their several Petitions to the Crown was sincere. The Terms they proposed should then have been closed with, and all might have been Peace. I dare say your L[ordshi]p as well as myself, laments they were not accepted. I remember 1 told you that better wd never be offered, 8c I have not forgotten your just Comparison of the Sybyl's Leaves. But the Contempt with which those Petitions were treated, none of them being vouchsaf'd an Answer, and the cruel Measures since taken, have chang'd that Temper. It could not be otherwise. To propose now to the Colonies (a Return to the State of Subjection they were formerly in to the) a Submission to the Crown of Great Britain, would be (useless) fruitless. The Time is past. One might as well propose it to France, on the Footing of a former title."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v05.0047":{"title":"Robert Treat Paine to Samuel and Daniel Hughes","author_label":"Robert Treat Paine","kind":"letter","date":"1776-08-24","date_label":"August 24, 1776","date_type":"written","recipient":"Samuel and Daniel Hughes","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 5","source_url":"https://archive.org/details/lettersofdelegat00smit","scan_url":"https://archive.org/details/lettersofdelegat00smit/page/57","text_status":"unreviewed_ocr","editorial_source_note":"FC (MHi). Addressed: \"To Saml. & Daniel Hughes at Annapolis.\"","authors":["robert-treat-paine"],"paras":[["h","Robert Treat Paine to Samuel and Daniel Hughes"],["p","Sr., Philada. Augt. 24 1776"],["p","Yours which I reed.1 by the bearer I shewed to Govr. Hopkins & we were of opinion that at so short notice we could not determine the size & No. of each Cannon. The Opinion of Congress should be had, & there was not time for that, but I do not see that you need be in the least hindred for doubtless there will be wanted Cannon of all the sizes. If your preparations should be applied towards making Cannon of the largest sizes mentioned I believe it"],["p","would be profitable; from the good Success you have had of making long 18 pounders I have great Expectations that you will furnish us with good 32 & 24 pounders. I believe the length you mention are right for battery Guns, they are 19 diameters. By the Question in yr letter I understand you to refer to Cannon to be made in the new furnaces you mean to build. If you expect to be able soon to make Cannon for Congress in the Furnace you now have (besides those you are about making for the Frigate) you will please to let us know it soon & we will give an answer to that particularly; I heartily wish you Success in this Undertaking, & am yr hble Sert,"],["p","RTP"],["p","P.S. If you write on this Subject, please to add these words to the Direction [of the Cannon Committee] 2 so that should I be absent it may be opened by the Comttee."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v05.0101":{"title":"Caesar Rodney to George Read","author_label":"Caesar Rodney","kind":"letter","date":"1776-09-07","date_label":"September 7, 1776","date_type":"written","recipient":"George Read","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 5","source_url":"https://archive.org/details/lettersofdelegat00smit","text_status":"unreviewed_ocr","editorial_source_note":"RC (DeHi). 1 See Rodney to George Read, September 4, 1776.","authors":["caesar-rodney"],"paras":[["h","Caesar Rodney to George Read"],["p","Sir Philadelphia Sepr. 7th 1776."],["p","Since I wrote last three Letters directed to you have come to my hands. I imagine they are from New York and have sent them with this by the Newcastle Stage."],["p","In my last Letter I gave you the Substance of Sullivans Message and what I then though would be the Determination of Congress thereon.1 However the Matter (after three days debate) has in Some measure received a different determination. The Congress have refused Sending any of their members to Confer as private Gentlemen, but with a view to satisfie some disturbed minds out of Doors, rather than an Expectation of its bringing about Peace they have appointed a Committee of Congress to repair to New York with powers to Confer with Lord Howe, to know the Extent of his powers and the Terms he Shall propose. Genl. Sullivan was furnished with a Copy of this Resolution Certified, and Returned to Lord Howe Yesterday. You will See by this that if Lord Howe Receives the Committee thus Sent he acknowledges the Congress and of Course the Independency of the States, Which I am Convinced he will not do. Yet it may Tend to Convince the people at large that we are desirous of peace whenever it Can be had upon those principals."],["p","There is no Material Change in affairs at New York, Except that a Great part of our Army are gone up to Kings-Bridge, among others the Delaware Battalion, and that Captain Wallace is gone up the East River with his Ship. She was fired on by the fort but not much if any hurt. She proceeded up till She got to a place Called Blackwells Island and Anchored. Our people there with two twelve pounders Oblidge her to Slip her Cable and get behind the Island. I am Sir Yr. most obedt, Humble Servt, Caesar Rodney"],["p","P.S. How goes on your Convention?"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v05.0214":{"title":"Samuel Chase to John Dickinson","author_label":"Samuel Chase","kind":"letter","date":"1776-09-29","date_label":"September 29, 1776","date_type":"written","recipient":"John Dickinson","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 5","source_url":"https://archive.org/details/lettersofdelegat00smit","scan_url":"https://archive.org/details/lettersofdelegat00smit/page/261","text_status":"unreviewed_ocr","editorial_source_note":"RC (PHi).","authors":["samuel-chase"],"paras":[["h","Samuel Chase to John Dickinson"],["p","My Dear Sir Philadelphia Septr. 29th. 1776 Sunday Morning"],["p","It is my very earnest Desire and anxious Wish that you would come to Annapolis.1 I arn satisfied you could render very great and essential Service to our State. However I will not press you to grant that to my importunate Sollictation which you think you can refuse to a whole province."],["p","I beg the favor of you to enclose your Remarks on our draft of Government and Bill of Rights (together with the Bill of Rights) by Tuesdays Post.2"],["p","I wish you every Blessing in this Life and I am, with the greatest Sincerity, Your Affectionate and Obedient Servant,"],["p","Saml. Chase"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v05.0243":{"title":"John Adams to Abigail Adams","author_label":"John Adams","kind":"letter","date":"1776-10","date_label":"October 1776","date_type":"written","recipient":"Abigail Adams","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 5","source_url":"https://archive.org/details/lettersofdelegat00smit","scan_url":"https://archive.org/details/lettersofdelegat00smit/page/302","text_status":"unreviewed_ocr","editorial_source_note":"RC (MHi). Adams, Family Correspondence (Butterfield), 2:137-38).","authors":["john-adams"],"paras":[["h","John Adams to Abigail Adams"],["p","Philadelphia Octr: 4th: 1770"],["p","I am seated, in a large Library Room, with Eight Gentlemen round about me, all engaged in Conversation. Amidst these Interruptions, how shall I make it out to write a Letter? '"],["p","The first day of October, the day appointed by the Charter of Pensilvania for the annual Election of Representatives, has passed away, and two Counties only have chosen Members, Bucks and Chester."],["p","The Assembly is therefore dead, and the Convention is dissolved. A new Convention is to be chosen, the Beginning of November."],["p","The Proceedings of the late Convention are not well liked, by the best of the Whiggs. Their Constitution is reprobated and the Oath with which they have endeavoured to prop it, by obliging every Man to swear that he will not add to, or diminish from or any Way alter that Constitution, before he can vote, is execrated."],["p","We live in the Age of political Experiments. Among many that will fail some, I hope will succeed. But Pensilvania will be divided and weakend, and rendered much less vigorous in the Cause, by the wretched Ideas of Government, which prevail, in the Minds of many People in it."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v05.0311":{"title":"Richard Henry Lee to Unknown","author_label":"Richard Henry Lee","kind":"letter","date":"1776-10-22","date_label":"October 22, 1776","date_type":"written","recipient":"Unknown","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 5","source_url":"https://archive.org/details/lettersofdelegat00smit","scan_url":"https://archive.org/details/lettersofdelegat00smit/page/364","text_status":"unreviewed_ocr","editorial_source_note":"RC ((OClWHi).","authors":["richard-henry-lee"],"paras":[["h","Richard Henry Lee to Unknown"],["p","Dear Sir, Phila. 22d Octr. 1776"],["p","Accept my thanks for your favor of the 1st which I received by this post only. The inclosed paper will give you all the military news that yesterday arrived to Congress.1 Our enemies have been amazingly industrious (as I think wickedness ever is) in Canada, coming out, contrary to all expectation, with 4 times our Marine force on Lake Champlain. The consequence was as you will see, our people bravely maintained the unequal contest, conducting themselves with a valor that has extorted applause even from their enemies, and which certainly deserved a better fortune. Carleton is now Master of the water, but we do not discover any great advantage that will result to him from that possession for this Campaign, as we have an Army equal to his at Ticonderoga, and the Season is fast approaching when no operations can be conducted on Lake Champlain, at least by means of Vessels. The Generals Washington & Howe are maneuvering on the ground above Kings bridge, each endeavoring to out flank the other. In the course of these operations, a few days since, two opposite Brigades met each other, when a very hot contest arose between the enemy and these New England Batallions, and which ended by driving the British Troops back to their main body. The General says, \"our Men behaved with great coolness and intrepedity.\" Private letters say we lost 30 men and the enemy 150 at the least. Gen. Mercer informs us that 150 Sail of Ships came in to the enemy from Sea last Saturday. That the whole power of Great Britain is now exerted against us is most certain, and that it behooves us to strain every nerve in every part of America to oppose them is equally clear; or else Slavery the most ignominious will surely be our lot. We must Cast Cannon, make powder, build Ships and Forts, and raise Armies with unremitting zeal and industry. Cannot we be as brave and industrious in the cause of liberty 8c virtue, as they are in Vice and the establishment of human Slavery? Let us lay aside"],["p","every private consideration, and press the war with force and union. We shall do every thing in our power to procure foreign assistance, and I think a general war in Europe is not far off. May Heaven prosper your righteous consultations and give success to the virtuous cause of America. Farewell. Richard Henry Lee"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v05.0378":{"title":"George Ross to the Lancaster Committee of Safety","author_label":"George Ross","kind":"letter","date":"1776-11-06","date_label":"November 6, 1776","date_type":"written","recipient":"the Lancaster Committee of Safety","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 5","source_url":"https://archive.org/details/lettersofdelegat00smit","scan_url":"https://archive.org/details/lettersofdelegat00smit/page/446","text_status":"unreviewed_ocr","editorial_source_note":"RC (DLC).","authors":["george-ross"],"paras":[["h","George Ross to the Lancaster Committee of Safety"],["p","Gent [November 6, 1776]"],["p","I have the pleasure of informing you that I have now hopes of seeing a happy Constitution Setled for our distracted State. The City of Philada. have exerted themselves as has also the County and have by a Vast Majority carried the Election against the Supporters of the Convention. The whole Tory interest was in favour of the Convention In expectation of Embarrasing our State under a Governmt. Weak but yet Arbitrary but they have failed.1"],["p","I wish for the Honor of Lancaster County they may have Acted with the same Spirit Sc propriety. I am sure of their Affection for the Cause but fear they have been guided more by passion than Judgmt. I hope they will pardon my Apprehensions. They Arise from the best of Motives, my sincere wishes for the happiness of my Country, which is intituled to all the services in my Power to Afford her and which I will ever give. I am with Sincere regard, Your Friend 8c Hble Servt., Geo. Ross"],["p","[PS.] By a letter this day from Genl. Schuyler Congress is informed our Army at Ticonderoga is in a prosperous State & well Supplyed with Provisions. Genl. Carlton is at Crown Point & if he makes an Attack we have good hopes he will meet with a Severe Repulse."],["p","Genl. Washingtons Army in health k Spirits. He sent us this day 22 prisoners — 10 of them Waldeckers."],["p","Philada County City Assembly"],["p","Jno Dickinson Jonn Bayard"],["p","Robt Knox Jos. Parker"],["p","Isaac Hughes Rob Morris"],["p","Fred. Antis Geo. Clymer"],["p","Thos Potts Sam Morris Junr"],["p","Geo. Grey Mick Shubert"],["p","No Counsellor"],["p","No Counsellor"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v05.0395":{"title":"Francis Lightfoot Lee to Landon Carter","author_label":"Francis Lightfoot Lee","kind":"letter","date":"1776-11-09","date_label":"November 9, 1776","date_type":"written","recipient":"Landon Carter","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 5","source_url":"https://archive.org/details/lettersofdelegat00smit","scan_url":"https://archive.org/details/lettersofdelegat00smit/page/461","text_status":"unreviewed_ocr","editorial_source_note":"RC (NN). 'See JCC, 5:765-66.","authors":["francis-lightfoot-lee"],"paras":[["h","Francis Lightfoot Lee to Landon Carter"],["p","My dear Colonel, Philadelphia Novr. 9th. 1776"],["p","Mr. Dye having been hurried away a day or two sooner than he"],["p","expected, prevented my writing to you by him. He will not probably"],["p","be with you sooner than this, as Mr. Colston sets off early tomorrow morning."],["p","I have been so entirely engaged in politics, that I found myself very badly qualified for the business you was pleased to put into my hands; indeed I presently found that Dye wou'd manage it much better than I cou'd; engaged as I was with other business. I therefore desired him to sell your tobo. with the rest, & settle the Accts. with you. I do not think you will suffer by it, bad as the venture has turned out. It wou'd give me pain, if I was not sure you will beleive that it was not want of inclination that prevented my doing the business myself. I have sent you nothing but the medicines, being desirous that you shou'd judge for yourself; after having received full information from Mr. Dye, as to the price of goods here. If you determine to have the other things, Mrs. Lee & myself will purchase them upon the first notice, and I expect there will be many opportunities to Poto. or Rapa."],["p","The exorbitant high prices of good is occasion'd in a great measure by the artifices of the wealthy tories cheifly in this State, in order to distress the Army & people, and to depreciate the Cont. Cury. Congress cannot with propriety interfere in this business; as the states now have powers competent to prevent the evil. The mischief has been pointed out, 8c the states requested to apply a remedy; but unhappily the rage of making regulations for future ages is gone forth, & little attention is paid to immediate defence; while our Enemies, open & concealed, are exerting every nerve to put a speedy end to our political existence. What a fine fund of ridicule, will our fine systems afford to our Victorious adversaries! I entirely agree with your Author, as to the impropriety of Overseers mustering. It woud be well enough to make them keep their arms in good order. However these young hands must run wild a little at first."],["p","You was in the right not to be alarm'd all is well in Congress; only the members grow weary, go off 8c leave us too thin; which obliged us to call for them. There are some, my dear Col. who wish the Congress to be divided 8c contemptible; as that cant be accomplished, the next thing is to make the world think it is so. These endeavors affect me only as the public good is concern'd. Your sentiments with respect to the same persons continuing long in high offices, have my full approbation, 8c therefore tho, I hope, not in the least intoxicated, but most confoundedly tired, I shall next spring beg leave to retire to Virginia, and shall then have the pleasure of laying my conduct before you, as one of my constituents, over a bowl of your good brandy toddy."],["p","Congress made no observations on the report of the Committee to Ld. Howe,1 thinking it better to leave the plain facts to the judgment of the people. This was not my opinion, 8c allways hoped"],["p","some private hand wou'd have done it, but alass! Constitutions employ every pen. I have not yet been able to meet with Doctr. Bond, when I do, shall confer upon the subject of your Letter, & let you know the results. The two mighty British armies are not likely to effect much in the State of N. York this year; when we heard last from Ticonderoga, Carlton was at Crown Point, uncertain whether he wou'd retire into Canada, or make an attempt upon Ticonderoga; if the latter, Cates thinks he can drub him. As to Genl. Howe, after long attempting to get by our Army & penetrate into the Country, we this moment learn by express from Genl. W. that he decamped the other night with precipitation, 8c is making his way toward the City of N. York. The Genl. is uncertain what the Enemy means to do next, but thinks he will either cross the North River & endeavor to come thro' the Jerseys to this City; or will move to the Southward. If his Ships prevent our Army from crossing the North river, we shall be in a bad pickle. I hope the Southern states will be able to keep him at bay, till they are reinforced. But your Convention must really give a truce to every consideration, but warlike preparations. Tis vain to sow the feild, unless it is fenced against the spoiler. Our best respects to our friends of Sabine Hall. I am with much esteem Dear Col., Yr. afft. hble Sevt. Francis Lightfoot Lee"],["p","[PS.] Inclosed is the apothecary's bill for the medicines. I reed. £14 from Dye."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v05.0498":{"title":"Benjamin Rush to John Dickinson","author_label":"Benjamin Rush","kind":"letter","date":"1776-12-01","date_label":"December 1, 1776","date_type":"written","recipient":"John Dickinson","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 5","source_url":"https://archive.org/details/lettersofdelegat00smit","scan_url":"https://archive.org/details/lettersofdelegat00smit/page/563","text_status":"unreviewed_ocr","editorial_source_note":"RC (PHi). Addressed: \"John Dickinson Esqr. at Fairhill.\"","authors":["benjamin-dr-rush"],"paras":[["h","Benjamin Rush to John Dickinson"],["p","My dear sir, Philada. Decemr 1st. 1776."],["p","While I disapprove most heartily of the coalition of parties in the Assembly I cannot help lamenting that you have left the house upon the Account of it. The members from Westmorland & Bedford will turn the scale in our favor as soon as they come to town, and we shall [have] a convention, and a consistant legislature in spite of all their cunning & malice. For the present it becomes us to unite heart %c hand in repelling the common enemy. The eyes of the whole city are fixed upon you. We expect, we are sure you will head your battalion. All our hopes of your future Usefulness in our state depend upon it. Mr. Howe cannot mean to winter in Philadelphia, Unless he is invited here by the slender opposition Genl Washington now makes against him. A body of 10,000 militia will certainly terrify him into Winter Quarters. The safety of the continent depends upon the part Pensylvania will take upon this occasion. The whole state of Pensylvania will be influenced by the city of Philada. and the city waits only to see what part you will take upon the Occasion.1 Excuse the liberty I have taken of suggesting these hints, and believe me to be with the most sincere regard your most Affectionate, humble servant,"],["p","Benja Rush"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v06.0159":{"title":"Richard Henry Lee to Patrick Henry","author_label":"Richard Henry Lee","kind":"letter","date":"1777-01-30","date_label":"January 30, 1777","date_type":"written","recipient":"Patrick Henry","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 6","source_url":"https://archive.org/details/lettersofdelegat06smit","scan_url":"https://archive.org/details/lettersofdelegat06smit/page/165","text_status":"unreviewed_ocr","editorial_source_note":"RC (DLC photostat). Richard Henry Lee, The Letters of Richard Henry Lee, ed. James C. Ballagh, 2 vols. (New York: Macmillan Co., 1911-14), 1:251-52. RC damaged ; missing words supplied from Tr.","authors":["richard-henry-lee"],"paras":[["h","Richard Henry Lee to Patrick Henry"],["p","Dear Sir, Baltimore January 30th 1777"],["p","It is with much pleasure I inform you that our affairs in the Jersies wear as favorable an aspect as we could possibly [hope fo]r. And if the militia remain with the General un[til the othe]r recruits get up, I verily believe the business of [the campaign] will be nearly finished for the] winter. Wonderfful as it m]ay seem, yet it is fact that our great successes in Jersey since the 24th of Deer, have been obtained by an army chiefly irregular, and much inferior in number to the regular force of the enemy."],["p","And the Army that now so greatly and so ignominiously distress the British force at Brunswick is inferior in number to the one it now confines to the Brunswick hills. The Committee of Congress at Philadelphia tell us a report has come there of an engagement between Gen. Sullivans detatchment of the army near Brunswick and a strong detatchment of the enemy. The issue not certainly known but they say a person immediately from Brunswick relates that the British light horse came in much confusion from the field of battle to that Town calling for a reenforcement. We therefore hope hourly for good news from that quarter, nor are we without hopes of good accounts from N. York. We know they were in a very defenceless situation lately, and if the motions of Gen. Heath are not too slow, so that reenforcement may come from Rhode Island or be sent from Jersey for the defence of N. York, he will go near to free that City from the Tyrants Troops. We have no late news from Europe except by the way of Hallifax, where the report is, that a War between France & G. Britain is inevitable, and the B. Officers there say \"the damnd Rebels would keep America yet.\" I hope the rightful Owners will keep America, and in despite of all the efforts of Tyranny & its Tools. Farewell dear Sir, affectionately yours, Richard Henry Lee"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v06.0170":{"title":"Robert Morris to Silas Deane","author_label":"Robert Morris","kind":"letter","date":"1777-01-31","date_label":"January 31, 1777","date_type":"written","recipient":"Silas Deane","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 6","source_url":"https://archive.org/details/lettersofdelegat06smit","scan_url":"https://archive.org/details/lettersofdelegat06smit/page/176","text_status":"unreviewed_ocr","editorial_source_note":"RC (CtHi).","authors":["robert-morris"],"paras":[["h","Robert Morris to Silas Deane"],["p","Dear Sir Philada. Jany 31st. 1777"],["p","I am exceedingly uneasy at a letter received last night from my Friend Mr. James Duff of Cadiz respecting my Brother. He tells me that he had regularly Corresponded with him from the time he arrived in Europe untill he went over to England & that from that time he never answered his letters altho they contained business of moment and I am likely to suffer considerably by the Neglect. He adds that his cxpences were growing very extravagant & in short gives me reason to suppose his Conduct is not right. Circumstanced as I now am with him You may suppose this gives me a most serious alarm. He had been Frolicksom & foolish many times as a Boy, but as I never knew him to depart from principles of honor & integrity in his wildest days, I never entertained a doubt of his becoming an excellent Character in the progress of his Manhood. These Considerations and the good accounts given of him by all my Friends in Spain & Italy induced me not only to commit to his care my own private business in which he is a partner, but to recommend him to the Superintendancy of the Public business as you will have seen heretofore and I know also that he has good mercantile abilities if he will but exercise them properly. However this letter from Mr Duff alarms me most exceedingly as it will make me most unhappy if the Public business shou'd have suffered by this appointment. I have hopes that on receiving my letters he wou'd instantly repair to France, consult you in all things and act under your guidance. If this shou'd be the case I shall be happy, if it is not, much shall I feel on the occasion, however I give you this notice of my alarm the moment I have received it that either his neglect & or abuse of the Trust reposed in him, if any there be, may be remedied the soonest that is possible and I am to inform you that the Secret Committee have agreed to join Alderman William Lee Esqr, late of London, now supposed to be in France, with my Brother in this Commission. Therefore you can immediately give him Notice of it and letters authorizing him to Act will follow this immediately; at present there is not time for it, neither are the rest of the Secret Committee here. I have by this Conveyance wrote to my Friend Mr. John Ross of this place now in Europe (I expect in France) giving him a full account of this affair and authorizing him if he finds my Brother to have been faulty, immediately to get from him all letters & papers that regard the Public or my own business together with a Power of atty from my Brother to Act in his name & behalf until such time as a proper arrangement shall take place. Mr. Ross unluckily is a Scotch Man, but he is a Staunch American or I am much deceived. He was manv years my Neighbour. We have done a great deal of business together and I know him to be a capable steady merchant, regular and punctual, therefore I most cheerfully commit my own affairs to his guidance & the Public will benefit by any direction he may have in theirs. I recommend this Gentn"],["p","to your Friendship but as to Politics you'l use your own discretion in trusting him or not as he is from North of Tweed, but I am confident he is a fast Friend to the interest of this Country, indeed it is his own interest to be so. Shou'd Mr Ross be in France when you receive this he will do the needfull immediately; if he is not there you will take the proper care of all public effects untill he comes. At the same time I must flatter myself with the hope that my present fears are needless. This will be delivered you by Capt Thos Bell whom I have sent over with the Public dispatches to you (Gentn Commissioners) and herein you will find enclosed a letter directed to my Brother left open & dated the 29th Inst.1 before I had any reason to doubt his Prudence. By this you will find I have procured Capt Bell a Commission for a Privateer & that my Friend Mr Jno Maxwell Nesbit is to be interested therein to the Amount of One Thousand pounds Sterling and myself to the same amount & that we proposed you & my Brother shou'd make up the rest of the concern to compleat such a Cruizer as you shou'd deem best calculated for success. If my Brother is doing what he ought to do and has your approbation to his Conduct he may still go on with this business. If the reverse Mr Ross can do it well or you may appoint any other person that you think proper, but as Capt Bell goes so long a Voyage for this purpose & you have encouraged the plan he must not be disapointed. I have Shipped some Tobacco by the ship he goes in consigned to Messrs. Pliarne, Penet & Compy with orders to sell it to the best advantage and to comply with your orders to the amount of One Thousand Pounds Sterling which is to pay for my interest in this Privateer. Mr. Nesbit says he has some bills but not enough for his share, he expects to have some money in my Brothers hand from a former consignment & he will send forward other effects soon to make it up. He is a Man of honor & Fortune and may be depended on; therefore do not let him be disapointed & to prevent it I have now directed that Messrs. Pliarne, Penet & Co shou'd Account with you for the whole net proceeds of 86 hhds of Tobo by this Ship which I hope will neat above £20 stg per hhd. If Mr Ross fits the Privateer you can transfer this order to him, if my Brother does it transfer it to him & if the whole is not wanted only take so much as is required leaving the remainder with Messrs Pliarne, Penet & Co for future orders. There are four hhds of Furs onboard this Ship also consigned to these Gentn. They are for Public account and the net proceeds to be remitted to you. Originally they were ordered to My Brother as well as the Tobacco but I have altered the orders to Messrs Pliarne & Co without mentioning the cause. Youl observe that the Cargoes that have geen dispatched from America for Europe consigned to the order of Mr. Thos. Morris have all been directed to Messrs. Pliarne, Penet & Co at Nantes, Messrs. Saml & J.I I. Delap at Bourdeaux & one to Mr. Andw Limozin at Havre de Grace, unless he has fixed other agents in those & other Ports since he received his appointment. Therefore you can readily come at all that have arrived for if he has attended his duty he"],["p","will know and give acct thereof. If he has not the Cargoes & his letters must remain with the above Houses unless they have sent the letters & made the remittances to you, and in that rase you will deliver all the letters that regard my Houses private Concerns to Mr Ross, also any money or effects that may ha\\e come into your hands in consequence of them. I put 100 hhds of Tobo. on their acct onbd the Ship Aurora from Virginia & 50 hhds onbd the ship Farmer, Capt Dashiel, from Maryld both for Nantes directed to Messrs Pliarne & Co. but Consigned to the order of Mr Thos. Morris. The rest of the Cargoes were on Public account. I hope to be relieved from this state of anxiety I am suddenly thrown into by the imprudence of one that I am very desirous of serving and have taken much pains to make a valuable good Man. Cod send he may yet turn out such. I beg my Compts to Doctr Franklin. I am impatient to hear of his safe arrival and shall be very happy when that good News reaches us. I am with sincere Regard & esteem Dr sir, Your affectionate Friend & Obedt hble servant, Robt Morris"],["p","P.S. If you have made any Commercial engagements in which I am interested you may depend on punctual compliance on my part and I shall push away remittances on Public Account fast as possible.2"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v06.0233":{"title":"Benjamin Rush to Robert Morris","author_label":"Benjamin Rush","kind":"letter","date":"1777-02-08","date_label":"February 8, 1777","date_type":"written","recipient":"Robert Morris","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 6","source_url":"https://archive.org/details/lettersofdelegat06smit","scan_url":"https://archive.org/details/lettersofdelegat06smit/page/244","text_status":"unreviewed_ocr","editorial_source_note":"RG (CtY).","authors":["benjamin-dr-rush"],"paras":[["h","Benjamin Rush to Robert Morris"],["p","Dear sir, Baltimore Feby. 8th. 1777"],["p","I have the pleasure of informing you that your letter to Congress of the 4th instant 1 produced a Motion this day for adjourning to Philadelphia. After some debate it was resolved by a majority of one state only not to put the Question.2 One state was accidentally unrepresented for a few minutes or it would have been carried in the Affirmative. The principal design of this letter is to request that you would urge the necessity of our returning to Philada. in your next letter. By our Absence from Philada. we not only depreciate the money there, but we likewise depreciate it by our residence here. The Scarcity of Artificers — the want of a sufficient number of boarding houses — the constant accession of Strangers who have business with the Congress and who create a fluctuation in the quantity of provisions brought into the town have rendered the price of living, and transacting business of all kinds three times as high in this"],["p","place as it is in many parts of the continent and nearly twice as high as in Philadelphia. But there are Other considerations which ought to influence us. Our return will have the same effect upon our politicks that General Washington's late successes have had upon our Arms. Its Operation perhaps may not be confined to the Continent. It may serve our cause even in the Court of France."],["p","Your letter produced another Motion in Congress of greater consequence than the one just now mentioned, namely to raise the interest of money received into our loan offices to 6 per Cent. It produced a very long, and serious debate. The question was postponed 'till Monday next at the request of Connecticut. There is good reason to believe from the part the several states took in the debate that it will be carried in the Affirmative by a majority of two or three states. Col. R H Lee has changed his mind upon this Subject, and was one of the warmest Advocates for raising the interest upon the floor."],["p","We live here in a convent. We confverse] only with One another. We are precluded from all opportunities of feeling the pulse of the public upon our measures. We rely upon the Committee of Philada. to feel it for us — and we expect once more to hear thro' you how it beats upon the Subject of returning to Philadelphia."],["p","From Dr Sir your most humble Servt, B. Rush"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v06.0349":{"title":"Elbridge Gerry to Thomas Gerry","author_label":"Elbridge Gerry","kind":"letter","date":"1777-02-25","date_label":"February 25, 1777","date_type":"written","recipient":"Thomas Gerry","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 6","source_url":"https://archive.org/details/lettersofdelegat06smit","scan_url":"https://archive.org/details/lettersofdelegat06smit/page/364","text_status":"unreviewed_ocr","editorial_source_note":"RC (MHi).","authors":["elbridge-gerry"],"paras":[["h","Elbridge Gerry to Thomas Gerry"],["p","Dr Brother Baltimore Feby 25th 1777"],["p","I have just reed your Favour of Jany 6th, in Answer to a part of wch. give me Leave to refer You to my Letter of the 21st Inst. With respect to my proposal for manning, as well as arming the Vessel that is to bring the Stores, by referring to the Letter I believe it will appear that You have misapprehended it. The premium required by the Under Writers at Salem is too high, & as the other two Setts of Bills Lading will not be wanted at present, You may wait for Oppertunity of safe Conveyance. When Mr. Abbot returns from his Cruise I presume he will pay the Ballances mentioned, but if he should defer it, be kind enough to signify to him my Request relative thereto; also to inclose Mr Harris' Sales of the salt &c. I am sorry to hear from a Marblehead Whig, that the Tories are suffered to take the Lead ; surely Skill is not wanted to regulate these unworthy people, & oblige them to promote the Cause from wch they wickedly have swerved. The noble Steed (some of whose ordinary Qualities they seem to partake ) , becomes a most useful Animal when properly disciplined; & neglected or enlarged soon contracts a Disposition troublesome, & refracting, however I think it will not be long before they'll receive their Quietus in America. By Letters from Mr Dean in France, the powers of Europe were expecting a formal Annunciation of our Independance at their respective Courts.1 He thinks a general War in Europe inevitable; & to confirm the Intention of France, our Agent in the West Indies informs us that he saw a Letter from his most christian Majesty desiring the Commanding Officer at St Domingo (Who having been a considerable Time on that Station had requested Leave to return) in the most pressing Term to remain there till further orders as he would be immediately wanted to take the Command of a considerable Army in that Quarter.2 This the officer has chearfully accepted. I have communicated to Messrs Samuel & Robert Purviance, the"],["p","part of your Letter that relates to them; & the Delegates of the Massachusetts B. having some Interest in their Hands belonging to the State, will probably have no Objection to the taking Mr Purviances Draught on You for such a part as he may want to fulfil your order, & endorsing the same to the assembly. The Raisens are principally sold as these Gentlemen inform me from 50/ to 60/ Currency ; but great Destruction is made in many of the Casks by Neglect & Vermin."],["p","In Addition to the 88 Batalions wch You mention, 28 of Infantry, 4 of the Train & 3 or 4 of Cavalry are now recruiting ; I hope no Means to raise, arm, & cloath them will be unessayed & when this is accomplished I think We shall under providence have agreable prospects of Success."],["p","I inclose You a Copy of Mr Haydens Note & order thereon; the original If sent might miscarry & be attended with Inconveniences. The Capture of the two prizes wch. you mention, was the Fortune of war & the recapture of them is only the Reverse, or as the Frenchman says, the same Thing; \"Fort' de Ger [Guerre?].\""],["p","The Enemy are again collecting their Force at Brunswick probably with a View to pursue their former Design; Congress have however, Intentions to reutrn to that City, & as it will give a good Appearance to our affairs at Home & abroad, I hope they will pursue this plan. I remain as before, yours with sincere Esteem, E Gerry"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v06.0501":{"title":"John Hancock to the Virginia Governor and Council","author_label":"John Hancock","kind":"letter","date":"1777-04-02","date_label":"April 2, 1777","date_type":"written","recipient":"the Virginia Governor and Council","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 6","source_url":"https://archive.org/details/lettersofdelegat06smit","scan_url":"https://archive.org/details/lettersofdelegat06smit/page/527","text_status":"unreviewed_ocr","editorial_source_note":"LB (DNA: PCC, item 12A).","authors":["john-hancock"],"paras":[["h","John Hancock to the Virginia Governor and Council"],["p","Gentlemen, Philada. April 2d. 1777."],["p","The enclosed Copy of a Letter from General Washington containing the most important Intelligence, I am commanded by Congress to transmit to you with the greatest Expedition."],["p","Altho from this Information the Enemy are said to have in View an Attack on some Part of Maryland, yet as it is uncertain where they will bend their Force, it is highly necessary that each State, and yours in particular, should make every Preparation for Defence. I am therefore most earnestly to request you will take such Measures in Concurrence with Govr. Johnson, to whom I have wrote on the Occasion, as will be most effectual to counteract the Designs & Plans of our Enemies.1 I have the Honour to be, Gentlemen, your most obed. & very hble Servt."],["p","J. H. Presid."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v06.0596":{"title":"John Adams to Abigail Adams","author_label":"John Adams","kind":"letter","date":"1777-04","date_label":"April 1777","date_type":"written","recipient":"Abigail Adams","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 6","source_url":"https://archive.org/details/lettersofdelegat06smit","scan_url":"https://archive.org/details/lettersofdelegat06smit/page/632","text_status":"unreviewed_ocr","editorial_source_note":"RC (MHi). Adams, Family Correspondence (Butterfield) , 2:219.","authors":["john-adams"],"paras":[["h","John Adams to Abigail Adams"],["p","Philadelphia Ap. 22. 1777"],["p","The Post brought me two Letters from you, this Morning, one of the 7th instant, and one before."],["p","You seem to be in fine Spirits — I rejoice at it."],["p","General Gates has commanded in Philadelphia, untill about a Fortnight ago, he went to Ticonderoga, where he is to command all Summer."],["p","Schuyler is here, where he now commands. We are crouding along Soldiers to the General, as fast as they get well of Inocculation."],["p","I think our N. Englandmen have been rather tardy, but I hope soon to hear of the Arrival of their Men at Morristown. The Army there, and at Ticonderoga too, is too weak."],["p","But Howes Army is weak too. Let the Tories, and Cowardly Whiggs, exagerate, as much as they will, How has not in all America, Ten Thousand Men fit for Duty, nor in my Opinion Seven."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v07.0033":{"title":"John Adams to James Warren","author_label":"John Adams","kind":"letter","date":"1777-05-06","date_label":"May 6, 1777","date_type":"written","recipient":"James Warren","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 7","source_url":"https://archive.org/details/lettersofdelegat07libr","text_status":"unreviewed_ocr","editorial_source_note":"RC (MHi). In Adams' hand, though not signed.","authors":["john-adams"],"paras":[["h","John Adams to James Warren"],["p","Dear Sir Philadelphia May 6. 1777"],["p","About Ten Days ago, I had the Boldness to make a Motion that a Navy Board Should be established at Boston — certain Gentlemen looked Struck and Surprised — however it passed. I have moved, I believe fifteen Times, that a Nomination should take Place. Certain Gentlemen looked cold."],["p","Two or three Days ago, the Nomination came on. Langdon, Vernon, Deshon, Dalton, Orne, Henley, Smith, Cushing, and Warren were nominated. This Day the Choice came on. At last Vernon, Warren and Deshon were chosen. The Board are to appoint their own Clerk who is to have 500 Dollars a year.1"],["p","I hope you will engage in this Business and conduct it with Spirit. You cannot be Speaker, and do this Duty too, I believe.2"],["p","I think the Town of Boston, will be offended. But I could not help it. This you will not mention. The salary for the Commissioners is 1500 Dollars a year. You will have the Building and fitting of all ships the appointment of officers, the Establishment of Arsenals and Magazines &c, which will take up your whole Time. But it will be honourable to be so capitally concerned in laying a Foundation of a great Navy. The Profit to you will be nothing. But the Honour and the Virtue, the greater."],["p","I almost envy you this Employment. I am weary of my own, and almost with my Life. But I ought not to be weary in endeavouring to do well."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v07.0052":{"title":"John Adams to Nathanael Greene","author_label":"John Adams","kind":"letter","date":"1777-05-10","date_label":"May 10, 1777","date_type":"written","recipient":"Nathanael Greene","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 7","source_url":"https://archive.org/details/lettersofdelegat07libr","text_status":"unreviewed_ocr","editorial_source_note":"FC (MHi).","authors":["john-adams"],"paras":[["h","John Adams to Nathanael Greene"],["p","Philadelphia May 10. 1777 Yours of the 7th was brought me this Morning.1 My Meaning was that if the Conduct of our Army had depended on me, I should have taken more Pains to have obtained exact Information of the Enemies Numbers, and our own, and should have considered every Inclination of the Enemies Intentions of coming to Philadelphia more particularly. Altho there is no doubt that Congress have authority to direct the military operations, yet I think they would be unwise to attempt it. This must be left to the General officers."],["p","We have not the Information that you have respecting our own Force. There is not a Man in Congress who knows what Force you now have in N. Jersey. We have had no Returns a long time and the opinions of Gentn who come from Camp are very various. My Constituents have a Right to expect that I give my Council whenever it may be usefull; and my Constituents shall not be disappointed. If you knew how manv dozens of my opinions are rejected where one is adopted, you would not think they had much Weight. But enough of this."],["p","My opinion last Summer was very consistent I believe, with that in my last Letter. A Man may be humble before the Enemy, and proud before a Friend. Some who think too little of their Powers and Forces against the Enemy, think too highly of their own Importance, among their Friends, and treat the latter with less Delicacy than they would the former. For my own Part I care not how haughty Men are, to the Enemies of their Country, provided they have Regard to Truth & Justice, nor how humble they are among its Friends."],["p","If by the finer Feelings of the Gentlemen of the Army, are meant their Moral Feelings, no Man detests more than myself, the Idea of hurting them. But if Vanity, and Pleasure is meant, I think, no Harm would be done by mortifying it. I am much mistaken and much misinformed, if the nice Feelings, the Pride, the Vanity, the Foppery, the Knavery and Gambling among too many of the officers, do not end in direct Endeavours to set up a Tyrant sooner or later, unless early Endeavours are used to controul them. I dont mean by this, any General Reflections upon the officers, most of whom I believe"],["p","to be good Citizens at present, but by the Representations We hear there are so many of an opposite Character, that there is danger that the Contagion will Spread."],["p","The Necessity of establishing an Army, Superiour to all our Enemies, is obvious, and, for my own Part, I dont See any Thing in the Power of Congress to do, to accomplish this great Purpose, but what has been done. If you think of any Thing more that is proper to be done, I should thank you for the Hint. I have Reason to believe upon very good Authority, that foreign Troops might be hired, both Germans, Swiss and French. What think you of the Policy of hiring them ? The Waste of the Natives of the Country, in the Army, is a melancholly, and an alarming Consideration. We want People, for Agriculture, Manufactures, Commerce and war, both by Sea and Land."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v07.0077":{"title":"John Adams to Abigail Adams","author_label":"John Adams","kind":"letter","date":"1777-05-14","date_label":"May 14, 1777","date_type":"written","recipient":"Abigail Adams","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 7","source_url":"https://archive.org/details/lettersofdelegat07libr","text_status":"unreviewed_ocr","editorial_source_note":"RC (MHi). Adams, Family Correspondence (Butterfield) , 2:238.","authors":["john-adams"],"paras":[["h","John Adams to Abigail Adams"],["p","May 14. 77"],["p","Prices with you are much more moderate than here. Yesterday I was obliged to give Forty shillings Pen. Cur., Thirty Two L.M.1 for one Gallon of Rum."],["p","In my station here, I have Business with many Gentlemen who have occasion to visit me, and I am reduced to the Necessity of treating them with plain Toddy and Rum and Water — a Glass of Wine, once in a while to a great stranger, of uncommon Consideration."],["p","The Prices of Beef, Pork, Veal, Mutton, Poultry, Butter, Cheese, Milk is Three Times higher, here than with you."],["p","I live like a Miser, and an Hermit, to save Charges, yet my Constituents will think my Expences beyond all Bounds. My Love to Dr. Tufts. I have received two agreable Letters from him, which I will answer as soon as I can.2"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v07.0128":{"title":"Elbridge Gerry to Unknown","author_label":"Elbridge Gerry","kind":"letter","date":"1777-05-27","date_label":"May 27, 1777","date_type":"written","recipient":"Unknown","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 7","source_url":"https://archive.org/details/lettersofdelegat07libr","text_status":"unreviewed_ocr","editorial_source_note":"RG (MB).","authors":["elbridge-gerry"],"paras":[["h","Elbridge Gerry to Unknown"],["p","My dear sir Philadelphia 27th May 1777"],["p","Being now in Congress I am unable to reply to your last Favours, & have only Time to inclose You a Warrant on the Loan office for the Money due to You in Consequence of an Error attending the last Adjustt. of your Account. I suffer much from Want of Exercise & Relaxation, shall however not leave Congress while I am able to attend the Business, as I wish much to see several Matters compleated, particularly the Confederation, before my Return."],["p","I am much in Haste sir your assured Friend & huml. sert."],["p","E Gerry"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v07.0132":{"title":"John Adams to Abigail Adams","author_label":"John Adams","kind":"letter","date":"1777-05-28","date_label":"May 28, 1777","date_type":"written","recipient":"Abigail Adams","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 7","source_url":"https://archive.org/details/lettersofdelegat07libr","text_status":"unreviewed_ocr","editorial_source_note":"RC (MHi) . Adams, Family Correspondence (Butterfield), 2:250.","authors":["john-adams"],"paras":[["h","John Adams to Abigail Adams"],["p","Philadelphia May 28. 1777 An horrid cold Day for Election — warm work however, in the Afternoon, I suppose.1"],["p","You will see by the inclosed Papers, among the Advertisements, how the Spirit of Manufacturing grows. There never was a Time when there was such full Employment, for every Man, Woman and Child, in this City. Spinning, Knitting, Weaving, every Tradesman is as full as possible. Wool and Flax in great Demand."],["p","Industry will supply our Necessities, if it is not cramped by injudicious Law — such as Regulations of Prices &c, Embargoes &c. These discourage Industry and turn that Ingenuity which ought to be employed for the general Good, into Knavery."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v07.0187":{"title":"Francis Lightfoot Lee to Richard Henry Lee","author_label":"Francis Lightfoot Lee","kind":"letter","date":"1777-06-17","date_label":"June 17, 1777","date_type":"written","recipient":"Richard Henry Lee","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 7","source_url":"https://archive.org/details/lettersofdelegat07libr","text_status":"unreviewed_ocr","editorial_source_note":"RC (PHi).","authors":["francis-lightfoot-lee"],"paras":[["h","Francis Lightfoot Lee to Richard Henry Lee"],["p","Dear Brother, Philadelphia June 17. 1777"],["p","On Friday last we received advice from Genl. Sullivan that the Enemy was advancing with their whole force, in two columns, one to Prince town, the other to Coryel's ferry. As we knew Genl. Howe had arrived at Brunswick with a considerable body of troops, It threw this City into great consternation, being in no state of defence, tho it has had so long warning. Sullivan with 1600 Continental] troops & as many Jersey militia marched on Saturday to Coryel's ferry, secured his baggage, heavy Cannon & the boats; and on Sunday morning expected to be join'd by 2000 more J. militia, when he proposed to meet the Enemy, harrass them & retard their march. We learn since that it was only part of Howe's Army, and that they are encamped at Somerset Courthouse. Genl. Washington writes that he did not think it proper to follow them immediately as he supposed their principal intention was to draw him out of his strong camp into the plain being as yet much superior in numbers & their train, that he had endeavor'd to harrass them with light troops but with little effect, being too well guarded with Artillery.1 Genl. Arnold, who is guarding the passes upon the River, wrote us yesterday, that the Jerseys are all in Arms; presses for the Militia of this State to be sent forward directly, for that if the party at Somerset shou'd escape, still Howe must be attacked while the spirit of the people is so high. Unhappily, tho the parties here have droped their dispute, yet things were left in such confusion by it, that it will be some time before they can be got into order. However as Genl. W. has order'd most of the troops at Peek's Kill to join him, we expect he will be strong enough with the assistance of Jersey to attack Howe. A Letter was reed, yesterday in this City, from a reputable person in Statia dated May 8th who says, he had just reed, a very late Bristol paper which said, the people of England were in the greatest consternation from the certainty of a French war, that there was the hotest press all over England, but very few seamen to be found, that they gave up America as lost, & were beyond measure confounded & distressed. We"],["p","have not yet heard from the Boston fleet. Genl. Gates arrived here yesterday. Every thing is in a very good way in the north. He is extreamly offended with our proceedings towards him, & will certainly leave the service. Your packet for France is not yet gone, & God knows when she will. I wish you wou'd have some measures fallen upon, to prevent the rascally tory Jew engrossers of this City & Baltimore from buying up the Salt & other necessaries imported into Virginia. None of the importations shou'd be allow'd to be exported, but by public agents of some State in distress & they shou'd purchase only under regulations made by the Governmt. Roman de Lyle talks of offering his services to Virginia, & depends upon you for an introduction When he arrives there. What troops shall hereafter come from Virginia, shou'd bring arms with them, for we are exhausted by the militia. My best complimts to the Govr & other friends. Yr. afft. bror. & friend,"],["p","Francis Lightfoot Lee"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v07.0249":{"title":"John Adams to Abigail Adams","author_label":"John Adams","kind":"letter","date":"1777-07-01","date_label":"July 1, 1777","date_type":"written","recipient":"Abigail Adams","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 7","source_url":"https://archive.org/details/lettersofdelegat07libr","text_status":"unreviewed_ocr","editorial_source_note":"RC (MHi). Adams, Family Correspondence (Butterfield) , 2:271-72.","authors":["john-adams"],"paras":[["h","John Adams to Abigail Adams"],["p","Philadelphia July 1. 1777 We have no News: a long, cold, raw, northeast Storm has chilled our Blood, for two days past. It is unusual, to have a storm from that Point, in June and July. It is an Omen no doubt. Pray what can it mean?"],["p","I have so little Ingenuity, at interpreting the Auspices, that I am unable to say whether it bodes Evil to Howe, or to Us."],["p","I rather think it augurs a fine Crop of Wheat, Rye, Barley, Corn, Spelts, Buckwheat, and Grass. It is a Presage of Plenty. Therefore let the Land rejoice. Flax and Cotton will grow, the better for this Weather."],["p","July 2d."],["p","The News Papers, inclosed, with this, will tell you all, that I know concerning the military operations in N. Jersey."],["p","We have a Letter from Arthur Lee, from Spain, giving Us comfortable Assurances of Friendship and Commerce. We may trade to the Havannah and to New Orleans, as well as to Old Spain.1"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v07.0300":{"title":"John Penn to Richard Caswell","author_label":"John Penn","kind":"letter","date":"1777-07-12","date_label":"July 12, 1777","date_type":"written","recipient":"Richard Caswell","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 7","source_url":"https://archive.org/details/lettersofdelegat07libr","text_status":"unreviewed_ocr","editorial_source_note":"MS not found; reprinted from N.C. State Records, 11:736.","authors":["john-penn"],"paras":[["h","John Penn to Richard Caswell"],["p","Dear Sir, Philada. July 12th 1777"],["p","Having been informed that the Troops belonging to our State could not part with the money they brought with them, but at a very great loss, Doctor Burke and myself thought it reasonable to exchange with the Men, by giving them an equal number of Continental dollars, which Mr. Blunt at our request did, amounting in the whole to 2485 1/2 dollars agreeable to the inclosed list — we hope the money will be of use with you, indeed it was lost to the Soldiers here."],["p","We have Imployed Lieut. John Allen to Conduct the money from Baltimore and have requested Mr. Helligrass to dispatch him as soon as possibly he can. You will receive the above quantity of dollars besides the 300,000 sent by the Congress, the whole is to be Conducted at the expence of the Continent."],["p","It is still uncertain what General Howe means to do as he remains between Staten Island & New York. Genl. Burgoyne is in the Neighborhood of Ticonderoga, his force is not known. I am afraid we shall not be able to keep that Fort."],["p","Your son is very well, our Troops are near this City waiting for Genl. Howe's movement. With great respect, I am, Dear Sir, Your ob. Serv."],["p","John Penn"],["p","[P.S.] Doct. Burke was out of the way so could not sign this letter."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v07.0357":{"title":"Samuel Chase to Thomas Johnson?","author_label":"Samuel Chase","kind":"letter","date":"1777-07-31","date_label":"July 31, 1777","date_type":"written","recipient":"Thomas Johnson?","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 7","source_url":"https://archive.org/details/lettersofdelegat07libr","text_status":"unreviewed_ocr","editorial_source_note":"Tr (MdHi).","authors":["samuel-chase"],"paras":[["h","Samuel Chase to Thomas Johnson?"],["p","Philada. July 31st. 1777."],["p","Dear Sir,1 Thursday morning 9 oClock"],["p","Inclosed is a copy of the intelligence received this morning from Dover.2 I doubt not congress will request at least one thousd. men from our state. Mr Hollingsworth leaves this City immediately, and I take the first chance of giving you notice of the designs of the enemy."],["p","Gen. Washington was expected with the first division (they march in three) at Caryals [Coryell's] ferry last night."],["p","This state is called on for 4500 of their militia, Jersey for 2000, and Delaware for 700."],["p","If you can venture to spare our Artillery, it will be, I believe, necessary to furnish them with field-pieces. You have some Iron ones. There is an universal complaint for arms from every state, and yet 35000 have been imported within the last six months."],["p","Your affectionate and obt. servant. S.C."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v07.0444":{"title":"Richard Henry Lee to Mann Page","author_label":"Richard Henry Lee","kind":"letter","date":"1777-08-17","date_label":"August 17, 1777","date_type":"written","recipient":"Mann Page","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 7","source_url":"https://archive.org/details/lettersofdelegat07libr","text_status":"unreviewed_ocr","editorial_source_note":"RG (MdAN). Addressed: \"Man Page Junr. esquire at Mansfield near Freder- icksburg in Virginia.\"","authors":["richard-henry-lee"],"paras":[["h","Richard Henry Lee to Mann Page"],["p","My dear Sir, Philadelphia 17th Augt. 1777"],["p","We are not able yet to give you any account of the wandering Howe and his fleet, save that they were seen on the 7th instant off Sinapuxen stearing Southward. Our accounts from France say that George depends much on the \"desperate efforts that Howe & Cornwallis must make to redeem their Bankrupt honor.\" 1 His present Manoeuvre seems the effort of a despairing Bankrupt. For what good can result from having multitudes of Men & Horses confined on board Ships at this season of the year, exposed to the torrid hell that beams upon their heads? Gen. Washingtons forces are well placed to meet Gen. Howes return, unless he should visit either extreme of the United States. The main body is about 20 miles from hence on the road to Coryells ferry on both sides of which the Carolina Troops & other Corps (about 2000) are stationed. Sullivan with 2000 more is in the Neighborhood of Morris Town, & Gen."],["p","Putnam with about 5000 occupies the Heights at Peekskill. I lately visited the Army here. It realy makes a fine appearance. Health, discipline, and good spirits, prevail thro the whole. I wish things lookt as well in the North, however I hope they will soon mend in that quarter. Gen. Gates is reappointed to the command there, and the Militia are turning out. Already Gen. Hackerman of the N. York Militia has had an engagement with a part of the enemy and beaten them, having killed 50 Indians on the spot. Congress has ordered 500 Riflemen from this Army to be sent up there immediately to check and chastise the Barbarian Auxiliaries that Burgoyne has brought with him and who are murdering & scalping all before them, Men, Women, & Children; without sparing those who have taken protection & sworn allegiance to the Tyrant. Even inveterate Tories feel the keen edge of the Scalping Knife, and the barbarous butchery of the Tomahawk. Gens. Schuyler & St. Clair are ordered to Head Quarters that an enquiry may be had into the loss of Ticonderoga and its valuable Stores. Tis a shocking affair and cannot, at present, be accounted for. Our accounts from France, late in May, do not promise immediate war, but substantial aid most certainly. Both France & Spain are arming powerfully and with great rapidity. The spirit of the former rises as its Fleet grows stronger, since we understand that the Minister lately replied to Lord Stormont, when he said the peace could not long continue if N. America continued to draw supplies from France, \"Nous ne desiron pas la guerre, et nous ne le craignon pas.\" We neither desire War, nor fear it. The potent armaments of two such dangerous Neighbors must infallibly check the efforts of G. Britain against us, by putting her under a necessity of watching them, and being prepared to defend herself. Doctr. Lee is returned from Spain and gone to the Court of Prussia. I suppose William will soon take his place. Lord Chatham is not dead as report made him, but it seems is better in health than usual, and we understand a late speech of his is arrived at N. York, in which he advises the Lords \"that Peace be made with N. America immediately and on any terms, assuring them they had no more chance to conquer this Continent with the force they had or could get than he would have to conquer Britain with his Crutch and that the longer they carried on the War the more certain would be their ruin, and the greater their disgrace.\" Wise and good Old Man, what pity is it that if Kings will be allowed, they cannot be directed by such Men!"],["p","I believe Manly is certainly taken & the Fox retaken.2 They were greatly overpowered by superior force. My best wishes attend the family at Mansfield."],["p","Farewell dear Sir, Affectionately yours, Richard Henry Lee [P.S.] Colo. Lee & Lady are well."],["p","P.S. Since neither the Northern or Southern posts of this day bring us any account of Howes fleet I am almost sure that he is gone to Charles"],["p","Town South Carolina, which, in its present state, against such a great Land & Sea force, cannot stand. It must fall. Curse on his Canvass Wings. Tis an unfair advantage they take of us. R.H. Lee"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v07.0480":{"title":"John Hancock to George Washington","author_label":"John Hancock","kind":"letter","date":"1777-08-23","date_label":"August 23, 1777","date_type":"written","recipient":"George Washington","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 7","source_url":"https://archive.org/details/lettersofdelegat07libr","text_status":"unreviewed_ocr","editorial_source_note":"RC (DLC). In the hand of Jacob Rush, with signature and postscript by Hancock.","authors":["john-hancock"],"paras":[["h","John Hancock to George Washington"],["p","Sir, Philada. August 23d. 1777. 6 O Clock A.M."],["p","1 am this Moment honored with your Favour of yesterday by the Return Express.1"],["p","Considering the Necessity of strengthening the Army under your Command, and of giving all possible Opposition to the Enemy, the Congress have come to the inclosed Resolves, Copies of which I shall forward in a few Minutes by Express to the sevl. States with the utmost Expedition. I beg Leave to refer your Attention to them, and am with every Sentiment that Esteem and Respect can inspire, Sir, your most obedt. & very hble Servt. John Hancock Prest."],["p","[PS.] I have just Rec'd an Express from Baltimore,2 the Intelligence the same as heretofore transmitted you, that I will not trouble you with the Copies."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v08.0046":{"title":"John Hancock to the Massachusetts Council","author_label":"John Hancock","kind":"letter","date":"1777-10-03","date_label":"October 3, 1777","date_type":"written","recipient":"the Massachusetts Council","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 8","source_url":"https://archive.org/details/lettersofdelegat08smit","scan_url":"https://archive.org/details/lettersofdelegat08smit/page/47","text_status":"unreviewed_ocr","editorial_source_note":"RC (M-Ar). In the hand of Jacob Rush and signed by Hancock.","authors":["john-hancock"],"paras":[["h","John Hancock to the Massachusetts Council"],["p","Gentlemen, York Town: Pennsylvania, Octr. 3d. 1777."],["p","Your Favour of the 17th ulto. enclosing a Copy of a Letter from"],["p","Mr. Loring Commissary of Prisoners, relative to the Exchange of"],["p","Doctor Church for Doctr. McHenry, was duely received and laid before Congress: In Consequence of which I am to inform you, they immediately, and in the strongest Terms, expressed their Disapprobation of the Proposal, and put their Negative upon it.1"],["p","I have the Honour to be, with the greatest Respect, Gentlemen, your most obed & very hble Servt. John Hancock Presidt"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v08.0304":{"title":"Elbridge Gerry to Joseph Trumbull","author_label":"Elbridge Gerry","kind":"letter","date":"1777-11-27","date_label":"November 27, 1777","date_type":"written","recipient":"Joseph Trumbull","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 8","source_url":"https://archive.org/details/lettersofdelegat08smit","scan_url":"https://archive.org/details/lettersofdelegat08smit/page/326","text_status":"unreviewed_ocr","editorial_source_note":"RC (CtHi).","authors":["elbridge-gerry"],"paras":[["h","Elbridge Gerry to Joseph Trumbull"],["p","Dear sir York in Pennsylvania Novr. 27. 1777"],["p","Congress have lately established a new Board of War, upon a Salary of 2000 Dollars per Year for each Member. General Gates is appointed president, General Mifflin, Colo Trumbull, Colo Pickering, & Mr Peters are Members. Three of the Gentlemen have accepted, there remain but two to give their Answers, General Gates 8c yourself. I doubt not, that the first will be in the affirmative, 8c hope that You will follow the Example, as thereby a prospect will be afforded of introducing (Economy 8z Discipline into our Army, 8c affairs in general, without which America cannot be free 8c happy.1 You was unanimously appointed, 8c from the Experience wch Gentlemen have had since You left the Department of Commissary General, of the Incompetency of their Friends to fill the Office, I doubt not that You would have had the offer with the Power of Appointing, I form my opinion from the Temper of the House when it was proposed, the D C Generals of purchases, had You been here to have executed it, 8c there had been a Certainty of your Acceptance. I know not your Sentiments on the Matter, but however they may be, I most ardently wish that You may accept of this Appointment for many Reasons. Colo Reed was nominated 8c would have been appointed, had it not been known to Gentlemen, that your Situation with respect to each would not admit of your sitting together at the same Board. I think there is not the least Doubt of this Fact. Your own affairs need not interrupt your immediate Attendance, as the Super Intendance of all the Commissaries in the eastern 8c northern Department is with the Governor 8c Council of Connecticut, who may displace 8c appoint at pleasure, 8c can direct the issuing Commissaries to receive the provisions now on your Hands, 8c your Accounts may be settled without a constant Attendance on the Commissioners."],["p","The succession of Errors wch have taken place in the Commissary's Department, have reverberated on Congress, & had the Gentlemen Who were the Cause thereof been troubled with an Attention to the Business of rectifying them, I should not have regretted the Consequences, but this Burthen has unreasonably fell on those Who opposed the Errors from the begining, 8c there seems to be a general Conviction that the Business never will be carried on by some of the present officers."],["p","The affairs of Congress go on to our utmost Wishes. Confederation is finished, a Tax of 5000000 on equitable principles is levied on the States, a recommendation to confiscate 8c make Sale of the Estates of Traitors is sent to each State, the Money to be invested in loan office Certificates, And hereafter appropriated by the respective States. Recommendations to the States to meet 8c fix the prices of Labour, internal produce, 8c Imports 8cc, to call in their Currency by"],["p","Loan or Taxes, to open Subscriptions for the Continental Loans in each Town & District under proper Regulations to aid the Loan offices, to supply with Cloathing the Officers of their respective Batalions, at prices proportioned to their Wages, Charging the Surplusage to the united States under suitable regulations, & to give Vigour to the execution of their Laws, are also past by Congress. I hope soon to see the Treasury Office upon a new Establishment, & that your Brother the P M General will be a Commissioner, his Salary is augmented to 125 Dollars per Month, but I think him too valuable for that office, altho it must be acknowledged an important one. By the latest Intelligence from abroad, a War between France Sc G Britain appears to be inevitable. The Enemy have obtained possession of Delaware River, from the Delay of the Army to support Fort Mifflin & Red Bank; I think that an Enquiry into this affair, 2c the Rhode Island Expedition will necessarily take place. I remain sir, with much Esteem yours Sincerely, E. Gerry."],["p","P.S. If you decline this office, it must have all the Effects so far as it respects yourself of giving up the Cause; a Measure that my Friend will never consent to, after having endured greater Toils than may be expected in future."],["p","General Stevens is broke for Drunkeness.2"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v09.0561":{"title":"Gouverneur Morris to George Washington","author_label":"Gouverneur Morris","kind":"letter","date":"1778-05-15","date_label":"May 15, 1778","date_type":"written","recipient":"George Washington","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 9","source_url":"https://archive.org/details/lettersofdelegat09libr","text_status":"unreviewed_ocr","editorial_source_note":"RC (ViU).","authors":["gouverneur-morris"],"paras":[["h","Gouverneur Morris to George Washington"],["p","Dear General. York Town 15th May 1778"],["p","Permit me to congratulate you on the passing a Resolution for a Kind of Establishment at this late Hour. It is not what you wished but it may do. You must pardon a little to the Republicanism of our Ideas. What is a little extraordinary there was no dissentient State and only two Individuals.^ Yet no Measure hath ever been more severely contested. We shall now go thro the Regimental 8c other Arrangements. Those rapidly. You will perhaps get something like an Army by September. How happy are we that even our Negligence cannot ruin us. Had any Man ventured to say we should have been so exceeding dilatory last March and had he said it with Authority the most gloomy Ideas must have filled every Bosom. Your Council of War by what I can learn ended satisfactorily (nay amicably) to all. Thus Wags the World. I am respectfully & sincerely yours,"],["p","Gouvr Morris"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v10.0003":{"title":"Josiah Bartlett to John Langdon","author_label":"Josiah Bartlett","kind":"letter","date":"1778-06-01","date_label":"June 1, 1778","date_type":"written","recipient":"John Langdon","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 10","source_url":"https://archive.org/details/lettersofdelegat10smit","scan_url":"https://archive.org/details/lettersofdelegat10smit/page/5","text_status":"unreviewed_ocr","editorial_source_note":"Tr (DLC).","authors":["josiah-bartlett"],"paras":[["h","Josiah Bartlett to John Langdon"],["p","My Dear Sir, York Town June 1st 1778."],["p","Before you receive this, I suppose you will have rec'd the Order of Congress for going on with your ship, which is to be changed to a two decker and to carry 56 guns— viz 28 of 24 lbs & 28 of 18 lbs.1"],["p","Mr Wentworth was innoculated at Fishkill, rode to Reading where he remained a week, is now here and attended Congress the day before yesterday."],["p","As to news I have nothing material to write you. The substance of the treaty with France you know. The Ship which arrived from Spain only brought a duplicate of that Treaty. Spain will not accede to the treaty till the arrival of her West India fleet, unless drove to it by England. It is then expected she will act as openly as France. Our Ambassadors inform us Spain and Portugal have settled their disputes & Portugal has acceded to the family compact. The extract of a letter in the enclosed paper dated February 28th 1778 is from Mr Lee one of our Commissioners.2"],["p","The common opinion in the army is that the enemy are about to leave Philadelphia, while some suspect it to be only a political manoeuvre to draw our army into a disadvantageous situation and to attack them. The Tories are stealing out of the City and taking the Oaths to the State. We have no further account of the famous British Commissioners who are to restore peace to America. I believe before this time they are satisfied they will effect nothing unless they enlarge the powers given by their late act of Parliament. One of our Ambassadors tells us the British Ministry publicly gave out that they have sent half a million of guineas to pave the way to a reconciliation and that Lord North informed Count Maurepas that he was sure of a majority of Congress. To such vile shifts are they drove to prevent foreign powers from assisting or acknowledging us; but all will be in vain. Give my best regards to General Whipple and remember me to all friends. I shall hope to hear from you as often as convenient."],["p","I am your friend and most obt servant, Josiah Bartlett"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v11.0005":{"title":"Robert Morris to Jonathan Hudson","author_label":"Robert Morris","kind":"letter","date":"1778-10-01","date_label":"October 1, 1778","date_type":"written","recipient":"Jonathan Hudson","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 11","source_url":"https://archive.org/details/lettersofdelegat11smit","scan_url":"https://archive.org/details/lettersofdelegat11smit/page/12","text_status":"unreviewed_ocr","editorial_source_note":"RC (CSmH: Emmet Collection).","authors":["robert-morris"],"paras":[["h","Robert Morris to Jonathan Hudson"],["p","Sir, Philada. Octr. 1st. 17781"],["p","I delivered your last letters which came by Post, to Mr. Whiteside that he might try what could be done with Salt, and I desired him to tell you how much I disapproved of Speculating in that Article. I dislike it because it tends to raise or keep up the price of so necessary an Article Sc I disapproved of it at this time because I think it an 111 judged Speculation. I hope you may not have bought any and wish you to Countermand Your orders immediately.2"],["p","Messrs. Purviances have a Prize Ship on their hands that will carry as it is said 600 hogsheads tobo. 1 beg you will ask them their lowest price for her, tell them I will buy her if they will sell her reasonably but on no other terms will I have any thing to Say to her. I can now buy such Ships in Boston for about £2000 that Money."],["p","I beg you to examine this Ship and give me soon as possible your full k Candid opinion of her & the price they ask for her, which will much oblige, Dr Sir, Your Obedt hble Servt, Robt Morris.3"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v11.0081":{"title":"Richard Henry Lee to Arthur Lee","author_label":"Richard Henry Lee","kind":"letter","date":"1778-10-19","date_label":"October 19, 1778","date_type":"written","recipient":"Arthur Lee","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 11","source_url":"https://archive.org/details/lettersofdelegat11smit","scan_url":"https://archive.org/details/lettersofdelegat11smit/page/77","text_status":"unreviewed_ocr","editorial_source_note":"RC (ViU: Lee Family Papers).","authors":["richard-henry-lee"],"paras":[["h","Richard Henry Lee to Arthur Lee"],["p","My dear Brother, Philadelphia Octr. 19. 1778"],["p","Monsieur the Marquis de la Fayette having done me the honor to take a letter for you, I am happy in the opportunity of bringing two men acquainted with each other whom I greatly love. All good men in these United States esteem the Marquis for his brave and generous attachment to the cause of America, and for the services he has here performed as a General in our Army. It is impossible that a person of such worth should not feel the obligation of returning to offer service to his country when engaged in war. Yet the Marquis still continues a Major General in the Army of the United States, and"],["p","we hope will be permitted by his Sovereign to come back more effectually to our aid, by adopting the plan proposed by Congress, for an account of which I refer you to the Marquis."],["p","Be so kind as [to] introduce my son Ludwell to the Marquis, and charge the Youth to respect Monsr. Fayette as the much esteemed friend of his father. I am my dear brother most affectionately yours,"],["p","Richard Henry Lee"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v11.0317":{"title":"Samuel Adams to James Warren","author_label":"Samuel Adams","kind":"letter","date":"1778-12-09","date_label":"December 9, 1778","date_type":"written","recipient":"James Warren","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 11","source_url":"https://archive.org/details/lettersofdelegat11smit","scan_url":"https://archive.org/details/lettersofdelegat11smit/page/309","text_status":"unreviewed_ocr","editorial_source_note":"RC (MHi: Warren-Adams Papers). In Samuel Adams' hand, though not signed. A continuation of Adams to Warren, November 23, 1778.","authors":["samuel-adams"],"paras":[["h","Samuel Adams to James Warren"],["p","Deer. 9. [1778] The foregoing I had laid aside, & probably should never have forwarded it to you, had not an extraordinary Peice appeared in the last Saturday's paper signd S. Dean, in which he avows himself to be the Author of the Queries I sent you a few Weeks ago.1 I believe you will find the Plausibility of this Performance, which I shall inclose, to be answerable to a Character I have given you in the Letter above. He \"had the Honor to be the Commercial and political Agent of America in Europe.\" He might have said more justly that he had the Honor of being employd by the secret Committee of Commerce as their Agent, and by the secret Committee of Correspondence as their Intelligencer. Mr. A Lee he says \"having by a wanton Display of his Errand, given great & just Cause of Disgust to the Court of Spain, returnd.\" I will relate to you certain Matters which may explain, if that Court was disgusted with him as Mr. D asserts, how it came to pass Soon after the Secret Committee was appointed, which if I remember rightly was about three years ago, they wrote a Letter to Mr. Lee then in England, requesting a political Correspondence with him, and desiring he would give them the best Intelligence he could, and pledging to him their Confidence.2 Mr. Lee being thus honord, in Mr. Dean's Sense, as a political Agent of America, and having the solemn Assurance of Confidence and Secrecy, with his usual fidelity & as became him in that Character, proceeded with unsuspecting Frankness to open to the Committee what he thought as well as what he knew of Men and and Measures. There was at that time in England a Mr. Carmichael, who is lately arrivd in America & since appointed a Delegate in Congress for the State of Maryland. Mr. Lee had a good Opinion of this young Gentleman; and he being at that time about to return hither by"],["p","the Way of France, Mr. Lee thought him a safe hand, and entrusted him with Dispatches to the secret Committee. His Letter was written on the inner Sides of the Outside Leaves of a small pocket Dictionary, and so neatly closd to the Covers as not to afford the least Suspicion if it should meet with the Fate of being taken by the Enemy. Mr. Carmichael took the Dictionary 8c went over to France where he remaind till his late Embarkation for Portsmouth at which place he arrivd last Summer. In France he met with Mr. Dean. The Letter was opend! Who probably committed this Act, Mr. Dana can inform you as well as I can. To him I refer you. I desire you would ask him & if you please let him know that I desire it of you. He can tell you more than I chuse to trust in writing. I hope you are by this time become confidential with him. But this is Digression. I have seen the Letter. It is dated the 3d of June, '76.3 There are containd in it free Sentiments of the Minister of Spain, but such as a Man of Mr. Lee's Integrity could not withhold from the Committee. Such Intelligence, I must say, being thus pyrated— Such Secrets betryd, Judge who \"wantonly displayd his Errand\"— and by whose Means the Court of Spain saw Cause to distrust Arthur Lee, if they did distrust him. I say if they did distrust him, because I doubt the Fact. If they restricted him to the City of Burgos, as Mr. Dean says, I rather think it was owing to the Caution of that Court, least she should too early offend the Court of London by giving Countenance to an American Commissioner."],["p","Mr. Dean says, \"At this Place (Berlin) he (A. L.) was so unfortunate as to do nothing, unless indeed he may give the Name of Business to the Loss of his Papers,\" by which a Discovery was made of the Secrets of his Colleagues &: the British Ministry enabled to counteract the Measures taken for the Benefit of America. The Anecdote is this. In Berlin, Mr. Lee being invited and dining abroad, the British Envoy found Means to get his Closet and his Trunk forcd open and his Papers were pilferd. But Mr. Lee having Intelligence of it, immediately made Application to the Minister of Berlin and by his Interposition the Papers were returnd; as I am informd in a few Hours.4 Mr. Dean designs to hold up my worthy Friend in this Instance as careless of the Secrets of his Colleagues. But what Security is there against the Rape of the Lock? This indeed is the second Instance of his losing his Papers. The first by the Behaviour of the Person to whom he had regularly committed them, for which I will not now give a Name; and the other by the Theft of a British Minister. If he had been as fortunate in the early discovery of the one as the other, Mr. Dean might allow \"the Name of Business\" to be given, if not to the Loss of his Papers, to his Activity &: Address in recovering them."],["p","It is pleasant to see Mr. Dean indulging his Talent in Insinua-"],["p","tion to lead his Readers to conclude that A. L. was secretly intriguing with the British Ministry & thereby embarrassing our Affairs in France. His Acquaintance with the Earl of Shelburne who had formerly been his Patron in England, was the Ground of Suspicion of his disclosing our Secrets; \"joynd to his undisguisd Hatred & Expressions of Contempt of the french Nation in General.\""],["p","I have good grounds to be satisfied from a Conversation I have had with a great Man5 who ought to be and undoubtedly is perfectly acquainted with the french Court, that Mr. L is thought of there differently from what Mr. Dean would have the People here think of him, and that the Insinuation \"that he had given universal Disgust to the Nation whose Assistance we sollicited\" is void of any just Foundation. But so long ago as \"in the Summer of 1777 a Correspondence between a certain Dr. Berkenhout & the Hon Arthur Lee Esq took place.\"6 Aye, and it was \"on political Subjects.\" If Mr. L had left it to be discoverd by the Sagacity of others that there was such a Correspondence between him and Dr. Berkenhout 8c that Dr. B. was in the Confidence of the British Ministry, Mr. Dean might have supposd there were Grounds to suspect Mr. L's Integrity; but unfortunately Mr. Lee told it himself to his Colleagues and related to them a Part of the Correspondence. Mr. D would here insinuate as he did in his Queries that it was a criminal Correspondence. But if it has been, would Mr. Lee have exposd himself to Mr. Dean? The Man whom he conceivd to be his mortal Enemy? Surely not. A wise Minister will endeavor to possess himself of the secret Designs of the publick Enemy. This is done by a Variety of Means. Mr. Lee corresponds with Dr. Berkenhout (as Mr. Dean says) a Confident of the British Ministry. A shortsighted Politician believes or a prejudicd 8c designing Man insinuates that it is a Criminal Correspondence. If it was so, Why was not Mr. D who knew it in the Summer of 1777, so faithful as to acquaint his Constituents, the Congress, of it? To have done this would have shown the Appearance of Fidelity. He relates a Story & as he says himself \"simply\" thus. \"A Gentleman of Character told me that his Correspondent in England\" &c. (See the 3 Collumn of his piece.) Who this Gentleman of Character is, and who the Correspondent in England, it was needless to tell us; but we learn that in Mr. D's Opinion a Gentleman of Character may have an English Correspondent. This Correspondent informed this Gentleman of Character, and because Mr. Dean tells us so, it is sufficient for us faithfully to believe it and damn Dr. Lee's Character. But I fear I have tired your Patience. Adieu."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v12.0135":{"title":"Richard Henry Lee's Draft Report on Silas Deane","author_label":"Richard Henry Lee","kind":"draft","date_type":"written","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 12","source_url":"https://archive.org/details/lettersofdelegat12smit","scan_url":"https://archive.org/details/lettersofdelegat12smit/page/124","text_status":"unreviewed_ocr","editorial_source_note":"MS (Capt. J. G. M. Stone, Annapolis, Md., 1974). In the'hand of Richard Henry Lee.","authors":["richard-henry-lee"],"paras":[["h","Richard Henry Lee's Draft Report on Silas Deane"],["p","[February- March? 1779]"],["p","The Committee appointed to consider &c beg leave to make the following report."],["p","It appears to your Committee that Mr. Deane did engage in private Commerce at the time that he was employed in the public business and having the direction of public monies."],["p","That altho it does not appear in proof that public funds were applied to private purposes as yet a variety of circumstances support the conjecture."],["p","That Mr. Deanes accounts for the expenditure of 37 Livres2 have not yet been settled."],["p","That in the opinion of your Committee it is proper that Mr. Deane should be called upon to make such settlement before the Continental Commissioners of accounts."],["p","That as Mr. Deane proposes to embark for a foreign Country, it is proper that he should, previous to his departure, give bond with sufficient security to repay the public whatever ballance may hereafter appear to be due to the United States."],["p","That it appears by letters of the Secret Committee to Mr. Hodge dated 3 that he was directed to purchase, fit out, and send to America, two well Armed Cutters loaded with Stores for the public use, and he was to lay his instructions before Silas Deane Esqr. and follow his advice in the execution. That these Cutters were not sent to America with Stores as directed but being purchased & fitted out in public and private partnership of which Partners Mr. Deane was one, they were sent to cruise for Prizes on the Coasts of England and Spain contrary to the sence of Congress and the desires of the Court of France. That these Cruises produced disagreable consequences both in France & Spain."],["p","February- March ? 1779 125"],["p","That there appears a contrariety in Mr. Deanes conduct concerning the affairs of Mr. Beaumerchain when he gives information to Congress in his single capacity and when he writes conjunctly with his Colleagues. Representing] in the one case the Stores sent by Mr. Beauhmerchais as private, and in the other informing Congress that this Gentlemans demand had better be settled in France as it was mixed public and private supply."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v12.0154":{"title":"William Whipple to John Langdon","author_label":"William Whipple","kind":"letter","date":"1779-03-02","date_label":"March 2, 1779","date_type":"written","recipient":"John Langdon","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 12","source_url":"https://archive.org/details/lettersofdelegat12smit","scan_url":"https://archive.org/details/lettersofdelegat12smit/page/140","text_status":"unreviewed_ocr","editorial_source_note":"Tr (DLC: Peter Force Collection). 1 That is, George Frost.","authors":["william-whipple"],"paras":[["h","William Whipple to John Langdon"],["p","My Dear Sir, Philadelphia 2d March 1779"],["p","Your favor of the 29th Jany, No 12, came to hand only 2 or 3 days ago; there has been several parcels of money sent to the Navy Board since my arrival here but not in so large sums as I could wish, till a few days ago, when the Committee succeeded in an effort to procure a grant of 500,000 which is gone on and I suppose will be in Boston by the time this reaches you or perhaps Sooner. From this supply I hope you will be furnished with a sufficiency for your present occasions and if you will let me know when the Loan Office is in cash, I will endeavor to procure an order there."],["p","I must refer you to the enclosed papers for news, but as that is an article you seem not to deal in I imagine you are not anxious about it."],["p","I suppose the General Court will meet before this reaches you. I hope you will not fail to choose delegates (whose attendance may be depended on) early in the session. My colleague1 says he shall set out for home by the 10th of April and I am confident he will be as good as his word and there is no pecuniary consideration that will be a temptation to me to tarry through the summer."],["p","Adieu yours &c, Wm. Whipple"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v12.0262":{"title":"Samuel Adams to James Warren","author_label":"Samuel Adams","kind":"letter","date":"1779-03-23","date_label":"March 23, 1779","date_type":"written","recipient":"James Warren","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 12","source_url":"https://archive.org/details/lettersofdelegat12smit","scan_url":"https://archive.org/details/lettersofdelegat12smit/page/231","text_status":"unreviewed_ocr","editorial_source_note":"RC (MHi: Warren- Adams Papers). In Adams' hand, though not signed.","authors":["samuel-adams"],"paras":[["h","Samuel Adams to James Warren"],["p","My dear Sir Philade. March 23. 1779"],["p","I am to acknowledge the Receipt of your Favors of the 1 2th & 28th of February. ' The Letter you mention in the former came to hand, but I am apt to think it will have no Effect at all.2 There was an Omission, in the Navy Boards not having Notice officially of the inclosd Resolution of Congress, but I hope the Delay has not been attended with material Inconvenience.3"],["p","I do sincerely hope the General Assembly will appoint another Person to take my Place here. I wrote a Letter to them last December, requesting that I might be relievd by one of my absent Colleagues or some other Gentleman, and permitted to return to my Family. I find my Health declining, and the Air of this Country is unfriendly to it. I am therefore for that, and other Reasons which I shall mention to you hereafter, steadfastly determind to get my self excused in April or May at farthest. In doing this, I shall immediately make Room for an abler Man. Such may easily be found and, I hope, be prevaild upon to come. I shall also gratify those whose Hearts are bent upon my Removal; and I shall save them Abundance of Pains which they will otherwise be put to, in making their Interest to effect it. These Men agree with me, if in Nothing else, in wishing most cordially for my Retirement from publick Life. Perhaps they would chuse to have me recalled with Disgrace. I hope that will not be in their Power; though I think I could bear even that with becoming Fortitude, for I am conscious that I do not deserve to be disgracd by my Country, and can be happy in the Reflections of my own Mind."],["p","The Arts my Enemies make use of are contemptible. Last year, as you observe, I was an Enemy to General Washington. This was said to render me odious to the People. The Man who fabricated the Charge did not believe it himself. When he endeavord to make others believe it, he attempted to injure me by imposing upon them. His own Heart must therefore reproach him with complicated Acts of Injustice, and if he has any Feeling, he must despise himself. If I indulgd the Spirit of Revenge, could"],["p","I wish for more? Now, you tell me, their Art is to prejudice the People against the Lees, and to propagate that I am a Friend to them. How trifling is this! Am I accountable to the People for my Opinions of Men? If I have found, from long and intimate Acquaintance with those gentlemen that they are, and have been from the Begining of this Contest, among the most able and zealous Defenders of the Rights of America and Mankind, shall I not be their Friend? I will avow my Friendship to these gentlemen in the Face of the World. As an Inhabitant of Massachusetts Bay, I should think my self ungrateful not to esteem Arthur Lee most highly, for his voluntary Services to that State in Times of her greatest Necessity, to the Injury of his private Interest and at the Risque of his Life. Adieu my Friend. I hope to see you shortly."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v12.0481":{"title":"Richard Henry Lee to the Virginia House of Delegates","author_label":"Richard Henry Lee","kind":"letter","date":"1779-05-04","date_label":"May 4, 1779","date_type":"written","recipient":"the Virginia House of Delegates","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 12","source_url":"https://archive.org/details/lettersofdelegat12smit","scan_url":"https://archive.org/details/lettersofdelegat12smit/page/428","text_status":"unreviewed_ocr","editorial_source_note":"RC (Vi: Executive Communications). Addressed: \"Honorable Speaker of the Honorable House of Delegates at Williamsburg in Virginia.\"","authors":["richard-henry-lee"],"paras":[["h","Richard Henry Lee to the Virginia House of Delegates"],["p","Sir, Philadelphia May the 4th 1779"],["p","A long, laborious, and almost unremitting attendance on public business by which I find my health decaying, renders some repose necessary, and compels me humbly to request that the honorable house of Delegates will accept the resignation of my appointment as a Member of Congress, and choose another gentleman to take my place in that Assembly. ' Altho I am happy in seeing the independency of my country so well secured, yet, until it shall be perfectly established, I do not desire totally to withdraw from the public service, relaxation is all my wish; that so I may be enabled to engage again with renewed vigor of mind and body, in any manner that the voice of my country shall please to direct."],["p","I have the honor to be Sir your most obedient and very humble servant,"],["p","Richard Henry Lee"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v13.0033":{"title":"John Dickinson's Committee Notes","author_label":"John Dickinson","kind":"notes","date":"1779-06-07","date_label":"June 7, 1779","date_type":"written","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 13","source_url":"https://archive.org/details/lettersofdelegat13smit","text_status":"unreviewed_ocr","editorial_source_note":"MS (PHi: Logan-Dickinson Collection). In the hand of John Dickinson. Because Dickinson's practice of abbreviating is idiosyncratic, preparing a printed text of his notes presents special difficulties. Little attempt, therefore, has been made to indicate expansion of abbreviations in this text, and c","authors":["john-dickinson"],"paras":[["h","John Dickinson's Committee Notes"],["p","[June 7? 1779]1"],["p","Call for Information from Committee for Q.M.G. & C.G. Departments2— 8c see the Resolution constituting it."],["p","Move for Resolution to promote Enquiry into Condition of Q.M.G. & C. G. in the several States.3"],["p","Call on the several Loan Offices throughout the Continent for Accots of all the Certificates issued in the Name of any person holding An Office in the Q.M.G. or C.G. Departments."],["p","Call on B[oard] of War for Accot of all persons holding Offices in Q.M.G. 8c C.G. Depts. Also Returns of all provisions 8c supplies in the 2 Depts from May 1778 to May 1779 specifying sort, Quantity or number 8c Quality."],["p","Magazines where to be form'd — Particulars to form them. Coll. Wadsworth has promised Us a Calculation on this Department. Get a Calculation of same kind in Q.M.Gs Department including Forage Masters Dept."],["p","Q[uery]. Where to call for necessary Returns in Q.M.G., C.G, Medical Department], Barrack Master G., Commercial Board — (Marine Committee Under this Head bring in new Establishment & Regulations) B. of War, 8c Commissary General of Issues — & Commissary General of military Stores."],["p","See in vol. 7. on the 13 March 1778 the new Regulations [...] C.G. Dept. — which afterwards were superseded."],["p","Enquire strictly into Expence of Expresses."],["p","Call for Result of"],["p","Recommendation to every State to inform Congress of all their respective productions that may be required in public Service."],["p","Call for this Resolution."],["p","Call on Treasury, Board of War, Medical Department, Barrack Master General, Marine Committee, Board of Admiralty or Court of Appeals, Commercial Committee, Committee of Foreign Affairs, Commissary General of purchases and of Issues & Commissary General of Military Stores for Accots of their respective Establishments 8c contingent Expences.4 Navy Boards. Secretary of Congress & bis"],["p","32 Junk 7, 1779"],["p","Office. Loan Offices. Commissary of Prisoners. Commissary of Hides. Commissioners of Accots."],["p","Call on Treasury Department] for an Accot. of their own Establishment & contingent Expences & of the Establishments & contingent Expences of all subordinate Depts depending on them, or of which Returns have been made to their Board."],["p","Do of the Board of War & Marine Committee, Postmaster.5"],["p","Letters dated June 7th 1779 desiring Returns & Information have been addrest to"],["p","The Board of Treasury*"],["p","The Board of War* A Conference has been held"],["p","The Quarter M. G. with the Commissary G. of"],["p","The Commissary G. of Issues purchases"],["p","The Director General* *A11 these I delivd. Myself —"],["p","The Marine Committee* The others I gave to Mr."],["p","The Commercial Committee* Sherman, who promised to"],["p","The Comm G. of Military Stores deliver them as address'd"],["p","The Post Master General"],["p","The Barrack M. General"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v13.0370":{"title":"Francis Lewis to Stephen Sayre","author_label":"Francis Lewis","kind":"letter","date":"1779-08-10","date_label":"August 10, 1779","date_type":"written","recipient":"Stephen Sayre","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 13","source_url":"https://archive.org/details/lettersofdelegat13smit","scan_url":"https://archive.org/details/lettersofdelegat13smit/page/350","text_status":"unreviewed_ocr","editorial_source_note":"RC (PPRF).","authors":["francis-lewis"],"paras":[["h","Francis Lewis to Stephen Sayre"],["p","My Dear Sir Philadelphia 10th August 1779"],["p","Your letter of the 21st Febry 1778 from Copenhagen via St. Croix is the only one I have received from you since the declaration of American Independence, about that time, I wrote you two several letters with duplicates for France, but so many of our dispatches being captured I much doubt whether any came to your hand."],["p","By the different manoeuvres of the British Troops, Congress has been obliged to change their places of residence, from hence to Baltimore, thence to this City, then to York Town and back again to this City where they now reside. When at Baltimore I urged your being appointed a Commissr. to one of the European States, but was answered by the Committee of Forreign Correspondence, that you were then Secretary to Mr. A. Lee's Embassy to the Court of Berlin,2 and proved a barr to your being appointed at that time to another Department. Upon the return of Congress to Phila. in April 1777,"],["p","by a new appointment of Delegates for our State I was not in the nomination, and remained so 'till Decemr. of the same year when I was rechosen, and since that time have been Chairman of the Commercial Committee of Congress."],["p","Your letter together with that from Mr. Frabitius (whose high Character I was well acquainted with when at Copenhagen) was laid before Congress,3 who are very sensible of the advantages that would accrew in a Commercial intercourse with Copenhagen, as several supplies of Russian manufactures might be obtained through that Channel, but we are at the same time apprehensive the Danish Court are too much influenced by that of G. B. to wink at such Commerce, tho' it may be advantageous to the Subject; But our greatest difficulty arrises from the mode of Establishing a fund, Rice, Tobbacco, 8c Indico, are now our principal articles for an European market, and of these we have considerable quantities, but our coasts have been so infested by the British Cruisers that scarsely one Vessell in three escape them, and unless we can establish a fund by loan from some European State, it will be impracticable for us under such circumstances to make payment with our produce, tho' we have more than sufficient in this Country to establish large funds in Europe, could we convey it with any prospect of safety."],["p","France being now engaged in a War with G.B. we cannot expect a loan from thence, and I presume Holland is at present sollicited by the Belligerent powers for money, a postcript to your letter hints a thought by Mr. Fabritius \"that a loan of two or three million of"],["p","Dollars might be negociated at B nt,4 and in case of one years"],["p","punctual payment of the Interest, he is confident any sums may be had at a very low Interest.\""],["p","Your scheme of sending out goods in Danish bottoms to St. Croix or St. Thomas is feasible, and where we could lodge Tobo., Indico &c to be returned in said ships for payment, but the Risque of Captures between this and the Islands is fully as great, however I shall urge Congress to make an attempt in one or the other mode, it will be therefore necessary that you and Mr. Fabritius inform me with the names of Agents in both Islands who may be appointed by you to receive such Effects; I would here observe that Russian manufactures, such as Canvas for our Navy, Brown Sheeting 8c Ravensduck for Tents, Brown 8c white Drillings for the Officers 8c soldiers — also 7/8 Hambro. Dowlas, 8c the best Ticklingbgs. from Hambro for soldiers shirts 8c Overalls, Cordage of all sizes, is always wanted."],["p","At the Commencement of the present dispute with G. B. in order to pay our Armies &c, we were under the necessity of making large emissions of paper money, this our Enemies availed themselves of by counterfeiting many of those Bills to a considerable amount, which by their Emissaries were dispersed through the United States, adding thereby to the then more than necessary quantity for a circulat-"],["p","ing medium, so alarmed the fears of the people that it has rapidly depreciated the present value of our money. The emissions chiefly counterfeited were of May 1777 & April 1778 which by a resolution of Congress are called in, and the public at large convinced of its bad effects, now cheerfully submit to a heavy Taxation, so as to reduce the remainder to nearly its pristine value; Had taxation been made coeval with emissions, the depreciation would in a great measure have been prevented, but taxation has for four years past lain dormant, nor was it possible to be effected sooner, when we consider that the respective States had new modes of government & new constitutions to form."],["p","General Washington has his head quarters at the Highlands on the West side of Hudsons River to cover a strong Post that we occupy on the river at a place called West Point, against which Sir H. Clinton planned an expedition in June last but finding the Post of too great strength, he posted his army nine miles below on both sides the river at opposite points, called Verplanks 8c Stony point, the latter strongly fortified was on the 15th ulto. at night taken by storm, by Genl Wayne with 1200 Men. The Garrison consisting of 606 Men of which 107 was killed & wounded, the remainder surrendered prisoners of War, and are now confined in this City &c."],["p","We have also authentick accounts from Connecticut that another detachment of British Troops from New York & Rhode Island, under the command of Sir George Collier 8c Genl. Tryon, landed at East & West Haven which they burn't, then advanced into New Haven which they plundered, but before they could fire the Town were obliged by the militia to a precipitate retreat to their ships, from whence they proceeded to Fairfield, and Norwalk, both which they also reduced to ashes. This mode of distressing the Inhabitants indiscriminately, will in my opinion have a contrary effect to what they expected, for by these cruelties the people are become so exasperated that they will retaliate with the utmost rigor.5"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v14.0052":{"title":"Samuel Huntington to the Continental Loan Office Commissioners","author_label":"Samuel Huntington","kind":"letter","date":"1779-10-09","date_label":"October 9, 1779","date_type":"written","recipient":"the Continental Loan Office Commissioners","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 14","source_url":"https://archive.org/details/lettersofdelegat14smit","scan_url":"https://archive.org/details/lettersofdelegat14smit/page/51","text_status":"unreviewed_ocr","editorial_source_note":"RC (MHi: Colbourn Collection). In the hand of Oeorge Bond and signed by Huntington. Addressed: \"Commissioner of the Continental Loan Office, In the State of Massachusetts Bay.\" LB (DNA: PCC, item 14). Addressed: \"Circular.\"","authors":["samuel-huntington"],"paras":[["h","Samuel Huntington to the Continental Loan Office Commissioners"],["p","Sir Philadelphia Octobr. 9th. 1779."],["p","You will receive herewith enclosed an Act of Congress of the 6th Instant extending the resolution of Congress of the 29th of June last for promoting Loans, to all sums which may be paid into the Continental Loan Office on or before the first day of March next, to the amount of the blank loan Office certificates which are Already ordered to be struck by Congress. Also giving certain encouragement to persons who shall subscribe Ten thousand dollars or upwards and make punctual payments as expressed in the Act.1"],["p","I am with sentiments of Esteem Your Obedient and Very humble servant, Saml. Huntington President"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v14.0096":{"title":"Samuel Huntington to George Washington","author_label":"Samuel Huntington","kind":"letter","date":"1779-10","date_label":"October 1779","date_type":"written","recipient":"George Washington","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 14","source_url":"https://archive.org/details/lettersofdelegat14smit","scan_url":"https://archive.org/details/lettersofdelegat14smit/page/88","text_status":"unreviewed_ocr","editorial_source_note":"RC (DLC: Washington Papers).","authors":["samuel-huntington"],"paras":[["h","Samuel Huntington to George Washington"],["p","Sir Philadelphia Octor 17th 1779"],["p","You will herewith receive enclosd a Memorial from two Officers"],["p","Stediford 8c Bicker which Congress have referd to the Commander"],["p","in Chief.1"],["p","I am Sir with the greatest Respect your Excys. humble Servant,"],["p","Saml Huntington President"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v14.0132":{"title":"Samuel Huntington to Captains Landolphe, Patot, and Raux","author_label":"Samuel Huntington","kind":"letter","date":"1779-10-26","date_label":"October 26, 1779","date_type":"written","recipient":"Captains Landolphe, Patot, and Raux","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 14","source_url":"https://archive.org/details/lettersofdelegat14smit","scan_url":"https://archive.org/details/lettersofdelegat14smit/page/122","text_status":"unreviewed_ocr","editorial_source_note":"LB (DNA: PCC, item 14).","authors":["samuel-huntington"],"paras":[["h","Samuel Huntington to Captains Landolphe, Patot, and Raux"],["p","Gentlemen, Philada Octr 26th 1779"],["p","Your letter of the 13th instant I received last evening, have communicated the same to the Minister of France Le Chevalier de la Luzerne, 8c shall lay the same before Monsr. Holker the Consul of France at this Port 8c marine Agent, hope he will take the necessary Measures to relieve your present Distresses & procure you the necessary Supplies.1"],["p","You may be assured of receiving all proper assistance & relief that these United States can afford their good Allies. I am with esteem 8c regard, your hble Servant,"],["p","S.H. President"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v14.0244":{"title":"Samuel Huntington to George Washington","author_label":"Samuel Huntington","kind":"letter","date":"1779-11-18","date_label":"November 18, 1779","date_type":"written","recipient":"George Washington","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 14","source_url":"https://archive.org/details/lettersofdelegat14smit","scan_url":"https://archive.org/details/lettersofdelegat14smit/page/211","text_status":"unreviewed_ocr","editorial_source_note":"RC (DLC: Washington Papers). In the hand of George Bond and signed by Huntington.","authors":["samuel-huntington"],"paras":[["h","Samuel Huntington to George Washington"],["p","Sir. Philadelphia Novr. 18th. 1779."],["p","By the act of Congress of this day herewith enclosed, you will perceive 1 am directed to inform your Excellency that they approve of your sentiments and Opinion as expressed in your letter of the 14th Instant, and leave the future measures on that subject to your direction as shall be thought proper upon the Intelligence you may have received.1"],["p","It is presumed your Excellency must have received before this Copies of the dispatches from Genl. Lincoln by Major Clarkson enclosed in my letter of the 10th Inst."],["p","I have the honor to be with the greatest respect, Your Excellency's humble servant. Saml Huntington President"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v14.0410":{"title":"Samuel Huntington to Nathanael Greene","author_label":"Samuel Huntington","kind":"letter","date":"1780-01-14","date_label":"January 14, 1780","date_type":"written","recipient":"Nathanael Greene","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 14","source_url":"https://archive.org/details/lettersofdelegat14smit","scan_url":"https://archive.org/details/lettersofdelegat14smit/page/344","text_status":"unreviewed_ocr","editorial_source_note":"RC (PPAmP: Greene Papers). In a clerical hand and signed by Huntington.","authors":["samuel-huntington"],"paras":[["h","Samuel Huntington to Nathanael Greene"],["p","Sir, Philadelphia Jany. 14. 1780"],["p","You will receive herewith enclos'd an Act of Congress of the 1 1th instant by which you will be informed That the Quarter Master General is directed to take efectual Care that the accounts of all supplies which may be furnished in future by his Department for the Troops of the Convention of Saratoga be kept separate from the accounts of Supplies furnished for the Guards. I am Sir, with Esteem & respect, your hble Servt."],["p","Sam. Huntington President"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v14.0425":{"title":"Samuel Huntington to George Washington","author_label":"Samuel Huntington","kind":"letter","date":"1780-01-21","date_label":"January 21, 1780","date_type":"written","recipient":"George Washington","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 14","source_url":"https://archive.org/details/lettersofdelegat14smit","scan_url":"https://archive.org/details/lettersofdelegat14smit/page/355","text_status":"unreviewed_ocr","editorial_source_note":"RC; (DLC: Washington Papers). In a clerical hand and signed by Huntington.","authors":["samuel-huntington"],"paras":[["h","Samuel Huntington to George Washington"],["p","Sir, Philadelphia Jany. 21st 1780"],["p","I am honour'd with your Excellency's despatches of the 23d, 24th, 25th, & 27th of Decemr, the 2d, 4th, 5th, 8c 18th Instant which have not been in particular before acknowledged.1"],["p","By the act of Congress of this day herewith enclos'd together with the letter from the Board of War therein refer'd to; you will be informed of the request of Colo Armand for promotion to the rank of a Brigadier 8c his claim as stated in the letter from the Board of War; and that I am constrained to request the opinion of your Excellency thereon.2"],["p","I am Sir, with every sentiment of Respect 8c Esteem your Excy's hble Servt, Saml. Huntington President"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v14.0444":{"title":"Samuel Huntington to George Washington","author_label":"Samuel Huntington","kind":"letter","date":"1780-01-25","date_label":"January 25, 1780","date_type":"written","recipient":"George Washington","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 14","source_url":"https://archive.org/details/lettersofdelegat14smit","scan_url":"https://archive.org/details/lettersofdelegat14smit/page/373","text_status":"unreviewed_ocr","editorial_source_note":"RC (DLC: Washington Papers). In a clerical hand and signed by Huntington. 1 See Huntington to Thomas Mifflin and to Philip Schuyler, January 24, 1780.","authors":["samuel-huntington"],"paras":[["h","Samuel Huntington to George Washington"],["p","Sir, Philadelphia January 25. 1780"],["p","Your Excellency will receive herewith enclos'd an Act of Congress of the 20th Instant together with two other Acts of the 14th & 17th of Decemr to which the former refers.1"],["p","These Acts are calculated with a Design to retrench Expences in the several staff Departments and promote as much as possible CEconomy therein."],["p","From a variety of Accounts there seems but too much reason to believe that great & unnecessary Expences have incurred in those departments remote from Head Quarters, and out of the View or Knowledge of the Heads of the Departments."],["p","The Gentlemen appointed Commissioners in the Act of the 20th Instant will be notified to wait on your Excellency at Head Quarters as soon as Circumstances will permit to consult 8c advise on the Subject matter of their Appointment."],["p","I have the honour to be with the greatest respect, your Excy's hble Servant, Sam. Huntington President"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v14.0557":{"title":"Samuel Huntington to Benjamin Lincoln","author_label":"Samuel Huntington","kind":"letter","date":"1780-03-11","date_label":"March 11, 1780","date_type":"written","recipient":"Benjamin Lincoln","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 14","source_url":"https://archive.org/details/lettersofdelegat14smit","scan_url":"https://archive.org/details/lettersofdelegat14smit/page/486","text_status":"unreviewed_ocr","editorial_source_note":"RC (CSmH: HM 22638). In a clerical hand and signed by Huntington.","authors":["samuel-huntington"],"paras":[["h","Samuel Huntington to Benjamin Lincoln"],["p","Sir, Philadelphia March 11. 1780"],["p","You will receive herewith enclosed four Acts of Congress of the 25th February and the 6th, 8th, & 1 1th Instant marked No. 1, 2, 3, & 4.1"],["p","Congress while they are disposed to give every necessary Aid in their Power for the Defense of the southern States by reinforcing the Army under your Command confide in your Wisdom and Prudence that no unnecessary Burthen or Expence will be created by calling out more of the Militia than the Exigency of the Case may at any Time require."],["p","I have the honour to be, with Sentiments of Esteem & regard, your hble servant, Sam. Huntington President"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v14.0616":{"title":"James Madison to Thomas Jefferson","author_label":"James Madison","kind":"letter","date":"1780-03-27","date_label":"March 27, 1780","date_type":"written","recipient":"Thomas Jefferson","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 14","source_url":"https://archive.org/details/lettersofdelegat14smit","text_status":"unreviewed_ocr","editorial_source_note":"RC (DLC: Madison Papers). Madison, Papers (Hutchinson), 2:5-7.","authors":["james-madison"],"paras":[["h","James Madison to Thomas Jefferson"],["p","Dear Sir Philadelphia March 27th. 1780"],["p","Nothing under the title of news has occurred since I wrote last week by express1 except that the Enemy on the 1st. of March remained in the neighbourhood of Charlestown in the same posture as when the preceding account came away. From the best intelligence from that quarter there seems to be great encouragement to hope that Clintons operations will be again frustrated. Our great apprehensions at present flow from a very different quarter. Among the various conjunctures of alarm and distress which have arisen in the course of the revolution, it is with pain I affirm to you Sir, no one can be singled out more truly critical than the present. Our army threatened with an immediate alternative of disbanding or living on free quarter, the public treasury empty, public credit exhausted, nay the private credit of purchasing Agents employed I am told as far as it will bear. Congress complaining of the extortion of the people, the people of the improvidence of Congress, and the army of both. Our affairs requiring the most mature & systematic measures, and the urgency of occasions admitting only of temporary expedients and those expedients generating new difficulties. Congress from a defect of adequate Statesmen more likely to fall into wrong measures and of less weight to enforce right ones, recommending plans to the several states for execution and the states separately rejudging the expediency of such plans, whereby the same distrust of concurrent exertions that has damped the ardor of patriotic individuals must produce the same effect among the States themselves. An old System of finance discarded as incompetent to our necessities, an untried & precarious one substituted and a total stagnation in prospect between the end of the former & the operation of the latter. These are the outlines of the true picture of our public situation. I leave it to your own imagination to fill them up. Believe me Sir as things now stand if the States do not vigorously proceed in collecting the old money and establishing [funds?] for the credit of the new, that we are undone; and let them be ever so expeditious in doing this still the intermediate distress to our army and hindrance to public affairs are a subject of melancholy reflection. Genl Washington writes that a failure of bread has already commenced in the army; and that for any thing he sees it must unavoidably increase.2 Meat they have only for a short season and as the whole dependance is on provisions now to be procured; without a shilling for the purpose, and without credit for a shilling, I look forward with the most pungent apprehensions. It will be attempted I believe to purchase a few supplies with loan office Certificates, but whether they will be received is perhaps far from being certain, and if received will certainly be a most expensive & ruinous expedient. It is not without some reluc-"],["p","548 March 27. 1780"],["p","tance I trust this information to a conveyance by post, but I know of no better at present, and I conceive it to be absolutely necessary to be known to those who are most able and zealous to contribute to the public relief."],["p","March 28. Authentic information is now reed, that the Enemy in their passage to Georgia lost all their Horse,3 the Defiance of 64 guns which foundered at sea, three transports with troops, although it is pretended these troops and the men of the Defiance were saved, and 1 transport with Hessians of which nothing has been heard. By a letter from Mr. Adams dated Corunna 16 Deer, there seems little probability that Britain is yet in a humour for peace.4 The Russian Ambassador at that Court has been lately changed, and the new one on his way to London made some stop at Paris whence a rumor has spread in Europe that Russia was about to employ her mediation for peace. Should there be any reality in it, Mr. Adams says it is the opinion of the most intelligent he had conversed with that the independance of the United [States] would be insisted on as a preliminary: to which G.B. would accede with much greater repugnance than the cession of Gibraltar which Spain was determined to make a sine qua non."],["p","With respect and regard I am, Dr Sir, yrs. sincerly"],["p","James Madison Jr"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v15.0165":{"title":"Robert R. Livingston to Philip Schuyler","author_label":"Robert R. Livingston","kind":"letter","date":"1780-05-21","date_label":"May 21, 1780","date_type":"written","recipient":"Philip Schuyler","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 15","source_url":"https://archive.org/details/lettersofdelegat15smit","scan_url":"https://archive.org/details/lettersofdelegat15smit/page/169","text_status":"unreviewed_ocr","editorial_source_note":"RC (NN: Schuyler Papers).","authors":["robert-r-livingston"],"paras":[["h","Robert R. Livingston to Philip Schuyler"],["p","Dear Sir Philadelphia 21st May 1780"],["p","Mr. Matthews has shewn you the powers of the Committee which with great difficulty we have appointed.' The oposition was exactly such as I expected, 8c from the quarter I mentioned to you, 8c its effect delay 8c a diminution of the power necessary to render the committee extensively useful. I have laboured hard to bring about a recal of the Maryland Line but without success. To move it myself would have lost us the confidence of the Southern States & excited an oposition which would have effectualy deprived us of the power of being useful upon other occasions. I endeavoured to prevail on Mr. Jones or Mr. Matthews to make the proposal, in which case we could have supported it with so much force as to have overborne all oposition. They were brought to wish it, but did not dare to move it when it came to the point so that all that we shall be able to do will be to direct them to return in case they hear the siege is raised before they arrive at Charlestown. I shall myself venture to move tomorrow for the return of Lees corps,2 the cavalry of which have not yet left the place. We have likewise appointed a committee to confer with the Minister on the procuring supplies for the French troops,3 8c to obtain intelligence of the strength of the enemy at the several ports, 8c the soundings of the several bays and harbours &c. I could wish you to communicate to us your Ideas on these subjects. The Minister will either draw bills or pay in specie for the necessaries which his Masters troops may require. This will put them out of danger of want, but what will be its operation upon our supplies?"],["p","How can this matter be best managed to render his credit useful to both?"],["p","On the other subject I would beg the favor of you to communicate the best information you have reed of the force the enemy have to the Norward, the strength 8c the weakness of Canada. And as you are more in the way of procuring intelligence from New York than I am to let me know as much as possible the force of the enemy there & in the neighbourhood."],["p","We have the most warm & pressing representations from our state relative to Vermont, and we expect hourly to have it brought on the carpet here.4 I shall write to Mr. Peabody to come down immediately/' which he has promised me he will do. You will be so obliging as to enforce my representations 8c to send him down as soon as possible, as I think he can be better spared from camp now than hereafter. You will present my comps. to Mrs. Schuyler 8c the Ladies with you. Will you believe that I have not yet ventured to execute your commission in the fullest extent? a new 8c a moritifying instance"],["p","of my infirmity to you in . Let me hear from You from time"],["p","to time 8c believe me most [. . .]ly yours &c."],["p","Robt R Livingston"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v15.0227":{"title":"Samuel Huntington to the States","author_label":"Samuel Huntington","kind":"letter","date":"1780-06-03","date_label":"June 3, 1780","date_type":"written","recipient":"the States","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 15","source_url":"https://archive.org/details/lettersofdelegat15smit","scan_url":"https://archive.org/details/lettersofdelegat15smit/page/244","text_status":"unreviewed_ocr","editorial_source_note":"LB(DNA: PCC, item 15).","authors":["samuel-huntington"],"paras":[["h","Samuel Huntington to the States"],["p","Sir, Circular. Philada June 3. 1780"],["p","Your Excellency will receive herewith enclosed an Act of Congress of the first Instant, in addition to the resolutions of the 25th of February; making further Provision respecting such Supplies as any State may furnish other than, or over 8c above their Quota of Supplies required by the Act of the 25th of February.1"],["p","I have the honour to be &c &c, S.H."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v15.0551":{"title":"Samuel Huntington to Horatio Gates","author_label":"Samuel Huntington","kind":"letter","date":"1780-08-10","date_label":"August 10, 1780","date_type":"written","recipient":"Horatio Gates","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 15","source_url":"https://archive.org/details/lettersofdelegat15smit","scan_url":"https://archive.org/details/lettersofdelegat15smit/page/567","text_status":"unreviewed_ocr","editorial_source_note":"RC (NHi: dates Papers). In a clerical hand and signed by Huntington.","authors":["samuel-huntington"],"paras":[["h","Samuel Huntington to Horatio Gates"],["p","Sir, Philadelphia August 10. 1780"],["p","By the Act of Congress of the 7th Instant herewith enclosed you will be informed, that General Washington is authorized to effectuate an Exchange of Officers, Prisoners of War; and also of the Measures Congress are taking for the Subsistence & Comfort of Officers 8c Privates that may remain Prisoners with the Enemy in these United States.1"],["p","Also that you are authorized to take the necessary Steps for establishing a Resident Commissary of Prisoners in South Carolina or Georgia to have the Care of Prisoners in those Places."],["p","You will further observe the Encouragements offered by Congress in this Act to Volunteer Horsemen in the States from Virginia to Georgia inclusive, to be under your Command, and submitting to your Determination the Number to be raised in each of those States. From the Representations we have received it is hoped a sufficient Number equal to your Wishes may be engaged as Volunteers agreeable to the Terms mentioned in the Act.2"],["p","As a further Aid to your military Chest, you will observe the Ballance of the Quota of ten Millions of Dollars, required of Virginia by the Act of Congress of the 19 of May last, is appropriated to the Southern Department, and ordered when collected to be sent to you for that Purpose. 3"],["p","I have the Honor to be, with great respect 8c Esteem, Sir, your most obedient humble servant, Sam. Huntington President"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v15.0601":{"title":"Samuel Huntington to Thomas Mumford","author_label":"Samuel Huntington","kind":"letter","date":"1780-08-26","date_label":"August 26, 1780","date_type":"written","recipient":"Thomas Mumford","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 15","source_url":"https://archive.org/details/lettersofdelegat15smit","text_status":"unreviewed_ocr","editorial_source_note":"RC (PPIn). In a clerical hand with signature and postscript by Huntington.","authors":["samuel-huntington"],"paras":[["h","Samuel Huntington to Thomas Mumford"],["p","Sir, Philadelphia August 26. 1780"],["p","I am favored with your Letter of the 7 Instant, thank you for the Communication you give me on the Subject."],["p","Congress have uniformly adopted the Practice of admitting all Persons within the British Dominions, or under their Government, to remove themselves with their Effects into these United States, in all cases where the Person applying for Permission can give satisfac-"],["p","tory Evidence that they have never taken Part against us, and are sincerely desirous to riske their Lives 8c Fortunes with the Independance of these United States."],["p","This Practice was adopted upon mature Deliberation, as founded, not only upon Principles of Justice & Humanity, but dictated by good Policy. Upon these Principles, Persons with their Effects coming from Ireland under the Character above described are exempted from Capture; and among the Number that have been permitted to come with their Effects and unite with us I have not heard of any Impostor though it is possible there may be an Instance."],["p","The Case of George Howell you mention may be an Imposition,1 but he gave satisfactory Evidence to Congress of the Sincerity 8c Uprightness of his Intentions 8c Proffession to riske his Life & Fortune with the Independance of these States, and that he had never taken any part against us. Persons of undoubted Character testified, that having been on the Island by Permission, Howell had repeatedly told them in confidence, he was determined to leave the island and take Part with his Country, that he knew he must sacrifice whatever he might leave behind and was desirous to bring off his Effects with him, that he had been impelled by Necessity and Family Connections since he came of Age to remain hitherto upon the Island, that he was now fully determined to come off if he could obtain Permission &c."],["p","In short he gave satisfactory Evidence of the Sincerity of his Intentions 8c Profession to Congress, who have ever appeared very jealous and carefull to guard against Imposition in such Cases and much more in giving Favors or Preference to the Enemies of their Country."],["p","Mr Howell was a perfect Stranger to me and before unheard of, but upon the Representation of his Case, Congress were so far satisfied as to order the President to give him a Permission 8c Passport for himself and his Effects, which I was bound to obey and indeed as his Case then appear'd, I see no Reason why it should not be granted."],["p","If he be an Impostor and has been guilty of deceiving Congress with Respect to his true Character, they would be very desirous to know it, and have him detected and properly punished."],["p","I should be much obliged to you for any Evidence that may be obtained to prove he has from the Beginning of this War appeared an open avowed Enemy to the Independance of America, and that he is a known Enemy to these States, or that his Professions 8c Intentions to Congress were not sincere."],["p","I am perswaded that from your known Attachment to the common Cause and Zeal to promote it, you will readily transmit any such Evidence as may be obtained on this Subject, and I can assure you Congress will not be wanting on their Part to adopt proper Pro-"],["p","ceedings against any Person that has been guilty of such gross Imposition as is supposed in the present Case and on the other Hand if the Man be sincere and innocent, Justice to him requires it should appear."],["p","The Permission granted to Mr Howell is not an uncommon Priviledge, it has been uniformly granted to proper Characters on Application. Congress may have been deceived in Characters, tho' I have never heard of a single Instance. The Case of Mr Howell may be a Deception, if so I most sincerely hope it may be made to appear. The Discovery and Detection is not difficult with those who have the Means of Knowledge, and Justice to our Country requires it should be done."],["p","I have the Honor to be, with Sentiments of Esteem 8c Respect, your most obedient Servant, Sam Huntington"],["p","P.S. Since writing the foregoing I have receivd a letter from Govr. Trumbull on the Same Subject & Shall write him a particular account of the matter.2 S.H."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v16.0043":{"title":"Samuel Huntington to Horatio Gates","author_label":"Samuel Huntington","kind":"letter","date":"1780-09-12","date_label":"September 12, 1780","date_type":"written","recipient":"Horatio Gates","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 16","source_url":"https://archive.org/details/lettersofdelegat16smit","scan_url":"https://archive.org/details/lettersofdelegat16smit/page/54","text_status":"unreviewed_ocr","editorial_source_note":"RC (NHi: Gates Papers). In a clerical hand and signed by Huntington. lJCC, 17:770-73.","authors":["samuel-huntington"],"paras":[["h","Samuel Huntington to Horatio Gates"],["p","Sir Philadelphia September 12. 1780"],["p","You will receive herewith enclosed an Act of Congress of the 24 Ulto.1 making farther Provision for the Officers of the Army respecting their Rations, and extending the half Pay granted to Officers by the Resolution of the 1 5 of May 1778, to the Widows or Children (as the Case may be) of Such Officers as have died or shall die in the Service; also repealing a restricting Clause in the last mentioned Resolution, and ascertaining the half Pay of General Officers in Proportion to their present Pay."],["p","You have also enclosed an Act of Congress of the 11 Instant, requesting the State of Virginia to furnish her Quota of Supplies as speedily as may be, agreeable to the Requisition of the 25 of February last, with an Addition of five thousand Barrels of Flour.2"],["p","You will also observe by this Act of the 1 1 Instant, the Expediency of Sending forward to the Southern Army a Corps of Artillery, and a Reinforcement of Cavalry &c is referred to the Commander in Chief."],["p","I have also enclosed for your Information an Act of Congress of the 12 Ulto. in Consequence of a Memorial from the General Officers.3 This Act which makes Provision in Favour of the Officers & Soldiers was mislaid by Accident in the Secretary's Office, or it would have been sooner transmitted."],["p","1 have the Honor to be, with very great Respect, Sir, your most obedient Servant, Sam. Huntington President"],["p","P.S. Your Despatches of the 30 Ulto have been duly received,4 those addressed to Genl. Washington were immediately forwarded & your Intelligence communicated to the Minister of France agreeable to your Request. S.H."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v16.0050":{"title":"James Madison to Edmund Pendleton","author_label":"James Madison","kind":"letter","date":"1780-09-12","date_label":"September 12, 1780","date_type":"written","recipient":"Edmund Pendleton","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 16","source_url":"https://archive.org/details/lettersofdelegat16smit","scan_url":"https://archive.org/details/lettersofdelegat16smit/page/60","text_status":"unreviewed_ocr","editorial_source_note":"RC (DLC: Madison Papers). Madison, Papers (Hutchinson), 2:80-82.","authors":["james-madison"],"paras":[["h","James Madison to Edmund Pendleton"],["p","Dear Sir Phila. Sepr. 12th. 1780"],["p","I received your favor of the 27th of August1 by last week's post and should not have failed to testify the pleasure with which I embrace your correspondence by an immediate answer had I not understood from Mr. Jones that he proposed to write you the news, and enclose you the paper of the day. In future I shall endeavor to drop you a line by every post, or at least as often as any thing material occurs."],["p","The delay of Ternay's 2d division and the report of its being shut up in Brest have brought our hopes from the present campaign very low. They have been a little revived within a few days by sundry concurring information, that a large French fleet from the West Indies is on our coast. This story is the more credible, as pretty certain intelligence has been reed, that the French & Spanish fleets in that quarter instead of going to Jamaica as every body expected and their own movements announced, had separated from each other, and gone into different ports, and as there is no other place after such an event where the former could act with so much advantage as on our coast in conjunction with Ternay. Should this good news prove true it is to be regretted that Graves did not stay a litUe longer off Rhode Island, unless he should return to Sandy Hook of which no notice has been received, where, as his large ships cannot get into the harbour, they must be an easy prey to the superior force of our Allies."],["p","We have the comfort to find from every successive account from the Southward that the late unfortunate affair in that quarter, although truly distressing, is by no means so fatal as was at first held up to us. Our scattered troops are again embodying, and as a sense of shame is now joined to a sense of public danger in the Militia it is to be hoped they will endeavour to cancel their disgrace by extraordinary exertions. Congress have recommended it to Virga. & N. Carolina to form Magazines for a large army, to the former to hasten the march of her new levies, & the latter to take immediate measures for filling her continental line."],["p","Congress have also at length entered seriously on a plan for finally ratifying the confederation.2 Convinced of the necessity of such a measure to repress the hopes with which the probable issue of the"],["p","campaign will inspire our Enemy as well as to give greater authority & vigor to our public councils, they have recommended in the most pressing terms to the States claiming unappropriated back lands, to cede a liberal portion of them for the general benefit. As these exclusive claims formed the only obstacle with Maryland there is no doubt that a compliance with this recommendation will bring her into the confederation. How far the States holding the back lands may be disposed to give them up cannot be so easily determind. From the sentiments of the most intelligent persons which have come to my knowledge, I own I am pretty sanguine that they will see the necessity of closing the union in too strong a light to oppose the only expedient that can accomplish it."],["p","Another circumstance that ought greatly to encourage us under disappointed expectations from the campaign is the combination of the Maritime powers in support of their neutral rights, and particularly the late insolent and provoking violation of those rights by the English Ships at St. Martins. It is not probable that the injured will be satisfied without reparations & acknowledgements which the pride of Britain will not submit to, and if she can ever be embroiled in an altercation with so formidable a league, the result must necessarily be decisively in our favour. Indeed It is not to be supposed after the amazing resources which have been seen in G. Britain when not only deprived of but opposed by her antient colonies, and the success of the latter in resisting for so long a time the utmost exertion of their resources against her, that the Maritime powers who appear to be so jealous of their rights will ever suffer an event to take place which must very soon expose them to be trampled on at pleasure of G. Britain."],["p","I must beg you once for all to excuse the inaccuracies with which the hurry of the post day will deface my letters."],["p","With sincere regard I am, Dr Sir yr. Obt friend & Servt."],["p","James Madison Junr."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v16.0101":{"title":"Samuel Huntington to George Washington","author_label":"Samuel Huntington","kind":"letter","date":"1780-09","date_label":"September 1780","date_type":"written","recipient":"George Washington","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 16","source_url":"https://archive.org/details/lettersofdelegat16smit","scan_url":"https://archive.org/details/lettersofdelegat16smit/page/118","text_status":"unreviewed_ocr","editorial_source_note":"RC (DLC: Washington Papers). In a clerical hand and signed by Huntington. 1 JCC, 18:876. Washington's letter to Huntington concerning Benedict Arnold's treason is in PCC, item 152, 9:199-202; and Washington, Writings (Fitzpatrick), 20:91-93.","authors":["samuel-huntington"],"paras":[["h","Samuel Huntington to George Washington"],["p","Sir, Philadelphia September 29. 7 oClock P.M. 1780"],["p","I am honored with your Excellency's Despatches of the 26 Instant, which will he laid before Congress in the Morning.1 We had before received Intelligence from General Greene, that Genl Arnold was gone over to the Enemy. Immediately Orders were given to search & seize his Papers & Effects to be found here, which was speedily executed, but I am not yet advised of what particular Discoveries have been made."],["p","With Congratulations on your Return to the Army, I have the Honor to be, your most obedient Servant,"],["p","Sam. Huntington"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v16.0130":{"title":"Samuel Huntington to the States","author_label":"Samuel Huntington","kind":"letter","date":"1780-10-06","date_label":"October 6, 1780","date_type":"written","recipient":"the States","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 16","source_url":"https://archive.org/details/lettersofdelegat16smit","scan_url":"https://archive.org/details/lettersofdelegat16smit/page/153","text_status":"unreviewed_ocr","editorial_source_note":"LB (DNA: PCC, item 15). Copies of this letter addressed to the four \"eastern\" states were intercepted at Stratford Landing, Conn., on October 20. See Huntington to Jonathan Trumbull, November 9, 1780.","authors":["samuel-huntington"],"paras":[["h","Samuel Huntington to the States"],["p","Sir Circular Philada October 6. 1780"],["p","Your Excellency will receive herewith enclosed an Act of Congress of the 21 Ulto, containing a new Arrangement of the Army. Special Reasons have delayed the Sending of it forward to the several States until this Time.1"],["p","By this Arrangement the Number of Battallions is greatly reduced, and of Consequence many of the Officers now retained in the Service must retire for the present; but after just & equitable Compensation is made to them, the Saving of Expence will be very great."],["p","Congress are extremely anxious, not only to avoid the Dangers & Embarrassments heretofore experienced by Delays in recruiting the Army until the Opening of the Campaign; but also to establish a permanent Army, of Troops engaged for the War, to consist of such Numbers as may be adequate to the Service, and at the same Time not exceed the Ability of the States to raise & support, and constantly recruit so as to keep up the Number."],["p","It is recommended to the States in the most pressing Manner to have their Regiments completed & in the Field by the first Day of January next at farthest. The Commander in Chief will cause immediate Returns to be made of the Deficiencies of each State according to this Arrangement.2"],["p","You will observe Sir, that, the respective States are to select from the Line of the Army the Number of Officers to command the several Regiments to them respectively assigned; taking Notice that no new Appointment is to be made of higher Rank than Lieut. Colonel Commandant, for substantial Reasons supposed to be known to all the States."],["p","But the first & immediate Object is to complete the Regiments to their full Number of non Commissioned Officers & Privates; which is recommended in the most pressing Manner as of the greatest Importance."],["p","I have the Honor to be with every Sentiment of Esteem & Respect, your Excellencys most obedient servt, S.H."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v16.0185":{"title":"Samuel Huntington to William Smallwood and Mordecai Gist","author_label":"Samuel Huntington","kind":"letter","date":"1780-10-18","date_label":"October 18, 1780","date_type":"written","recipient":"William Smallwood and Mordecai Gist","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 16","source_url":"https://archive.org/details/lettersofdelegat16smit","scan_url":"https://archive.org/details/lettersofdelegat16smit/page/222","text_status":"unreviewed_ocr","editorial_source_note":"LB (DNA: PCC, item 15). Addressed: \"To Major General Smallwood. The like verbatim to Brigadier Genl Gist.\"","authors":["samuel-huntington"],"paras":[["h","Samuel Huntington to William Smallwood and Mordecai Gist"],["p","Sir, Philada October 18, 17801"],["p","Notwithstanding the Event of the Action near Cambden the 16"],["p","of August last, I have the Pleasure to present you with the Thanks of Congress expressed in the Copy of their Act enclosed of the 14 Instant to yourself in particular and the brave Officers & Troops who distinguished themselves by their Bravery & Valour on that Occasion.2"],["p","I have the Honor to be, with Esteem & respect, &c &c &c,"],["p","S.H.3"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v16.0572":{"title":"Samuel Huntington to George Washington","author_label":"Samuel Huntington","kind":"letter","date":"1781-02-02","date_label":"February 2, 1781","date_type":"written","recipient":"George Washington","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 16","source_url":"https://archive.org/details/lettersofdelegat16smit","scan_url":"https://archive.org/details/lettersofdelegat16smit/page/662","text_status":"unreviewed_ocr","editorial_source_note":"RC (MiU-C: Huntington Papers). In a clerical hand and signed by Huntington.","authors":["samuel-huntington"],"paras":[["h","Samuel Huntington to George Washington"],["p","Sir, Philadelphia February 2. 1781"],["p","By the enclosed resolve of the 1 st Instant your Excellency will be informed that the resolution of Congress of the 4th of September 1778 allowing Officers three Dollars a Day for Expences on Business not incidental to their Office is repealed and to have no Effect from and after the first Day of March next.1"],["p","I am desired by Mr Secretary Thomson to request your Excellency would be so obliging as to forward by the first convenient Opportunity the enclosed Letter addressed to Mr Mathew Cowper.2"],["p","With the highest respect, I have the Honor to be, your Excellency's most obedient & most humble Servant,"],["p","Saml. Huntington President"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v17.0050":{"title":"Samuel Adams to the Public","author_label":"Samuel Adams","kind":"letter","date":"1781-03-13","date_label":"March 13, 1781","date_type":"written","recipient":"the Public","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 17","source_url":"https://archive.org/details/lettersofdelegat17smit","scan_url":"https://archive.org/details/lettersofdelegat17smit/page/55","text_status":"unreviewed_ocr","editorial_source_note":"FC (NN: Adams Papers). In the hand of Samuel Adams, and endorsed by him: \"The foregoing was sent to Mr. Edes by the Post. March 13, 1781.\"","authors":["samuel-adams"],"paras":[["h","Samuel Adams to the Public"],["p","[March 13, 1781]1 \"As we have a Constitution which is admired for its genuine Principles, I have been sollicitous to know whether our Countrymen at large partook of the Spirit of those who formd it. I have conceivd strong hopes, that in organizing the Government and electing Persons to fill the important Places of Trust, no Consideration would have been sufficient to govern their Suffrages in favor of any Candidate unless he was possessd of those Qualities which are"],["p","necessary to enable him to perform the Functions of the Office to be filled, with Advantage to the Publick. I flatterd myself, that both the Governors 8c the governed would have laid aside the gawdy trappings of Monarchy & put on that Simplicity which is the ornament 8c Strength of a true Republick. How far it has been done I am not able to judge at this Distance. It is a great Satisfaction to me to be informd, that some of the best Men in the Commonwealth, are elected into the principal Departments of Governmt. Men, who will dignify the Character of our Country — who will revive & disseminate those Principles, moral 8c political, to propagate which our Ancestors transplanted themselves into this new World — who by the Wisdom of their Councils, and their exemplary Manners, will establish the public Liberty on the Foundation of a Rock. Such men will secure to themselves more of the Esteem of their virtuous, 8c even their vicious fellow Citizens than they could by a thousand courtly Addresses, which are commonly the Breath of Vanity & Adulation. There is a Charm in Virtue to force Esteem. If Men of a different Character have by any Means been advancd to those hallowd Seats, who have even sollicitted publick Employment, to give a Scope to Views of Ambition 8c Avarice, Passions which have in all Ages been the Bane of human Society; or, to gratify the raging Thirst for popular Applause, a Disease with which little Minds are usally tormented, it is our Happiness that the Constitution requires annual Elections, 8c such Mistakes may be corrected at the next."],["p","\"I was sorry to hear that the Number of Votes returnd the last time, did not amount to more than a Quarter of the Number of qualified Electors. The Choice of Legislators, Magistrates & Governors is surely a Business of the greatest Moment, 8c claims the Attention of every virtuous Citizen. The Framers of our happy Constitution while they gave due Attention to political, were not forgetful of Civil Liberty — that personal Freedom 8c those Rights of Property, which the meanest Citizen is intitled to, 8c the Security of which is the great End of political Society. It was not indeed their Province to make particular Laws for these Purposes. To do this, 8c to provide for the equal 8c impartial Execution of such Laws, agreable to the Constitution, is the Duty of the Legislature. Hence every Citizen will see, and I hope will be deeply impressd with a Sense of it, how exceedingly important it is to himself, 8c how intimately the Welfare of his Children is connected with it, that those who have a Share in making, as well as in judging 8c executing the Laws should be Men of singular Wisdom 8c Integrity. Such as are conscious that they are deficient in either of these Qualities, shoud even tremble at being named as Candidates! I hope the great Business of Elections will never be left by the Many to be done by the Few; for that few, before we are aware of it, may be the Engine of Corruption, the Tool of a Junto. Heaven forbid! that our Country-"],["p","men should ever be biassed in their Choice by unreasonable Predilections for any Men, or that an Attachment to the Constituion should be lost \"in Devotion to Persons.\" The Effect of this wd soon be to change the Love of Liberty into the Spirit of Faction. Let each Citizen remember, at the Moment he is offering his Vote, that he is not making a Present or a Compliment to please an Individual, or at least that he ought not so to do, but that he is executing one of the most solemn Trusts in human Society, for which he is accountable to God & his Country\" — \"When the great Body of the People are determind not to be imposd upon by a false Glare of Virtues held before their Eyes; but, making up their own Minds shall impartially give in their Suffrages, after their best Inquiry into the Characters of Candidates, for those whom they judge to be the fittest Persons, there will be no Danger that the generous Enthusiasm of Liberty so characteristick of the People of Massachusetts will ever sink into the Violence & Rage of Party, which has often provd fatal to free Republicks.\"2"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v17.0134":{"title":"Daniel Carroll to Thomas Sim Lee","author_label":"Daniel Carroll","kind":"letter","date":"1781-04-10","date_label":"April 10, 1781","date_type":"written","recipient":"Thomas Sim Lee","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 17","source_url":"https://archive.org/details/lettersofdelegat17smit","scan_url":"https://archive.org/details/lettersofdelegat17smit/page/139","text_status":"unreviewed_ocr","editorial_source_note":"RC (MdHi: Lee, Horsey, and Carroll Papers deposit, 1985).","authors":["daniel-carroll"],"paras":[["h","Daniel Carroll to Thomas Sim Lee"],["p","Dear Sr. Philadelphia Apl 10th. 1781"],["p","I receivd yours of the 6th with the money enclosd — & Shall loose"],["p","no time in forwarding the wine. Col. Harrison has been in Town"],["p","some days past sick — 8c proposes sending a light waggon down with his Baggage, if there is some I shall send a quarter cask of wine by that opportunity. What you mention of Capt Murray Shall be attended to. Nothing more of the embarkation at New York officially since the letters the President sent you.1 The reinforcement arrived in Chessapeake were in 18 Transports, supposed to be under the Command of Genl. Philips."],["p","I am Dear Sr. with great regard & esteem, Yr hu Obt Sert,"],["p","Danl Carroll"],["p","[P.S.] Please to let Mr. Richard Lloyd & Mr. Carroll have the perusal of the New York papers I send — they are for Parson Gates from Mr Meade."],["p","I sent to Mr Carroll by the Express a paper contg Genl Greens last Letter & cannot [find] one to send you by this opportunity."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v17.0300":{"title":"Daniel of St. Thomas Jenifer to John Hall","author_label":"Daniel of St. Thomas Jenifer","kind":"letter","date":"1781-06-05","date_label":"June 5, 1781","date_type":"written","recipient":"John Hall","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 17","source_url":"https://archive.org/details/lettersofdelegat17smit","scan_url":"https://archive.org/details/lettersofdelegat17smit/page/298","text_status":"unreviewed_ocr","editorial_source_note":"RC (PHi: Gratz Collection).","authors":["daniel-of-st-thomas-jenifer"],"paras":[["h","Daniel of St. Thomas Jenifer to John Hall"],["p","My dear Sir, Phila. May [i.e. June] 5th. 1781."],["p","I thank you for your favor of the first Inst. Censor had much better in my opinion employed his Penn in attempting to heal breaches than to have widen'd them, as to one of the Rulers I do not care how soon he is changed. '"],["p","The Governor has informed Mr. Carroll that our Supply of Money shall be speedy,2 & therefore it would be doubting his & the Councils attention at this time to apply immediately to the Genl. Assembly, but our wants are so great that Mr. Carroll who whas been for some days & still continues unwell could not apply to the Doctor because he had not Money to pay him for his Visit 8c Medic[ine]s. The first Resolution of the Committee of the whole will do very well, the second perhaps is too broad. See what the other States do in this business before you carry your Resolution into a Law. Congress have laid the foundation of a general Bank which will preclude the idea of erecting others. Congress have heard nothing from General Green lately nor of the success you mention."],["p","I expect that General Wayne will be able to join the Marquis tomorrow, and that he will have it in his power to check the progressive Motions of the Enemy."],["p","Mr. Carroll and I wrote to the Genl assembly to add two members to the Delegation.3 We expected the choice would have been immediately made & that we should have seen by this time Mr. Johnson, Mr. Stone, Mr Carroll4 or yourself. Subjects of the last importance to the United States are before Congress, and unless we have the assistance of one or two of you in the course of this week it"],["p","will be too late even for a finger to be put into the Pye, indeed my friend it will turn out as we ever expected, that if there is a peace we shall have very little to say to the Terms of it therefore I wish our State would Stop the Sales of British & Refugee property for at least a Month or two 'till the scene opens a little wider, We can do as some other States do, rub on without it; and however Congress may have spurned at the idea, when Mr. Adams desired instructions on this head, they will I believe now reverse their tone.5 The King of Great Britain told you by his Commissioners That he would sooner part with his Crown than give up those who had sought his protection, and his obstinacy is unparralelled. Mr. Carroll and I thought of recommending this Subject to the consideration of the General Assembly immediately after the Ministers laid his Memorial before Congress; but upon reflection finding that we were not at liberty to give our reasons for the adopting the measure we agreed to Postpone our interference till we were, concluding that not much would in this respect be done in the mean time. My friend, the French are powerful in the West Indias, perhaps they will Conquer Clinton there, but whilst the Grass grows the Steed Starves."],["p","I shall enquire for the Map & Pamphlet you mention. I am with my compliments to Mrs. Hall."],["p","Dr Sir Your affectionate friend,"],["p","Daniel of St Thos Jenifer"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v18.0132":{"title":"William Churchill Houston to Thomas McKean","author_label":"William Churchill Houston","kind":"letter","date":"1781-10-13","date_label":"October 13, 1781","date_type":"written","recipient":"Thomas McKean","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 18","source_url":"https://archive.org/details/lettersofdelegat18smit","scan_url":"https://archive.org/details/lettersofdelegat18smit/page/129","text_status":"unreviewed_ocr","editorial_source_note":"RC (DNA: PCC, item 78).","authors":["william-churchill-houston"],"paras":[["h","William Churchill Houston to Thomas McKean"],["p","Sir, Philada. 13 Octr. 1781."],["p","I proposed to have attended in my Place this Morning1 and saved Your Excellency the Trouble of this Letter, but am called away sooner than I expected by Company with whom I am under an Engagement to return to New Jersey. Am therefore to request Your Excellency will be pleased again to express my Acknowledgments to Congress for the Honour they had intended me in the Election to the Office of Comptroller of Accounts, and to beg they will excuse me from undertaking it."],["p","I regret my having detained them so long from another Election, and hope they will attribute it to an earnest Desire to have obeyed their Commands, if, from the most careful Enquiry and Reflection, I could have thought myself capable of answering their Expectation."],["p","I have the Honour to be, Your Excellency's very obedt Servant,"],["p","W. C. Houston"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v18.0340":{"title":"Daniel Carroll to Thomas Sim Lee","author_label":"Daniel Carroll","kind":"letter","date":"1782-02","date_label":"February 1782","date_type":"written","recipient":"Thomas Sim Lee","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 18","source_url":"https://archive.org/details/lettersofdelegat18smit","scan_url":"https://archive.org/details/lettersofdelegat18smit/page/329","text_status":"unreviewed_ocr","editorial_source_note":"RC (MdHi: Lee, Horsey, and Carroll Papers deposit, 1985).","authors":["daniel-carroll"],"paras":[["h","Daniel Carroll to Thomas Sim Lee"],["p","Dear Sr. Pha. 10 February 82."],["p","Mr. Mullahan will deliver 3 prs. of Shoes for Mrs. Digges, and two pair of Slippers for Mrs Rogers. I take the liberty of requesting your care of them. He has given me a memorandum of some shoes for your Lady, which shall be forwarded by the first opportunity when they are done."],["p","I wrote to you abt 3 weeks past by Mr Richardson respecting my Situation abt money matters.1 You will now receive a public Letter on that Subject.2 I expect Mr Wright here in a few days3 & wish most earnestly to have it in my power to return to Maryland — & am confident you will have me assisted all you can — excuse me for troubling you on this subject. Present me to yr Lady."],["p","Yrs. Dr. Sr., with great esteem, Danl Carroll"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v18.0640":{"title":"Thomas McKean to Nicholas Van Dyke","author_label":"Thomas McKean","kind":"letter","date":"1782-07-29","date_label":"July 29, 1782","date_type":"written","recipient":"Nicholas Van Dyke","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 18","source_url":"https://archive.org/details/lettersofdelegat18smit","scan_url":"https://archive.org/details/lettersofdelegat18smit/page/675","text_status":"unreviewed_ocr","editorial_source_note":"RC (DLC: Nicholas Van Dyke Papers). Addressed: \"Nicholas Van Dyke Esquire at","authors":["thomas-mckean"],"paras":[["h","Thomas McKean to Nicholas Van Dyke"],["p","Dear Sir, Philadelphia. July 29th. 1782."],["p","Your favor of the 22d instant, with Henry Reynolds papers inclosed, came safe to hand, but I want the declarations, or at least the substance of them. Be so good as to send me copies by the first opportunity."],["p","To morrow morning I purpose to set out for Newtown in Bucks county, to hold a court of Oyer & Terminer there, but expect to return the latter end of the week. We are very busy in Congress, but have no news of any consequence. Rhode-Island has not yet granted the duty of five per centum; no taxes are coming in; the army must be paid or we shall be in a miserable situation. I hope all those, who can pay their taxes, will do it speedily."],["p","I am, dear Sir, in haste, Your most obedient humble servt."],["p","Tho M:Kean"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v19.0318":{"title":"Abraham Clark to William Livingston","author_label":"Abraham Clark","kind":"letter","date":"1782-12-04","date_label":"December 4, 1782","date_type":"written","recipient":"William Livingston","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 19","source_url":"https://archive.org/details/lettersofdelegat19smit","text_status":"unreviewed_ocr","editorial_source_note":"RC (NN: Livingston Papers). 1 Not identified.","authors":["abraham-clark"],"paras":[["h","Abraham Clark to William Livingston"],["p","Sir Philada. Deer. 4. 1782."],["p","Capt. Dehart l hath been attempting to procure his exchange at this"],["p","place, but as exchanges in the Continental Line are by seniority only,"],["p","he can have no prospect in his application here. It hath long been the Custom, in the Eastern states especially, to exchange for their Citizens such as are not Strictly Speaking Continental Prisoners, by which I mean those not taken at a Continental expence, they even exchange those taken by Privateers under Continental Commissions, this hath long been their practice. I cannot say what their conduct is at present but suppose the same they have heretofore practised: in this View of the matter I should not hesitate were I in your Excellencys place to send into New York for Capt. Dehart one of the Prisoners in Jersey as he is one of our Citizens, and perhaps the only one a Marine Prisoner, and the Prisoners with you taken neither at Continental expence or by a Continental Commission, as I am informed. Most of the prisoners coming out on Parole are to stay it is said untill called for, any sent in for such would not exchange them, but be Creditted in the general Account for past Arrears. Mr. Deharts parole entitles him to a discharge upon one's being sent in for him and should he return to New York and wait till all Arrears are paid up, and those taken before him exchanged, it is pretty certain he must remain a prisoner till the end of the War: his only prospect of exchange rests with your Excellency, who I am persuaded will grant him every favour his case may entitle him to, any other than such I would not Ask or even wish for."],["p","I have the honour to be, with great respect, Sir, your Obedt. Humble Servt. Abra. Clark"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v19.0333":{"title":"William Floyd to George Clinton","author_label":"William Floyd","kind":"letter","date":"1782-12-07","date_label":"December 7, 1782","date_type":"written","recipient":"George Clinton","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 19","source_url":"https://archive.org/details/lettersofdelegat19smit","scan_url":"https://archive.org/details/lettersofdelegat19smit/page/466","text_status":"unreviewed_ocr","editorial_source_note":"RC (PPRF: Americana Collection).","authors":["william-floyd"],"paras":[["h","William Floyd to George Clinton"],["p","Sir Philadelphia December 7th. 1782"],["p","As we have in our Official Letter1 Informed your Excellency of all Matters that are of a publick nature And that Relate to our State, I Shall only Remind you of my Situation With Respect to the means of Support; I did not Leave home with any Expectation of Coming to this place, unless the State in the first Instance did furnish me with money. But by your Excellencys Advise, Expecting that I Should very Soon be Supplied I was Induced to Come on, I am now here at my own Expence which I am not able to Sustain but a very Short time Longer, under these Circumstance your Excellency will Easily Discover my Embarassment, and I hope Devise Some way for my Relief that I may not be Involved in Difficulties that are Disgraceful to myself and to the State."],["p","From Sir your most Obedt. and humble Sevt, Wm. Floyd"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v19.0409":{"title":"James Madison's Notes of Debates","author_label":"James Madison","kind":"notes","date":"1783-01-06","date_label":"January 6, 1783","date_type":"written","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 19","source_url":"https://archive.org/details/lettersofdelegat19smit","text_status":"unreviewed_ocr","editorial_source_note":"MS (DLC: Madison Papers). Madison, Papers (Hutchinson), 6:15-16.","authors":["james-madison"],"paras":[["h","James Madison's Notes of Debates"],["p","Monday Jany. 6th. [1783] ' The Memorial from the army was laid before Congress and referred to a grand Committee.2 This reference was intended as a mark of the important light in which the memorial was viewed."],["p","Mr. Berkley3 having represented some inconveniencies incident to the plan of a Consular Convention between France & U. S., particularly the restriction of Consuls from trading, & his letter having been committed, a report was made proposing that the Convention should for the present be suspended. To this it had been objected that as the convention might already be concluded such a step was improper;"],["p","and as the end might be obtained by authorising the Minister at Versailles to propose particular alterations that it was unnecessary. By Mr. M[adison] it had been moved that the report should be postponed to make place for the consideration of an instruction & authority to the sd. Minister for that purpose; and this motion had in consequence been brought before Congress.4 On this day the business was revived. The sentiments of the members were various, some wishing to suspend such part of the convention only as excluded Consuls from commerce; others thought this exclusion too important to be even suspended; others again thought the whole ought to be suspended during the War; & others lastly contending that the whole ought to be new modelled; the Consuls having too many privileges in some respects, 8c too little power in others. It was observable that this diversity of opinions prevailed chiefly among the members who had come in since the Convention had been passed in Congress; the members originally present adhering to the views which then governed them.5 The subject was finally postponed; 8 States only being represented 8c 9 being requisite for such a question. Even to have suspended the convention after it had been proposed to the Court of France 8c possibly acceded to would have been indecent and dishonorable; and at a juncture when G. B. was courting a commercial intimacy, to the probable uneasiness of France, of very mischevous tendency. But experience constantly teaches that new members of a public body do not feel the necessary respect or responsibility for the acts of their predecessors, and that a change of members & of circumstances often proves fatal to consistency and stability of public measures. Some conversation in private by the old members with the most judicious of the new in this instance has abated the fondness of the latter for innovations, and it is even problematical whether they will be again urged."],["p","In the evening of this day the grand Committee met and agreed to meet again the succeeding evening for the purpose of a conference with the Superintendt. of Finance."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v20.0035":{"title":"James Madison to Edmund Randolph","author_label":"James Madison","kind":"letter","date":"1783-03-18","date_label":"March 18, 1783","date_type":"written","recipient":"Edmund Randolph","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 20","source_url":"https://archive.org/details/lettersofdelegat20smit","scan_url":"https://archive.org/details/lettersofdelegat20smit/page/48","text_status":"unreviewed_ocr","editorial_source_note":"RC (DLC: Madison Papers). In Madison's hand, though not signed. Madison, Papen (Hutchinson), 6:355-56.","authors":["james-madison"],"paras":[["h","James Madison to Edmund Randolph"],["p","My Dear Sir Philada. March 18. 1783"],["p","I reed, yesterday your favor of the 7 inst. together with that of the 22 Ulto. which ought to have been brought by the preceding mail.1 I regret much the uncertainty which attends your going into the Legislature. Is it possible that the difference between the amt. of your salary from the State and of the profits from which your office excludes you can form an essential article in your pecuniary plans? I am far from being singular in supposing that the business on the opposite side would be a much more productive fund."],["p","My letter by Express communicated to you the outlines of the intelligence brought by Capt. Barney from our Ministers in Europe.2 The tediousness of the Cypher does not permit me now to enter into detail. I can only add that notwithstanding the flattering aspect of the preliminary articles there are various circumstances which check our confidence in them, as there are some which will {detract from our joy) 3 if they should be (finally established}. To explain this it must suffice to observe that The latest letters from our Ministers express the greatest (jealousy of G B) and secondly that the situation of (France between} the (interfering claims of Spain} & (U S} to which may perhaps be added some particular (views of her own} having carried (her into a discountenance of} claims, the (suspicions of our ministers} on (that side} gave an opportunity to (British address to decoy them into a} degree (of confidence} which seems to leave their (own reputations} as well as the (safety of their country at the mercy of Shelburne}. In this (business Jay has taken the lead} & proceeded to (a length of which you} can (form little idea. Adams has followed with} cordiality. (Franklin has been dragged into it. Laurens} in his (separate letter} professes a (violent suspicion of G. B.} and (good will & confidence toward France}.4 The (dilemma to which Congress are} reduced is (infinitely perplexing}. If (they abet the proceedings of their ministers all} confidence (with France is at an end} which in the event of (a renewal of the war must be dread}full as in (that of peace it may} be (dishonourable. If they avow the conduct of their ministers} by (their) usual (frankness of communication} the most serious {inconveniences} also (present} themselves. The torment of this {dilemma can not be justly conveyed} withjout a} fulljer recital of facts than is permitted}. I wish you not to hazard even an interlined decypherment of those which I have deposited in your confidence."],["p","Despatches were yesterday reed, from Genl Washington which have (received) & (increased our apprehenseons on that side}.5 There seems to be reason to {suspect that) the (intriegues of) the {civil creditors fan) the (discontents of) the (army. The conduct of Washington} does equal honor to {his prudence and to his virtue}."],["p","The state {of our foreign affairs and of the army} combined with the difficulty and uncertainty of providing for justice & for our finances & with the (approaching exit of Morris give a peculiar solemnity to) the {present moment}. God send us a Speedy & {honourable deliverance from every danger). Pray hasten the new Cypher which you have promised."],["p","I have not yet perused your notes but thank you for them. Mr. J n6"],["p","is still left in dubio as to his destination. Before the next post the final decision of Congs. will probably take place. The paper inclosed to Mr. Ambler will give you the first part of the parliamentary debates, as the one herewith inclosed will the preliminary articles. The eagerness"],["p","50 March is, 1783"],["p","of the opposition for them portends violent altercations. The liberality of the articles to the U.S. will probably be the ground of Attack from the old Ministry; the omission of Commerce that of Fox's division. Farewell."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v20.0204":{"title":"James Madison's Notes of Debates","author_label":"James Madison","kind":"notes","date":"1783-05-08","date_label":"May 8, 1783","date_type":"written","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 20","source_url":"https://archive.org/details/lettersofdelegat20smit","scan_url":"https://archive.org/details/lettersofdelegat20smit/page/239","text_status":"unreviewed_ocr","editorial_source_note":"MS (DI.C: Madison Papers). Madison, Papers (Hutchinson), 7:28.","authors":["james-madison"],"paras":[["h","James Madison's Notes of Debates"],["p","Thursday May 8. [1783] Mr. Bland suggested that the Prisoners of War should be detained, until an answer be given as to the delivery of slaves, represented in a letter from Mr. Thomas Walke, to be refused on the part of Sr. Guy Carlton.1"],["p","On his motion seconded by Mr. Williamson it was ordered that the"],["p","letter be sent to Gen. Washington for his information, in carrying into"],["p","effect the Resolution of Apl. 15, touching arrangements with the"],["p","British Commander for delivery of the posts, negroes &c-"],["p","A Portrait of Don Galvez was presented to Congress by Oliver Pollock.3"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v20.0290":{"title":"Alexander Hamilton to George Clinton","author_label":"Alexander Hamilton","kind":"letter","date":"1783-06-11","date_label":"June 11, 1783","date_type":"written","recipient":"George Clinton","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 20","source_url":"https://archive.org/details/lettersofdelegat20smit","text_status":"unreviewed_ocr","editorial_source_note":"RC (DLC: George and James Clinton Papers, photostat).","authors":["alexander-hamilton"],"paras":[["h","Alexander Hamilton to George Clinton"],["p","Sir Philadelphia, June 11th. 1783"],["p","In two or three letters, which I have had the honor of writing to Your Excellency lately — I mentioned the necessity of a representation of the state here and at the same time of my returning to my private occupations. I am obliged to inform Your Excellency that I cannot remain here above ten days longer.1"],["p","I have the honor to be, Yr. Excellency's Most Obed ser,"],["p","Alex Hamilton"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v20.0486":{"title":"John Francis Mercer to James Madison","author_label":"John Francis Mercer","kind":"letter","date":"1783-08-14","date_label":"August 14, 1783","date_type":"written","recipient":"James Madison","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 20","source_url":"https://archive.org/details/lettersofdelegat20smit","scan_url":"https://archive.org/details/lettersofdelegat20smit/page/553","text_status":"unreviewed_ocr","editorial_source_note":"RC (DLC: Madison Papers). Endorsed by Madison: \"Angst. 14. 1783. Jno. F. Mercer.\" Madison, Papers (Hutchinson), 7:277-78.","authors":["john-francis-mercer"],"paras":[["h","John Francis Mercer to James Madison"],["p","Dear Sir [August 14, 1783]"],["p","Before I left Phila. I made enquiry for a Bill on me for 200 Dollars & wch had been presented 8c accepted, but by whom had entirely escaped my recollection — according to the perverse order of human affairs a Letter waiting here informs me of what I wished to know there — it is in the hands of a Mr. J. Ross, whom I have directed to apply to you 8c request the favor of you to discharge it."],["p","The Question for the return to Phila. had been decided in the negative prior to my arrival. I must think a worthy colleague,1 hurried this matter on with an unbecoming precipitation — & I am at a loss to reconcile with his professed, candor & openness, his making a motion with an intention of voting agt. it, supported by Mr. Howell the inventer of this ingenious, 8c honourable device.2 This said worthy Gentleman Mr. Howell, made a motion seconded by our other colleague Mr. Lee, to strike out Government after cofoederal & insert Union, in an Act of Congres3 — this will give you the complexion of our affairs."],["p","Mr. Laurens writes us from London dated the 17th of June, & suggests that there is no prospect that the mission of Mr. Hartley wd. terminate either in a commercial or definitive Treaty.4"],["p","It will be well for you to advise Mrs. House what steps she shoud take — had I any Idea that the sentiment of Congress coud. be so absurdly fixed I woud not hesitate to give my opinion that she shoud remove to where they may plan their residence.5 I am no doubt disposed by my desire of living with her myself. Does my friend Mrs. Trist pursue the plan of her Indies expedition. I wish she wd. write me when she hears from Havanna.6"],["p","My best Respects to Genl. Howe & the Gentn. of his family. The Gnl. will receive official notice of the present aims of Congress which supersedes the propriety of my writing.7 Come & bring Mr. Jones — your presence wd. be of essential utility.8"],["p","I am with respect [8c] esteem Dr Sir, Yr. mo. Ob. Sv"],["p","John F. Mercer 14th"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v21.0118":{"title":"Elbridge Gerry to Abigail Adams","author_label":"Elbridge Gerry","kind":"letter","date":"1783-11-06","date_label":"November 6, 1783","date_type":"written","recipient":"Abigail Adams","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 21","source_url":"https://archive.org/details/lettersofdelegat21smit","scan_url":"https://archive.org/details/lettersofdelegat21smit/page/148","text_status":"unreviewed_ocr","editorial_source_note":"RC (MHi: Adams Papers).","authors":["elbridge-gerry"],"paras":[["h","Elbridge Gerry to Abigail Adams"],["p","My dear Madam Princeton 6th Novr 1783"],["p","Since I had the Pleasure of addressing You,1 nothing of Importance has occurred in the Concerns of our Friend excepting a Letter from Mr Jay, wherein he with great Candour & good Sense has endeavoured to do Justice to Mr Adams' Character, 8c recommended him as the most suitable person to represent the united States at the Court of London; declaring at the same Time in the most positive terms, that should the place be offered to himself, he would not accept it. I should be exceedingly happy on my own Account, but more particularly on yours, Madam, to see Mr Adams in America, because I am persuaded he would not only be in the Way of rendering at this Time essential Services to his Country, but also (by recovering his Health), to himself & Family. The perplexities of American politics, are neither pleasing nor salutary; much less so must there be, which are in the Center 8c subject to all the Subtleties 8c Intrigues of European Systems; but the probability is I think against his immediate return."],["p","The postmasters have either misconstrued or perverted the Design of the post office Ordnance, which provides that Letters to 8c from certain persons in publick office, on publick business shall be exempt from postage.2 The Endorsement of such persons Names on their Letters is therefore sufficient to acquit the Receiver thereof from postage; but the postmasters have, as I am informed, in many Cases where the Members of Congress 8c the Commander in chief have not endorsed with the Words \"on publick Business,\" had the assurance to take postage; not so much I apprehend to benefit the publick, as to save the 20 per Cent allowed to the postoffice,3 but Measures are taken since the Receipt of your Letter to correct this Error, & I presume the Frank of our foreign Ministers will be admitted in Future by order of Congress. Doctor Lee & Mr Osgood join in their best respects to yourself 8c Family, with Madam your sincere Friend 8c most obt hum servt"],["p","E Gerry"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v21.0131":{"title":"Thomas Mifflin to Certain States","author_label":"Thomas Mifflin","kind":"letter","date":"1783-11-23","date_label":"November 23, 1783","date_type":"written","recipient":"Certain States","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 21","source_url":"https://archive.org/details/lettersofdelegat21smit","scan_url":"https://archive.org/details/lettersofdelegat21smit/page/162","text_status":"unreviewed_ocr","editorial_source_note":"LB (DNA: PCC, item 16). Addressed: \"His Excellency The Governor of New-Hamp- shire. NB. A similar letter was written to their Excellencies the Governors of Connecti- cut, New- York, New-Jersey and Delaware.\"","authors":["thomas-mifflin"],"paras":[["h","Thomas Mifflin to Certain States"],["p","Sir, Philadelphia November 23rd. 1783."],["p","I have the honor to inform you that Mr. Thaxter, the private Secretary to Mr. Adams, arrived here from France last evening; being dispatched by our Ministers at Paris with a Copy of the definitive treaty of peace between the United States of America and Great Britain; which was signed on the 3rd of September last."],["p","As I find by the last article of the Treaty, it is stipulated that \"the ratifications thereof, expedited in good and due form, shall be exchanged between the contracting parties in the space of Six months, or sooner if possible; \" to be computed from the day of the signature; and as much of that time is elapsed, I think it proper to give your Excellency this information, to the end that the delegates of your State may be impressed with the necessity of their attending in Congress as soon as possible.1"],["p","I am with the greatest respect and Esteem, Your Excellency's obt. humble Servt. Tho. Mifflin"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v21.0166":{"title":"Thomas Mifflin to John Dickinson","author_label":"Thomas Mifflin","kind":"letter","date":"1783-12-24","date_label":"December 24, 1783","date_type":"written","recipient":"John Dickinson","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 21","source_url":"https://archive.org/details/lettersofdelegat21smit","scan_url":"https://archive.org/details/lettersofdelegat21smit/page/223","text_status":"unreviewed_ocr","editorial_source_note":"RC (PHC: Roberts Collection).","authors":["thomas-mifflin"],"paras":[["h","Thomas Mifflin to John Dickinson"],["p","Sir Annapolis Decern. 23rd. 1783."],["p","I have the honor to inform you, that this day at twelve o' Clock, His Excellency General Washington had a public audience of Congress, resigned his commission and took his leave of all the employments of public life. The General's address 8c the answer of Congress I enclose for the Satisfaction of your Excellency 8c the Honorable Council.1 The delegates of Pennsylvania will write to your Excellency by the next post 8c give you a detail of the business which has been acted upon in Congress since their arrival here."],["p","I have the honor to be, with the highest respect, Your Excellency's & Council's obedt. Servt. Thomas Mifflin"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v22.0232":{"title":"Hugh Williamson to Richard Caswell","author_label":"Hugh Williamson","kind":"letter","date":"1785-03-28","date_label":"March 28, 1785","date_type":"written","recipient":"Richard Caswell","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 22","source_url":"https://archive.org/details/lettersofdelegat22smit","scan_url":"https://archive.org/details/lettersofdelegat22smit/page/296","text_status":"unreviewed_ocr","editorial_source_note":"RC (NjMoHP: Lloyd W. Smith Collection).","authors":["hugh-williamson"],"paras":[["h","Hugh Williamson to Richard Caswell"],["p","Sir New York 28th March 1 785"],["p","The inclosed for the Govr. of N. Carolina is forwarded to you,1 the Delegates from the State thinking it probable that the Delays to which it will be subjected in reaching the Hand of Govr. Martin may prove fatal to the Design. The Delegates are not informed of the Time on which the administration comes into your Hands but they presume that you will think fit to open the inclosed when it comes to Hand, and that you will detain it till you can act upon it or forward it with Dispatch to Govr. Martin as the Exigence of the Case may seem to require. I have the Honor to be with the utmost Consideration, Sir, Your obedt hble Servt. Hu Williamson"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v22.0316":{"title":"Richard Henry Lee to Samuel Adams","author_label":"Richard Henry Lee","kind":"letter","date":"1785-05-20","date_label":"May 20, 1785","date_type":"written","recipient":"Samuel Adams","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 22","source_url":"https://archive.org/details/lettersofdelegat22smit","scan_url":"https://archive.org/details/lettersofdelegat22smit/page/397","text_status":"unreviewed_ocr","editorial_source_note":"RC (NN: Samuel Adams Papers).","authors":["richard-henry-lee"],"paras":[["h","Richard Henry Lee to Samuel Adams"],["p","My dear Sir, New York May 20. 1 785"],["p","I thank you for your favor introducing Mrs. Macauley Graham to me.1 This excellent Lady made but a short stay here, being desirous of returning from the South, before the sickly season comes on in that climate. I hope we shall shortly finish our plan for disposing of the western Lands to discharge the oppressive public debt created by the war & I think that if this source of revenue be rightly managed, that these republics may soon be discharged from that state of oppression and distress that an indebted people must invariably feel. The late arrival here of a Ship from Canton in China after a successful voyage of 14 Months from this port, is a proof of American enterprise, and will probably mortify, as much as it will injure our old Oppressors, the British.2"],["p","I beg my respects to Mrs. Adams, and I sincerely wish a long continuance of health and happiness to you, being most truly dear Sir Your affectionate friend, Richard Henry Lee3"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v22.0339":{"title":"Richard Henry Lee to James Madison","author_label":"Richard Henry Lee","kind":"letter","date":"1785-05-30","date_label":"May 30, 1785","date_type":"written","recipient":"James Madison","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 22","source_url":"https://archive.org/details/lettersofdelegat22smit","scan_url":"https://archive.org/details/lettersofdelegat22smit/page/417","text_status":"unreviewed_ocr","editorial_source_note":"RC (DLC: Madison Papers).","authors":["richard-henry-lee"],"paras":[["h","Richard Henry Lee to James Madison"],["p","Dear Sir New York May the 30th 1 785"],["p","Two days ago, and not sooner, your favor of March the 20th l was deliverd to me, so that you find it has been more than two months travelling thus far. It seems to me that our Assembly were influenced more by the letter than the spirit of the Confederation. The consequence will certainly be, if our meetings are slow as usual, that Virginia will be unrepresented for some time after the federal year commences.2 Tho no great mischief arises from this, the appearance is not so handsome as it should be; besides that it partakes too much of that too common inattention to the great Council of the U. S. upon the wise conduct of which so much depends."],["p","I am very happy to see by the Newspapers that the business of opening Potomac goes on so well. Tis certainly an object of great consequence to extend our internal navigation. Concerning James river I have heard nothing.3 When I was in our Assembly it appeard to me rather to be the wish, than otherwise, that Kentucky should apply for separation — And I should suppose that if, when they found themselves compitent to the business of Self Government, they properly applied to our Assembly, no good objection could be made to a separation— For they have, 8c will remain for a long time, if not always, more expence than profit to the rest of the country.4 Washington County seems to be stimulated by a troublesome person who for self aggrandisement appears willg. to dismember that part also, 8c join with the Revolters from N. Carolina. This last seems to merit the wise 8c firm attention of Government & the Legislature.5 We have, after much debate indeed, & great waste of time, at last pass'd an Ordinance for disposing of such part of the Lands N. W of the Ohio as belongs to the U. S. 8c have been purchased of the Indians. If this proves agreeable to the public, it will extinguish about 10 Millions of the pub debt. And the remaining lands, going southward to the Mississippi, will nearly discharge all the domestic debt — Besides the probable prospect that"],["p","we have of considerable cessions from N & S. Carolina & Georgia. This Source does indeed deserve our warmest cultivation as it seems to be almost the only one that we have for discharging our oppressive debt. Dr. Franklin has leave to retire, Mr. Jefferson remains in France — And Mr. J. Adams is sent to London. If the Court of this last country is sincere, we may expect an amicable & easy settlement of existing differences between us. The Minister (Mr. Pitt) does appear willing to be liberal in Commercial regulations, but the avaricious spirit of Commerce that is so great every where, but which in England has ever been excessive, opposes his views — And so we find it is in France, for the Marquis de La Fayette writes that the advantages already granted us are most violently exclaimed against by the Trading people of the Kingdom.6 Mr Gardoque (who calls himself Plenepotentiary Charged with Affairs is arrived at Phila. and we expect him soon here7 — So that we shall quickly know whether he can or will do any thing conclusive concerning the Navigation of Mississippi. He reports a great scarcity of provisions at the Havannah, but yet we dont hear of the ports of that Island being opened to us for supply. It is reported that the frigate which brought him is taking in flower. The American enterprise has been well markt by a short and successful Voyage made from hence to Canton in China. The Chinese were kind to our people and glad to see a new Source of Commerce opened to them from a New People, as they called us. The Europeans there were civil but astonished at the rapidity of our movements, especially the English. I fear that our Countrymen will overdo this business — For now there appears every where a Rage for East India Voyages. So that the variety of means may defeat the Attainment of the concurrent end — A regulated & useful commerce with that part of the World. It seems very questionable now whether Congress will adjourn or not this Year — if they do, it will not be until late in August. Inattention, Sickness, and a variety of causes occasion business to go on very slowly. 1 8"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v22.0531":{"title":"Rufus King to Timothy Pickering","author_label":"Rufus King","kind":"letter","date":"1785-08-31","date_label":"August 31, 1785","date_type":"written","recipient":"Timothy Pickering","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 22","source_url":"https://archive.org/details/lettersofdelegat22smit","scan_url":"https://archive.org/details/lettersofdelegat22smit/page/607","text_status":"unreviewed_ocr","editorial_source_note":"RC (MHi: Pickering Papers).","authors":["rufus-king"],"paras":[["h","Rufus King to Timothy Pickering"],["p","Dr Sir New York 31st Aug. 1785"],["p","I thank you for your's of yesterday; since you left this City I found an opportunity to draw a small Bill which will answer my present demands, and which leaves me at liberty with expressions of acknowledgement to decline your obliging offer."],["p","Mr. Hillegas it is said will come on to this City with his Department. We have a publication from your quarter, entitled considerations on the Bank of &C.1 Does not the author prove more than he would wish; upon the principles attempted to be established in this Pamphlet, have not congress authority to order the removal of the Bank to this City or elsewhere? 2"],["p","With great respect & esteem, your obedt. servt. Rufus King"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v22.0575":{"title":"Elbridge Gerry to Samuel Adams","author_label":"Elbridge Gerry","kind":"letter","date":"1785-09-30","date_label":"September 30, 1785","date_type":"written","recipient":"Samuel Adams","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 22","source_url":"https://archive.org/details/lettersofdelegat22smit","scan_url":"https://archive.org/details/lettersofdelegat22smit/page/651","text_status":"unreviewed_ocr","editorial_source_note":"RC (NN: Adams Papers).","authors":["elbridge-gerry"],"paras":[["h","Elbridge Gerry to Samuel Adams"],["p","My dear Sir, New York 30th Sepr 1 785"],["p","I am much obliged to you for your Hint relative to what may take place with Respect to the Cincinnati, in our Delegation of the next Year.1 We shall before the adjournment endeavour to fix on the Journals something that may operate to cripple, if not mortally to wound that unconstitutional Monster."],["p","I am happy to find that We unite in Sentiment in the Necessity of vesting Congress with more commercial powers: 8c flatter myself We shall not differ in making them in the first Instance temporary, & in opposing a general Revision of the Confederation.2 It is difficult to determine on a good Expedient, to remedy our present Evils, but We shall attempt it, if Time will permit."],["p","Doctor Franklin has, as You will perceive by the Pennsylvania papers, been puffed at a great Rate, & will probably be in the Chair of that State. His Grandson came to this City last Evening, but his object I cannot yet ascertain. I confess to You, I have a jealous Eye on the Doctor: he is devoted to the Court of Versailles, & should he come to Congress as a Delegate & obtain the Chair, he may do more Mischief"],["p","than We are apt to imagine. But his great Age seems almost an insupperable Bar to the Execution of an extensive plan."],["p","Mr Simkins I have not seen, he called on me so early that he found me in Bed & has not renewed his Visit when I was at Home."],["p","I have the pleasure of inclosing a Copy of the Requisition, which is not so good as may be wished, but the best that could be obtained."],["p","Adieu my dear Sir & be assured I am yours sincerely,"],["p","E Gerry"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v22.0630":{"title":"Richard Henry Lee to John Adams","author_label":"Richard Henry Lee","kind":"letter","date":"1785-10-24","date_label":"October 24, 1785","date_type":"written","recipient":"John Adams","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 22","source_url":"https://archive.org/details/lettersofdelegat22smit","scan_url":"https://archive.org/details/lettersofdelegat22smit/page/700","text_status":"unreviewed_ocr","editorial_source_note":"RC (MHi: Adams Family Papers).","authors":["richard-henry-lee"],"paras":[["h","Richard Henry Lee to John Adams"],["p","Dear Sir New York October the 24th 1 785"],["p","Having yesterday written a long letter to you, I have now only to request your attention to the following business, which is of very great importance to those whom it concerns, and who form a considerable portion of the Citizens of these States. The representation of those professing the Church of England system of religion, having been lately assembled at Philadelphia where Lay & Clerical deputies from seven States were convened in General Convention for the purpose, among other things, of preserving and maintaining a succession of divines in their Church, in a manner which they judge consonant to the gospel, and no way interfering with the religious or civil rights of others— have sent an address to the Archbishops and Bishops of England, proposing a plan for the consecration of American Bishops.1 It is imagined, that before anything is done in this business by the Bishops of England, that they will consult the King and Ministry; who, it is apprehended may now, as heretofore, suppose that any step of the kind being taken in England might be considered here as an officious intermeddling with our affairs that would give offence on this side the water. Should this be the case, the Church of England Members in Congress have the greatest reliance on your liberal regard for the religious rights of all men, that you will remove mistaken scruples from the mind of administration, by representing how perfectly consonant it is with our revolution principles professed thro-out all the States, that every denomination of Christians has a right to pursue its own religious modes, interfering not with others. That instead of giving offence, it must give content, by evidencing a friendly disposition to accommodate the people here who are members of the Church in question. In proof of this, Congress did lately shew their attention to the accommodation of this Class of Christians, by communicating to the different Executives your information from the Danish Minister of"],["p","that Kings willingness to facilitate the business of ordination for our church2 — And the Assembly of Virginia hath incorporated this Society— Under which Act of incorporation the Convention was held in that State that sent both Lay & Clerical deputies to the General Convention lately held in Philadelphia."],["p","I have the honor to be, with sentiments of the truest esteem and regard, dear Sir Your most obedient and very humble servant."],["p","Richard Henry Lee"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v23.0196":{"title":"Rufus King to John Lowell, Theophilus Parsons, and James Sullivan","author_label":"Rufus King","kind":"letter","date":"1786-04-12","date_label":"April 12, 1786","date_type":"written","recipient":"John Lowell, Theophilus Parsons, and James Sullivan","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 23","source_url":"https://archive.org/details/lettersofdelegat23smit","scan_url":"https://archive.org/details/lettersofdelegat23smit/page/229","text_status":"unreviewed_ocr","editorial_source_note":"RC (MH-H: bMS Am 1582). Addressed: \"The Hon. Mr. Lowell. Mr. Sullivan & Mr. Parsons.\"","authors":["rufus-king"],"paras":[["h","Rufus King to John Lowell, Theophilus Parsons, and James Sullivan"],["p","Gentlemen, New York 12 Ap. 1786"],["p","By the last Packet I received from Mr. Adams an attested copy of the Letters patent of King James the 1st to the council of Plymouth, together with the papers, copies whereof are inclosed. The Copy of the letters patent is voluminous; and I have supposed it as well to keep it in my possession as to transmit it by Post."],["p","Nothing has taken place respecting our federal court since I wrote to you last: indeed there are no agents herewho can take any farther measure on this Subject, we apprized the Governor of this Event in October last, but have heard nothing concerning the business since.1"],["p","I though) it more proper to inclose these copies to you, than to the Governor; judging thai you had monies in your hands with which Mr. Adams may be reimbursed his advances."],["p","With perfect Respect, I have the Honor to be, Gentlemen, your obt. & very H'ble servt, Rufus King"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v24.0016":{"title":"Rufus King to Nathan Dane","author_label":"Rufus King","kind":"letter","date":"1786-11","date_label":"November 1786","date_type":"written","recipient":"Nathan Dane","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 24","source_url":"https://archive.org/details/lettersofdelegat24smit","scan_url":"https://archive.org/details/lettersofdelegat24smit/page/33","text_status":"unreviewed_ocr","editorial_source_note":"RC (MBevHi: Dane Papers).","authors":["rufus-king"],"paras":[["h","Rufus King to Nathan Dane"],["p","Dr. Sir New York 22 Nov. [ 1 7] 86"],["p","Mr. Gorham left us on Monday, I expect to leave this place for Hartford on Friday.1 No addition of Delegates since I wrote you last. I wrote a note to each of the Printers in this City 8c requested that they would not insert any thing in their papers relative to your communication with the Legislature,2 as the accounts were very erroneous. Nothing has been or will be published."],["p","I have nothing to add except that we have a copy of the Treaty of Amity 8c Commerce concluded between Morocco & the US.3 Its duration is Fifty years."],["p","Farewel, Rufus King"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v24.0268":{"title":"William Blount to Joseph Clay","author_label":"William Blount","kind":"letter","date":"1787-06","date_label":"June 1787","date_type":"written","recipient":"Joseph Clay","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 24","source_url":"https://archive.org/details/lettersofdelegat24smit","text_status":"unreviewed_ocr","editorial_source_note":"Ri. (PHi: Gratz Collection). Addressed: \"Joseph Cla) esquire, Savannah.\"","authors":["william-blount"],"paras":[["h","William Blount to Joseph Clay"],["p","Dear Sir, Newyorkjune 11th 1787"],["p","I have had the Pleasure to receive your's of the 28th April addressed to Doer. Nicholas Romayne.1 Hereto annexed is the Account of Sales of the Hogshead of Skins therein mentioned2 and of three others3 recieved some short Time before which I presume as you deal in that Article will not be unacceptable. At present there are not States enough represented to form a Congress and I believe will not be untill the Convention rises. The Members of the Convention observe such inviolable Secrecy that it is altogether unknown"],["p","324 June 11, 17875"],["p","out doors what they arc doing. I shall leave this in a few days to take my Seat among them."],["p","Please present my Compliments to Mrs. Clay and believe me with much esteem, Your most Obedient Humble servant,"],["p","Win. Blount"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v24.0312":{"title":"William Blount to Richard Caswell","author_label":"William Blount","kind":"letter","date":"1787-07-19","date_label":"July 19, 1787","date_type":"written","recipient":"Richard Caswell","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 24","source_url":"https://archive.org/details/lettersofdelegat24smit","scan_url":"https://archive.org/details/lettersofdelegat24smit/page/362","text_status":"unreviewed_ocr","editorial_source_note":"FC (Nc-Ar: Blount Papers). In the hand of William Blount.","authors":["william-blount"],"paras":[["h","William Blount to Richard Caswell"],["p","Dear Sir,1 Newyorkjuly 19th 1787."],["p","Herewith I forward to your Address the Papers of today in one of which is contained a Letter dated at Nashville May 1st addressed to the Honorable B. H.2 You will readily conjecture it was fabricated by a Person better informed that [than] any Inhabitants of Davidson County can be it only remains for me to tell you that it has been written on my Motion in the first Instance by my Friend H. W.3 It has been here much applauded as well written and it certainly is well timed. He is not suspected of being the Author. It has been translated into French & will be published in Paris & London."],["p","I arrived here on the 3d July from Philadelphia accompanyed by Mr. Hawkins, the Reasons that induced us to do [so] We have given you in official Lettrs by Post which I suppose will be to hand before this.4 We have at present nine States on the floor, 8c I have from day to day for Several days past been about to return to Philadelphia but sundry things which require the Assent of that Number of States has been so pressing and still continues so to be that I believe we shall continue here untill Sunday (we are so now industrious that We set on Saturday). I had yesterday a Letter from D<avie>5 in which he says \"since you left us We have progressed obliquely and retrograded directly so that we stand on the same Spot you left us\" and when I left them much Progress was not made. My Colleagues were very unanimous, H. W. are there Head, and were in Sentiment with Virginia who seemed to take the lead, Madison at their Head, tho Randolph and Mason are also great. The general outlines were to have a National Assembly composed of three Branches, the first to be elected by the People at large and to consist of about 70 Members, the second Branch of a less Number to be chosen by the respective Legislatures for a longer duration and the third an Executive of a single Man for a still longer Time. I must confess notwithstanding all I heard in favour of this System I am not in sentiment with my Colleagues for as I have before said I still think We shall ultimately and not many Years first be seperate and distinct Governments perfectly independent of each other. The little States were much opposed to the Politics of the larger they insisted that each State ought to have an equal Vote as in the present Confederation."],["p","Congress yesterday recived a Letter from Mr. Brandt written in the Indian Language informing that all the Nations of Indians of the North West of the Ohio had formed a Confederacy offensive 8c Defensive, it was couched in hostile Language and contained a request in the Terms of a Demand that our Surveyors should desist from"],["p","survey [ing] the Lands west of the Ohio.6 Daily Accounts from Kentuckey prove the Indians are hostile in that quarter and by the Report of the Superintendent from the Creeks there is much Reason to fear Hostilities will shortly commence between them and the Citizens of Georgia. There has been at Philadelphia a Mr. Drungold with a Cherokee &John Woods with a Chickasaw & Choctaw and have all returned, the two latter by way of Fort Pitt, the former complained loudly against the Infraction of the Treaty at Hopewell in as much as that the Whites had settled within a few Miles of their towns, and within that part assigned them by the State of N.Ca. I would wish the Whites had forborn there Settlements on that part — the other two complained that Trade had not been sent among them as they were taught to expect and that they were suffering for the Want of the promised Supplies, in Short We have three Reports from the Secretary at War, on Indian Afairs, one in particular which is the Subject of this day recommends the Stationing Continental Troops on the Ohio in different parts as low as the Rapids and the Calling out Militia on Continental pay to protect the Kentuckey and other Inhabitants on the east side of the Ohio.7"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v25.0295":{"title":"James Madison to Thomas Jefferson","author_label":"James Madison","kind":"letter","date":"1788-08-23","date_label":"August 23, 1788","date_type":"written","recipient":"Thomas Jefferson","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 25","source_url":"https://archive.org/details/lettersofdelegat25smit","scan_url":"https://archive.org/details/lettersofdelegat25smit/page/315","text_status":"unreviewed_ocr","editorial_source_note":"RC (DLC: Madison Papers). Madison, Papers (Rutland), 11:238-39.","authors":["james-madison"],"paras":[["h","James Madison to Thomas Jefferson"],["p","Dear Sir New York Augst. 23. 1 788."],["p","My last went via England in the hands of a Swiss gentleman who had married an American lady, and was returning with her to his own country. He proposed to take Paris in his way. By that opportunity I inclosed copies of the proceedings of this State on the subject of the"],["p","Constitution. North Carolina was then in Convention, and it was generally expected would in some form or other have fallen into the general stream. The event has disappointed us. It appears that a large majority has decided against the Constitution as it stands, and according to the information here received has made the alterations proposed by Virginia the conditions on which alone that State will unite with the others. Whether this be the precise state of the case I can not say. It seems at least certain that she has either rejected the Constitution, or annexed conditions precedent to her ratification. It cannot be doubted that this bold step is to be ascribed in part to the influence of the minority in Virginia which lies mosdy in the Southern part of the State, and to the management of its leader. It is in part ascribed also by some to assurances transmitted from leading individuals here, that New York would set the example of rejection. The event, whatever may have been its cause, with the tendency of the circular letter from the Convention of N. York, has somewhat changed the aspect of things and has given fresh hopes and exertions to those who opposed the Constitution. The object with them now will be to effect an early Convention composed of men who will essentially mutilate the system, particularly in the article of taxation, without which in my opinion the system cannot answer the purposes for which it was intended. An early Convention is in every view to be dreaded in the present temper of America. A very short period of delay would produce the double advantage of diminishing the heat and increasing the light of all parties. A trial for one year will probably suggest more real amendments than all the antecedent speculations of our most sagacious politicians."],["p","Congress have not yet decided on the arrangements for inaugurating the new Government. The place of its first meeting continues to divide the Northern & Southern members, though with a few exceptions to this general description of the parties. The departure of Rho. Island, and the refusal of N. Carolina in consequence of the late event there to vote in the question, threatens a disagreeable issue to the business, there being now an apparent impossibility of obtaining seven States for any one place. The three Eastern States & N. York, reinforced by S. Carolina, and as yet by N.Jersey, give a plurality of votes in favor of this City. The advocates for a more central position however though less numerous, seemed very determined not to yeild to what they call a shameful partiality to one extremity of the Continent. It will be certainly of far more importance under the proposed than the present system that regard should be had to centrality whether we consider the number of members belonging to the Government, the diffusive manner in which they will be appointed, or the increased re-"],["p","sort of individuals having business with the Legislative, Executive & Judiciary departments. If the Western Country be taken into view, as it certainly ought, the reasoning is still further corroborated. There is good ground to believe that a very {jealous eye will be}1 kept in that {quarter on injattention {to it and particularly when} involving a {seeming advantage to the eastern states} which have been {rendered extremely suspicious} and {obnoxious by the Missisipi project}. There is {even good ground to believe that Spain is taking} advantage of {this disgust in Kentucky} and is {actually endeavoring} to {seduce them from the union holding out a darling object which will never be obtained by them as part of the union}. This is a {fact as certain as it is important but which I hint in strict confidence} and with {a request} that no suspicion may be excited of its being {known particularly thro the channel of me}.2 I have this moment notice that I must send off my letter instantly, or lose the conveyance. I must consequently defer further communications till another opportunity."],["p","In the meantime I am, Yrs. Affely, Js. Madison Jr."],["p","[P.S.] Along with this you will receive a copy of the report you desired from Mr. Thomson,3 and a copy of the Federalist, a publication mentioned in my last."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v25.0303":{"title":"Alexander Hamilton to John Chaloner","author_label":"Alexander Hamilton","kind":"letter","date":"1788-08-28","date_label":"August 28, 1788","date_type":"written","recipient":"John Chaloner","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 25","source_url":"https://archive.org/details/lettersofdelegat25smit","scan_url":"https://archive.org/details/lettersofdelegat25smit/page/328","text_status":"unreviewed_ocr","editorial_source_note":"RC (PHi: Chaloner & White Papers). Addressed: \"Mr. John Chaloner, Merchant, Philadelphia.\"","authors":["alexander-hamilton"],"paras":[["h","Alexander Hamilton to John Chaloner"],["p","Sir1 New York Aug 28. 1 788.2"],["p","I have received your letter of the 20th of August with the paper inclosed.3"],["p","I have caused a search to be made in the secretary's office and am informed, that the deeds mentioned in the abstract are regularly recorded agreeably to the references; and the chain of title appears to be complete. As to the value of the land no estimate can well be formed but by a person acquainted with the spot. From the part of the country in which it lies I should conjecture it might be worth a dollar an acre; though sold in the gross it would not perhaps fetch half the money. As to incumbrances this would be a still more difficult inquiry. Recourse must be had to the records in Albany; and that done, there would still be a general source of apprehension from the known embarrassments of Croghan — there being judgments against him to a large amount, which it is perhaps not possible to ascertain whether satisfied or not or how far."],["p","I have sent the abstract to Albany to pursue the inquiry, which will be done; unless you send me word it is unnecessary. Upon the whole I fear the matter will be after all a leap in the dark — But the circumstances may be such as to render it prudent to take it."],["p","I remain with esteem, Yrs, A Hamilton"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v25.0360":{"title":"Alexander Hamilton to Nathaniel Chipman","author_label":"Alexander Hamilton","kind":"letter","date_type":"written","recipient":"Nathaniel Chipman","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 25","source_url":"https://archive.org/details/lettersofdelegat25smit","scan_url":"https://archive.org/details/lettersofdelegat25smit/page/397","text_status":"unreviewed_ocr","editorial_source_note":"RC (DLC: Hamilton-McLane Collection).","authors":["alexander-hamilton"],"paras":[["h","Alexander Hamilton to Nathaniel Chipman"],["p","Sir1 [September? 1788] 2"],["p","Your favour of the 6th of September has been duly handed to me,3 and I receive great pleasure from the hopes you appear to entertain of a favourable turn of affairs in Vermont in regard to the new Government. It is certainly an object of mutual importance to yourselves and to the Union and well deserves the best endeavours of every discerning and good man."],["p","I observe with satisfaction your opinion that Vermont will not make a point of introducing amendments (I mean as a condition of her accession). That ground would be the most hazardous which she could venture upon, as it is very probable that such amendments as might be popular with you would be deemed inadmissible by the friends of the system who will doubtless be the most influential persons in the national councils and who would rather submit to the inconvenience of your being out of the Union 'till circumstances should alter, than consent to any thing that might impair the energy of the Government. The article of taxation is above all the most delicate thing to meddle with; for as plenary power in that respect must ever be considered as the vital principle of government; no abrigment or constitutional suspension of that power can ever upon mature consideration be countenanced by the intelligent Friends of an effective national government. You must as I remarked in my former letter rely upon the natural course of things which I am satisfied will exempt you in ordinary times from direct taxation, on account of the difficulty of exercising it in so extensive a country, so peculiarly situated, with advantage to the revenue or satisfaction to the people. Though this difficulty will be gradually diminished from various causes, a considerable time must first elapse; and in the interim you will have nothing to apprehend on this score. As far as indirect taxation is concerned it will be impossible to exempt you from sharing in the burthen nor can it be desired by your citizens. I repeat these ideas to impress you the more strongly with my sense of the danger of touching this cord and of the impolicy of perplexing the main object with any such collateral experiments. While I am glad to perceive that you do not think your people will be tenacious on the point."],["p","It will be useless for you to have any view in your act to the present Congress. They can of course do nothing in the matter. All you will have to do will be to pass an act of accession to the new constitution on the conditions upon which you mean to rely. It will then be for the new Government when met to declare whether you can be received on your terms or not."],["p","398 September?, 1788"],["p","I am sorry to find that the affair of boundary is likely to create some embarrassment. Mens minds every where out of you[r] state are made up upon and reconciled to that which has been delineated by Congress. Any departure from it must beget new disscussions, in which all the passions will have their usual scope, and may occasion greater impediments than the real importance of the thing would justify. If however the further claims you state cannot be gotten over with you I would still wish to see the experiment made though with this clog; because I have it very much at heart that you should become a member of the Confederacy. It is however not to be inferred that the same disposition will actuate every body. In this state the pride of certain individuals has too long triumphed over the public interrest and in several of the Southern states a jealousy of Northern influence will prevent any great zeal for increasing in the national councils the number of Northern Voters. I mention these circumstances (though I dare say they will have occurred to you) to show you the necessity of moderation and caution on your part and the error of any sanguine calculation upon a disposition to receive you at any rate. A supposition of this nature might lead to fatal mistakes."],["p","In the event of an extension of your boundary beyond the Congressional line would it be impracticable for you to have commissioners appointed to adjust any differences which might arise? I presume the principal object with you in the extension of your boundary would be to cover some private interests. This might be matter of Negotiation."],["p","There is one thing which I think it proper to mention to you about which I have some doubt; that is whether a legislative accession would be deemed valid. It is the policy of the system to lay its foundations in the immediate consent of the people. You will best judge how far it is safe or practicable to have recourse to a Convention. Whatever you do no time ought to be lost. The present moment is undoubtedly critically favourable. Let it by all means be improved."],["p","I remain with esteem, Sir, Yr. Obed & hum s — A Hamilton"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v25.0390":{"title":"Hugh Williamson to Samuel Johnston","author_label":"Hugh Williamson","kind":"letter","date":"1788-10-17","date_label":"October 17, 1788","date_type":"written","recipient":"Samuel Johnston","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 25","source_url":"https://archive.org/details/lettersofdelegat25smit","scan_url":"https://archive.org/details/lettersofdelegat25smit/page/432","text_status":"unreviewed_ocr","editorial_source_note":"RC (MH-H: bMS Am 1649.5).","authors":["hugh-williamson"],"paras":[["h","Hugh Williamson to Samuel Johnston"],["p","Sir public New York 17th Octo. 1788."],["p","The length and frequency of the Letters, on public Affairs, with which I have taken the Liberty of troubling you would require an Apologie was it not that I had rather submit to a charge on this Account than be suspected of neglect of Duty or Inattention to the Interest of the State. With this you will receive a Copy of the printed Journal of Congress to the 1st Inst. Near the End of the Journal you will find the Report of a Committee who have taken much Pains to understand the Administration of the Treasury.1 The Operation of this Report compared with the Act of May 22nd may prove a salutary Lesson to Speculators & public Defaulters and may help to save our Constituents from the Tax of many a Dollar."],["p","The Secretary of Congress has doubtless forwarded an Act of Septr. 16th respecting the Practice of transporting convicted malefactors from foreign Countries.2 Inclosed is a Paper that respects a"],["p","late Importation of such People. On the last Year others had been Landed to the Eastward in Massachusits. Congress have complained to the British Court concerning the Cargo that was sent from New Providence; Perhaps a greater insult to any Nation could hardly have been offered."],["p","On the 13th Inst I wrote you in much Haste a Letter which may not have come to Hand. The Object was to inform you that the Board of Commissioners for settling Accounts between the several States and the Union can hardly be ready to proceed to Business before Feby or perhaps March next. My Information induces me to believe that three or four of the States cannot have given in all their Claims when the Time expires in which the District Commissioners are at Liberty to receive Claims; hence it will follow that those States will desire the Indulgence of more Time. I think it probable that North Carolina may wish for more Time to deliver in her Claims, in this Case the Delegates certainly will not fail to move for such a Resolution on the first Intimation from the State and I presume that a longer Day might readily be obtained."],["p","Our Affairs with the Western Indians wear a very gloomey Aspect. The Indians are coming very slowly to a Treaty, about this Time to be held at Muskingum and many of them have sent Word that they shall come Armed. The British at Detroit hearing of this Treaty have been giving the Indians considerable Presents though it was but a short Time since they had given them other Presents uncommonly large. A Party of Indians have lately attacked a Convoy of Provisions on the Wabash, killed ten continental Soldiers & wounded eight; they had some Weeks before that killed several continental Soldiers who were guarding Provisions. The Wabash Indians are daily bringing in Scalps. Genl. St. Clair the Governor of the Western Territory, who is holding the Treaty, has, in pursuance of a Vote of Congress requested of the Executive of Pennsylvania & Virginia to hold 1500 of their Militia in readiness to oppose the Indians & he has written to Congress some days ago that he fears the number mentioned will be insufficient.3"],["p","The British are tampering with the Indians on this Side and the Spaniards have lately, very exceptionably, presumed to hold a Treaty with Indians who live within the Territories of the United States. In this State of Indian Affairs, and considering that there is but a Handfull of national Troops in Service, I think it clear that North Carolina must depend on her own Prudence or her own strength for the Measure of Peace that she may enjoy with the neighbouring Indians."],["p","I have the Honour to be with the utmost Consideration, Sir, Your most obedient and very hble Servant, Hu Williamson"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v25.0524":{"title":"Thomas Nelson Jr. to John Page","author_label":"Thomas Nelson Jr.","kind":"letter","date":"1776-09-03","date_label":"September 3, 1776","date_type":"written","recipient":"John Page","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 25","source_url":"https://archive.org/details/lettersofdelegat25smit","scan_url":"https://archive.org/details/lettersofdelegat25smit/page/590","text_status":"unreviewed_ocr","editorial_source_note":"RC (NNPM: Gilder Lehrman Collection).","authors":["thomas-nelson-jr"],"paras":[["h","Thomas Nelson to John Page"],["p","My Dear Page Philada Sepr 3d 1776"],["p","I do not undertake this Letter with my wonted pleasure, when I have writen to you,1 because I cannot give you so favourable an account of our affairs at N. York as I could wish. Our Troops, after a bloody engagement upon Long Island, were obliged to retreat from thence the works not being teneable, 8c I wish they may not, nay I am certain they will, be obliged to quit the City of New York, as the hights upon the Island command the whole City. On the 27th of last Month the Enemy made an attack upon our Troops, who fought them twelve hours Be were at length obliged to give way, being overpower'd by"],["p","numbers & surrounded, by the Superior generalship of the Enemy, who stole a march upon us unperceiv'd. There was want of conduct somewhere, I do not mean in the Commander in Chief, for he was at New York & did not get over upon the Island till the mischief was almost done, or at least the foundation for it laid. We had General Sullivan taken prisoner & Brigadier Genl Lord Sterling, with several of our best field Officers. Our loss of Men killd & missing is suppos'd to be about 700. That of the Enemy at the least as many, some say more, but it is not ascertain'd yet."],["p","We had not more than 2,400 Men in the feild; the Enemy 10,000 & yet our Men kept them at bay the time I have mention'd & three companies of the Marylanders, with Major Gist at their head, forced their way thro' the Enemy 8c made their escape. Our Men behav'd like Heroes. The Engagement was principally in the field & we should have done very well with the Britons had not a cowardly rascal of a Lieutenant in the train of Artillery refus'd to fight after his Captain was wounded. Our Artillery was doing execution when this accident happen'd."],["p","We must give them up all the Islands untill we can get a Marine strong enough to defend them. We'll keep the Continent in spight of them."],["p","Every thing shall be done, to procure the passage of our accounts, that is in my power, which I hope to effect this week & you shall have a public Letter by the next post, upon them & such other matters as may occur in the interim."],["p","I am, with great sincerity, Yours &ca, Tho Nelson jr."]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."},"lod.v25.0674":{"title":"Abraham Clark's Accounts","author_label":"Abraham Clark","kind":"notes","date":"1782-11-15","date_label":"November 15, 1782","date_type":"written","edition":"Letters of Delegates to Congress, 1774-1789, ed. Paul H. Smith et al. (Library of Congress, 1976-2000), vol. 25","source_url":"https://archive.org/details/lettersofdelegat25smit","scan_url":"https://archive.org/details/lettersofdelegat25smit/page/738","text_status":"unreviewed_ocr","editorial_source_note":"MS (NNPM: Gilder Lehrman Collection). Written and signed by Abraham Clark.","authors":["abraham-clark"],"paras":[["h","Abraham Clark's Accounts"],["p","[November 15, 1782-October 31, 1783] The State of New Jersey, to Abraham Clark. Dr."],["p","1782 To my time in attending Congress from the 15th ) dollars day of Novemr. to the 4th day of January 1783 ' 204 including two days going to Philada. & my ( return home making 51 days at 4 dollars per day )"],["p","1783 To Attending Congress from the 25th February to I"],["p","the 25th day of June inclusive, including my going 480"],["p","and returning, making 120 days @ 4 dollars per day"],["p","To Attendance from July 7th to August 20th"],["p","inclusive except two days absent at home making j 172"],["p","43 days at 4 dollars per day"],["p","To Attendance from Septemr. 12th to Octor. 31 1"],["p","inclusive making 50 days @ 4 dollars per day I 200"],["p","Per Abra. Clark1"],["p","1,056"]],"layout_note":"Page numbers, running heads, line breaks and end-of-line hyphens from the printed page were removed; the words are as the OCR read them."}}});
